-- ═══════════════════════════════════════════════════════════════════════════
-- S113-A — el segundo Batch y las fichas por especie
--
-- 🔴 NADA SE REGENERA ACÁ. Los dos .json son la salida literal de las corridas
-- de D; esta migración las carga y **aplica una sola transformación: la voz**.
--
-- ── LA VOZ, Y POR QUÉ EL REEMPLAZO NO PUEDE SER CIEGO ───────────────────────
-- Firma del founder: «chicos» → «niños» (tuteo neutro; «chicos» es rioplatense).
-- **Pero «chicos» significa TAMBIÉN «pequeños»**, y en la carga anterior cinco
-- fichas lo usaban así — «espacios chicos», «grupos muy chicos». *Un
-- find-and-replace habría escrito «espacios niños» y nadie lo habría visto hasta
-- que una familia leyera la ficha.* Se reemplaza sólo cuando NO lo precede un
-- adjetivo de tamaño, y el control negativo de la verificación busca
-- exactamente esos engendros.
--
-- ── LAS 11 «POR ESPECIE» SON DOS COSAS DISTINTAS ────────────────────────────
-- Cinco apuntan a una fila que ya existe (`gato-comun`, `criollo` de perro y de
-- equino, `huron`, `otro`) y **cuatro de ellas rellenan justo las que el primer
-- Batch había dejado VACÍAS**: el modelo se negó, con razón, a escribir sobre
-- «Gato Común» como raza — y ahora escribe sobre el GATO. *No es la misma
-- pregunta y por eso ahora sí tiene respuesta.*
--
-- Las otras seis vienen con `raza_codigo` en null: **no tienen dónde colgar**.
-- Se les crea su fila `(<especie>, <especie>)` con **`activo = false`**, y eso
-- es una decisión, no un descuido: *la fila existe para sostener contenido, no
-- para ser elegida.* El selector ya ofrece «No sé» para quien no conoce la raza;
-- una entrada «Pez» al lado de las razas de pez sería la misma opción dos veces.
--
-- ⚠️ CONVENCIÓN QUE NACE ACÁ Y HAY QUE SABER: el contenido de una especie se
-- pide con `obtenerContenidoDeRaza(especie, especie)`. Queda escrito en el
-- wrapper.
--
-- ── LO QUE NO ENTRA, DECLARADO ──────────────────────────────────────────────
-- El segundo Batch rechazó dos (`samoyedo-blanco` por no parsear, `cane-corso`
-- por `cuidados.senior inválido`) y devolvió seis vacías por no reconocer la
-- raza. **Cinco de esas seis son razas que agregué yo el mismo día** — o sea que
-- la segunda red funcionó exactamente como se diseñó: entraron al selector y
-- **no van a mostrar un párrafo inventado**.
--
-- 76(g) — VEDA: NO RIGE. Inserción de contenido nuevo + seis filas de catálogo.
-- Cero backfill sobre datos de familias, cero anclas.
-- ═══════════════════════════════════════════════════════════════════════════
begin;

-- Las seis filas «por especie» que faltaban, apagadas en el selector.
insert into public.cat_razas (especie, slug, nombre, ruta_imagen, activo, creado_en_s113)
values
  ('pez','pez','Pez', null, false, true),
  ('roedor','roedor','Roedor', null, false, true),
  ('cobaya','cobaya','Cobaya', null, false, true),
  ('conejo','conejo','Conejo', null, false, true),
  ('ave','ave','Ave', null, false, true),
  ('reptil','reptil','Reptil', null, false, true)
on conflict (especie, slug) do nothing;

-- El segundo Batch: 108 fichas, todas apagadas.
insert into public.razas_contenido
  (especie, raza_codigo, conocida, origen, temperamento, talla_adulta,
   esperanza_vida, predisposiciones, cuidados_por_etapa, modelo, generado_el)
values
  ('conejo','belier-frances',true,'El Belier Francés se desarrolló en Francia a partir de conejos Belier ingleses, cruzados para lograr un animal más grande y robusto. Se lo criaba tanto por su carne como por su carácter tranquilo, lo que después lo convirtió en una raza muy elegida como mascota.','Suele ser un conejo calmo y sociable, que tolera bien el manejo y el contacto con las personas. Tiende a adaptarse a la vida en interior y a los niños, aunque como todo animal necesita tiempo para acostumbrarse a su familia. Su tamaño grande hace que algunos ejemplares sean algo menos ágiles pero no menos curiosos.','Entre 4 y 6 kg de peso, con orejas caídas que pueden superar los 45 cm de largo total.','Entre 5 y 8 años aproximadamente.',array['Problemas dentales por el crecimiento continuo de los dientes, algo para revisar periódicamente con el veterinario','Afecciones en las orejas caídas, que pueden acumular humedad o suciedad y conviene chequear con el veterinario','Sobrepeso, dado su tamaño grande y tendencia a la vida sedentaria, tema para conversar sobre alimentación con el veterinario','Problemas en las patas por su peso corporal, algo que el veterinario puede evaluar','Molestias digestivas relacionadas con el pelaje o la dieta, para consultar con el veterinario']::text[],'{"cachorro": "En esta etapa necesita una dieta adecuada para su crecimiento, con buen aporte de fibra, y contacto progresivo con las personas para sociabilizarlo. Es buen momento para que el veterinario revise su desarrollo general y sus orejas.", "adulto": "Necesita espacio suficiente para moverse, una dieta balanceada rica en fibra y control de peso, dado su tamaño. El cepillado regular ayuda con el pelaje, y las orejas conviene revisarlas seguido junto con el veterinario.", "senior": "En esta etapa puede reducir su actividad, por lo que hay que prestar atención a la alimentación para evitar el sobrepeso. Las visitas al veterinario conviene espaciarlas menos, para controlar dientes, articulaciones y estado general."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','braco-aleman',true,'El Braco Alemán se desarrolló en Alemania en el siglo XIX como perro de caza versátil, capaz de rastrear, señalar y cobrar piezas tanto en tierra como en agua. Se buscaba un perro polivalente para el cazador que necesitaba un solo animal para todas las tareas.','Suele ser un perro activo, atento y muy apegado a su familia, con ganas de participar en todo lo que se hace en casa. Tiene instinto de caza marcado, así que puede mostrar mucho interés por rastros y movimientos. Con buena socialización suele llevarse bien con niños y otros animales, aunque cada individuo tiene lo suyo.','Entre 20 y 32 kg, con una altura de 53 a 64 cm según sea macho o hembra.','Entre 10 y 12 años.',array['Displasia de cadera, algo para chequear con el veterinario sobre todo si es muy activo desde joven','Torsión gástrica, tema para hablar con el veterinario respecto a horarios y ritmo de comidas','Otitis, por sus orejas caídas conviene comentarlo en los controles','Problemas oculares, como entropión, que vale la pena revisar en las visitas de rutina','Hipotiroidismo, una condición a tener en cuenta con análisis periódicos']::text[],'{"cachorro": "Necesita socialización temprana y variada, con estímulos distintos y contacto con otros perros y personas. El ejercicio debe ser moderado y acorde a su edad, evitando saltos o esfuerzos fuertes mientras los huesos están en crecimiento. Es un buen momento para empezar a acostumbrarlo a la manipulación de orejas y patas, y para consultar al veterinario sobre el plan de alimentación y controles.", "adulto": "Requiere ejercicio diario intenso, tanto físico como mental, porque es un perro con mucha energía y necesidad de actividad. El pelaje es corto y fácil de mantener, con cepillado ocasional. Conviene mantener rutinas de alimentación estables y controles veterinarios regulares, prestando atención a las orejas y a los signos de malestar digestivo.", "senior": "Puede necesitar que el ejercicio se ajuste en intensidad, aunque muchos siguen queriendo moverse bastante. Es buen momento para prestar más atención a articulaciones, vista y peso corporal, y para charlar con el veterinario sobre chequeos más frecuentes. La calidez del hogar y la rutina conocida lo ayudan a sentirse cómodo en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','shar-pei',true,'El Shar Pei viene del sur de China, de una región cercana a Cantón, donde existe desde hace siglos. Se usaba como perro de granja para varias tareas, incluyendo guarda y caza, y en algún momento también en peleas, algo que ya no define a la raza actual.','Suele ser un perro independiente, tranquilo dentro de casa y muy apegado a su familia. Con los extraños tiende a mostrarse reservado o distante, y agradece una socialización temprana para no volverse desconfiado o territorial. No es un perro efusivo, pero sí leal y observador.','Entre 18 y 30 kilos, con una altura aproximada de 44 a 51 cm a la cruz.','Entre 9 y 11 años aproximadamente.',array['Pliegues cutáneos que pueden acumular humedad o irritarse, algo para revisar con el veterinario','Problemas oculares como entropión, vale la pena consultarlo desde cachorro','Alergias o sensibilidad de piel, un tema para conversar si aparecen picazón o rojeces','Displasia de cadera, conviene charlarlo en los controles de rutina','Fiebre periódica asociada a la raza, conocida como Shar Pei fever, para preguntarle al veterinario si notás episodios repetidos']::text[],'{"cachorro": "Es clave la socialización temprana con personas y otros animales, para que su reserva natural no se convierta en desconfianza excesiva. Los pliegues de la piel necesitan revisión frecuente para mantenerlos limpios y secos. El veterinario puede guiar sobre el crecimiento y la alimentación adecuada en esta etapa.", "adulto": "Necesita ejercicio moderado, paseos diarios y estímulos mentales, sin exigencias extremas. La piel y los pliegues requieren atención regular, y cualquier irritación conviene consultarla a tiempo. Es un buen momento para mantener controles veterinarios periódicos y una dieta acorde a su nivel de actividad.", "senior": "Puede reducir su energía y volverse más sedentario, por lo que el ejercicio se ajusta a su ritmo sin desaparecer del todo. La piel sigue necesitando cuidado constante, y los chequeos veterinarios ayudan a detectar a tiempo cambios propios de la edad. La alimentación puede necesitar ajustes, siempre con orientación profesional."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','pastor-de-shetland',true,'El Pastor de Shetland, también llamado Sheltie, viene de las Islas Shetland en Escocia, donde se usaba para arrear ovejas y otros animales de granja en terrenos difíciles. Es de estructura similar al Collie pero en tamaño reducido, adaptado a la vida en esas islas pequeñas y de recursos limitados.','Suele ser una raza atenta, inteligente y muy apegada a su familia, con fuerte instinto de trabajo y vigilancia. Tiende a ser algo reservado con extraños y puede ladrar bastante si no se trabaja eso desde cachorro. Le gusta tener tareas y estimulación mental, y en general se lleva bien con niños si se socializa a tiempo.','Entre 6 y 12 kg, con una altura de 33 a 41 cm aproximadamente.','Entre 12 y 14 años, aproximadamente.',array['Problemas oculares hereditarios, algo para revisar con el veterinario desde cachorro','Displasia de cadera','Sensibilidad a ciertos medicamentos, tema para conversar con el veterinario antes de cualquier tratamiento','Problemas de tiroides en la etapa adulta o senior','Dermatomiositis, una condición de piel que puede aparecer en cachorros de esta raza']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes para que el instinto de arreo y la tendencia a ladrar no se vuelvan un problema. El pelaje empieza a requerir cepillado regular desde chico para acostumbrarlo a la rutina. Conviene consultar al veterinario sobre el plan de vacunación y controles de crecimiento.", "adulto": "Necesita ejercicio diario, tanto físico como mental, ya que es una raza activa y con ganas de tener un propósito. El pelaje denso requiere cepillado frecuente, sobre todo en épocas de muda. Los chequeos veterinarios anuales ayudan a seguir de cerca su salud general.", "senior": "Los paseos pueden espaciarse o acortarse según su energía, pero sigue siendo importante mantenerlo activo dentro de sus posibilidades. Hay que estar atento a cambios en la vista, la movilidad o el peso, y consultarlos con el veterinario. Los controles periódicos se vuelven más frecuentes en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','briard',true,'El Briard es una raza francesa antigua, criada durante siglos como perro pastor y guardián de rebaños en el campo francés. Se destacaba por su capacidad de trabajar largas jornadas y proteger al ganado por su cuenta.','Suele ser un perro leal y muy apegado a su familia, aunque puede mostrarse reservado o desconfiado con extraños. Tiene instinto protector y necesita socialización temprana para relacionarse bien con otras personas y animales. Es inteligente y aprende rápido, aunque también puede ser algo independiente a la hora de obedecer.','Entre 33 y 40 kg, con una altura que va de 56 a 68 cm según el sexo.','Entre 10 y 12 años.',array['Displasia de cadera, algo para chequear con el veterinario en controles periódicos','Torsión gástrica, conviene conversar con el veterinario sobre pautas de alimentación y ejercicio','Problemas oculares hereditarios, vale la pena consultarlo en los chequeos de rutina','Estenosis pulmonar, un tema para preguntar en las visitas veterinarias']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes para evitar que la desconfianza natural de la raza se vuelva un problema. El pelaje largo empieza a requerir cepillado frecuente desde chico para que no se enrede. Es buen momento para consultar con el veterinario sobre alimentación y el plan de vacunas.", "adulto": "Requiere ejercicio diario constante, ya que es un perro con energía y necesidad de actividad física y mental. El pelaje demanda cepillado regular, varias veces por semana, para evitar nudos. Mantener controles veterinarios periódicos ayuda a seguir de cerca su salud general.", "senior": "Puede necesitar rutinas de ejercicio más suaves, adaptadas a su movilidad y ritmo. El cuidado del pelaje sigue siendo importante, prestando atención a la piel debajo del manto. Es buen momento para aumentar la frecuencia de visitas al veterinario y estar atento a cualquier cambio en su comportamiento o movilidad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','perro-sin-pelo-del-peru',true,'Es una raza originaria del Perú, con presencia desde épocas preincaicas, donde se la encuentra representada en cerámicas y tumbas de culturas antiguas. Se la valoraba como compañía y también se le atribuía un rol en la medicina tradicional por el calor de su piel.','Suele ser un perro afectuoso con su familia y algo reservado o desconfiado con extraños. Es activo, alerta y bastante apegado a las personas con las que convive, aunque cada ejemplar tiene su propio carácter.','Entre 4 y 25 kg y entre 25 y 60 cm de altura, según la variedad (pequeña, mediana o grande).','Entre 11 y 14 años aproximadamente.',array['Sensibilidad de la piel ante el sol y el frío, algo para charlar con el veterinario sobre protección adecuada','Posible presencia de comedones o acné, un tema para consultar en los controles de piel','Ausencia total o parcial de dientes en algunos ejemplares, bueno revisarlo con el veterinario','Tendencia a golpes o lastimaduras en la piel al no tener pelo que la proteja','Sensibilidad ocular ocasional, conviene que el veterinario la evalúe en los chequeos']::text[],'{"cachorro": "Necesita socialización temprana para ganar confianza con personas y otros animales. La piel del cachorro es delicada, así que conviene cuidarla del sol y del frío desde el principio. Es buen momento para que el veterinario arme un plan de controles y alimentación.", "adulto": "Requiere ejercicio diario y estímulo mental, ya que es un perro despierto y activo. La piel necesita cuidado regular, con protección solar en verano y abrigo en invierno. Los chequeos veterinarios periódicos ayudan a seguir de cerca la piel, los dientes y los ojos.", "senior": "Puede necesitar rutinas de ejercicio más suaves y adaptadas a su ritmo. La piel y la vista suelen requerir más atención en esta etapa, así que los controles veterinarios conviene espaciarlos menos. Mantener el confort térmico, evitando frío y sol directo, se vuelve más importante con la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','basset-hound',true,'El Basset Hound se originó en Francia, descendiente de sabuesos usados para rastrear liebres y conejos. Su cuerpo bajo y su olfato desarrollado le permitían seguir rastros a paso constante mientras los cazadores lo acompañaban a pie. Llegó a Inglaterra en el siglo XIX, donde se consolidó como raza.','Suele ser un perro tranquilo, afectuoso y bastante paciente con los niños de la casa. Tiene un carácter algo terco cuando algo le interesa, sobre todo si detecta un olor que seguir. Es sociable con otros perros y disfruta de la compañía, aunque no busca ser hiperactivo.','Entre 20 y 29 kg, con una altura de 33 a 38 cm en la cruz.','Entre 10 y 12 años.',array['Problemas de columna, algo para conversar con el veterinario dado su cuerpo alargado y patas cortas','Infecciones de oído, por la forma caída y larga de sus orejas','Displasia de cadera','Obesidad, si la alimentación y el ejercicio no se equilibran bien','Problemas oculares, como el ectropión o entropión']::text[],'{"cachorro": "Necesita socialización temprana y paseos cortos, evitando saltos o escaleras que fuercen su columna todavía en desarrollo. La alimentación debe ser controlada para que no crezca demasiado rápido. Conviene empezar a limpiar sus orejas con regularidad y consultar al veterinario sobre el plan de vacunación.", "adulto": "Los paseos diarios moderados le ayudan a mantener un peso saludable, algo clave para cuidar su espalda y articulaciones. El pelaje es corto y fácil de mantener, pero las orejas necesitan revisión frecuente. Es buen momento para chequeos veterinarios periódicos y para vigilar la alimentación, ya que tiende a engordar con facilidad.", "senior": "Con la edad puede volverse menos activo y más sensible a los cambios de rutina. Convine mantener paseos suaves y adaptar la dieta según indique el veterinario. Los controles regulares ayudan a detectar a tiempo molestias articulares o de columna, frecuentes en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('equino','cuarto-de-milla',true,'Se originó en Estados Unidos durante la época colonial, cruzando caballos ingleses con ejemplares de origen español. Se la crió para trabajo de rancho, carreras cortas de un cuarto de milla (de ahí su nombre) y como caballo versátil para el campo.','Suele ser un caballo tranquilo y dispuesto a trabajar, con buena disposición hacia las personas. Tiende a ser inteligente y a aprender rápido, lo que lo hace manejable en distintas tareas. Como en toda raza, el carácter individual varía según la crianza y el manejo.','Entre 450 y 550 kg de peso, con una alzada aproximada de 1,42 a 1,60 metros.','Entre 25 y 30 años.',array['Ciertas afecciones oculares hereditarias, algo para comentar con el veterinario','Predisposición a problemas musculares relacionados con el almacenamiento de glucógeno, tema para conversar con el veterinario','Tendencia a laminitis en algunos ejemplares, tema para revisar con el veterinario','Tendencia a problemas de cascos si el manejo o el terreno no son los adecuados','Cierta predisposición a atrofia muscular hereditaria, algo para consultar con el veterinario']::text[],'{"cachorro": "El potrillo necesita espacio para moverse y socializar con otros caballos desde temprano. La alimentación debe acompañar su crecimiento sin acelerarlo de más, y conviene que el veterinario haga un seguimiento regular de su desarrollo.", "adulto": "Necesita ejercicio regular acorde a su uso, ya sea trabajo, deporte o simple actividad diaria. El pelaje y los cascos requieren revisión periódica, y una dieta equilibrada según su nivel de actividad ayuda a mantenerlo en buen estado.", "senior": "Con los años puede necesitar ajustes en la dieta y menor exigencia física. Las visitas al veterinario conviene que sean más frecuentes para controlar articulaciones, dientes y estado general."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','lhasa-apso',true,'El Lhasa Apso viene del Tíbet, donde se lo criaba para vigilar el interior de monasterios y hogares, dando aviso ante cualquier visita. Se lo consideraba casi sagrado y se regalaba como símbolo de buena fortuna. Su pelaje largo lo ayudaba a soportar el clima frío de la meseta tibetana.','Suele ser un perro independiente y alerta, con fuerte instinto de guardián a pesar de su tamaño pequeño. Es leal a su familia pero puede mostrarse reservado o desconfiado con extraños. Con buena socialización desde cachorro convive bien en el hogar, aunque conserva cierta terquedad propia de la raza.','Entre 5 y 8 kg de peso, con una altura de 25 a 28 cm aproximadamente.','Entre 12 y 15 años.',array['Problemas oculares como queratitis o cataratas, para chequear en controles regulares','Displasia de cadera, algo para conversar con el veterinario según su actividad','Afecciones renales que pueden presentarse en algunos ejemplares','Problemas dermatológicos vinculados al tipo de pelaje','Obstrucción de conductos lagrimales, algo que el veterinario puede evaluar']::text[],'{"cachorro": "Es clave socializarlo temprano con personas y otros animales para suavizar su tendencia a la desconfianza. El pelaje empieza a requerir cepillado frecuente desde chico para que no se acostumbre mal al manejo. Las consultas veterinarias tempranas ayudan a seguir su desarrollo general.", "adulto": "Necesita paseos moderados, no es una raza que demande ejercicio intenso pero sí estimulación mental. El cepillado regular es fundamental para evitar nudos y mantener la piel sana. Conviene mantener controles veterinarios periódicos, sobre todo de ojos y piel.", "senior": "Puede reducir su energía y volverse algo más sedentario, por lo que conviene ajustar la alimentación y el ritmo de paseos. Los chequeos veterinarios más frecuentes ayudan a detectar cambios en la vista, los riñones o las articulaciones. El pelaje sigue necesitando cuidado, aunque algunas familias optan por mantenerlo más corto en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('ave','amazona-frentiazul',true,'La Amazona Frentiazul es originaria de Sudamérica, principalmente de Argentina, Bolivia, Paraguay y Brasil. Se la conoce también como loro hablador o Amazona aestiva, y históricamente fue muy popular como ave de compañía por su facilidad para imitar sonidos y palabras.','Suele ser un ave inteligente, curiosa y muy sociable con su familia humana. Puede formar vínculos fuertes con una persona en particular y mostrarse territorial en la época reproductiva. Necesita estímulo mental constante porque el aburrimiento suele derivar en comportamientos como gritar o arrancarse plumas.','Entre 350 y 450 gramos, con una longitud de 35 a 38 centímetros aproximadamente.','Entre 50 y 80 años en cautiverio con buenos cuidados.',array['Problemas de comportamiento como el picaje de plumas, algo para conversar con el veterinario o un especialista en aves','Enfermedades respiratorias, conviene consultar ante cualquier cambio en la respiración o el canto','Obesidad y problemas hepáticos asociados a dietas inadecuadas, tema para charlar con el veterinario sobre la alimentación','Deficiencias nutricionales cuando la dieta es solo a base de semillas, bueno revisarlo con un profesional','Infecciones por hongos o bacterias, especialmente si el ambiente no es el adecuado, algo para monitorear con el veterinario']::text[],'{"cachorro": "En la etapa joven es clave la socialización temprana con distintas personas y estímulos para que sea un ave equilibrada de adulta. Necesita una dieta variada más allá de las semillas, con frutas y verduras frescas, y siempre es bueno consultar con el veterinario sobre la alimentación específica. El juego y el contacto diario ayudan a formar un vínculo de confianza.", "adulto": "Un adulto necesita tiempo diario fuera de la jaula para volar o moverse, y juguetes que lo mantengan mentalmente activo. La dieta debe ser balanceada y variada, evitando el exceso de grasas. Los chequeos veterinarios periódicos ayudan a detectar a tiempo cualquier cambio en su salud o comportamiento.", "senior": "Con los años puede reducir su nivel de actividad y es importante observar cambios en el apetito, el plumaje o la movilidad para consultarlo con el veterinario. Mantener el enriquecimiento ambiental sigue siendo importante aunque el ave esté menos activa. Los controles veterinarios más frecuentes ayudan a acompañar mejor esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','fox-terrier',true,'El Fox Terrier se originó en Inglaterra en el siglo XIX, criado para desenterrar zorros y ayudar en la caza acompañando a los perros de rastro. Existen dos variedades, pelo liso y pelo duro, ambas con el mismo fondo de trabajo. Fue seleccionado por su valentía y su capacidad para meterse en madrigueras.','Es un perro despierto, activo y con mucha iniciativa propia, algo esperable en una raza criada para trabajar sin supervisión constante. Suele ser cariñoso con su familia, aunque puede mostrarse independiente y terco a la hora de obedecer. Tiene fuerte instinto de caza, así que la convivencia con otros animales pequeños conviene pensarla con cuidado.','Entre 7 y 9 kilos, con una altura aproximada de 35 a 39 centímetros a la cruz.','Entre 12 y 15 años.',array['Luxación de rótula, algo para chequear en controles de rutina','Problemas de cadera, conviene hablarlo con el veterinario según la actividad del perro','Sordera congénita, más frecuente en ejemplares con manchas blancas amplias','Afecciones oculares hereditarias, vale mencionarlo en los chequeos periódicos','Sensibilidad de piel en la variedad de pelo duro, un tema para consultar si aparecen irritaciones']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros perros y distintos ambientes, dado su temperamento independiente. La energía es alta desde chico, así que conviene canalizarla con juegos y estímulos mentales además del ejercicio físico. Cualquier duda sobre desarrollo óseo o vacunación es mejor consultarla con el veterinario.", "adulto": "Requiere ejercicio diario constante, tanto físico como mental, porque se aburre fácil y puede volverse destructivo si le falta actividad. El pelaje, sea liso o duro, pide cepillado regular, y la variedad de pelo duro suele necesitar stripping periódico. Es buen momento para mantener controles veterinarios regulares y una alimentación acorde a su nivel de actividad.", "senior": "Con la edad baja el nivel de energía, pero sigue siendo importante mantener paseos moderados y estimulación mental. Conviene prestar atención a cambios en la movilidad o la vista, y llevarlos a revisión veterinaria si aparecen. Los chequeos periódicos ayudan a detectar a tiempo cuestiones propias de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','schnauzer-miniatura',true,'El Schnauzer Miniatura viene de Alemania, donde se lo desarrolló en el siglo XIX a partir del Schnauzer estándar cruzado con razas más pequeñas. Se lo criaba como perro de granja y guardián, principalmente para controlar roedores.','Suele ser un perro alerta, inteligente y apegado a su familia. Tiende a ser bueno con los niños y a adaptarse bien a la vida en departamento, aunque puede mostrarse desconfiado con extraños y ladrar ante cualquier novedad. Con estímulo mental y buena socialización suele convivir bien con otros animales.','Entre 5 y 9 kg de peso, con una altura aproximada de 30 a 36 cm a la cruz.','Entre 12 y 15 años.',array['Problemas oculares como cataratas, algo para revisar con el veterinario en controles periódicos','Pancreatitis o sensibilidad digestiva, un tema para conversar sobre la alimentación','Cálculos urinarios, conviene comentarlo con el veterinario si hay antecedentes','Hipotiroidismo, algo a tener en cuenta en chequeos de rutina','Afecciones cardíacas, para conversar con el veterinario en los controles anuales']::text[],'{"cachorro": "Es clave exponerlo a distintas personas, animales y situaciones para que crezca seguro y no desarrolle un ladrido excesivo. El pelaje necesita cepillado regular desde pequeño para acostumbrarlo a la manipulación, y conviene consultar al veterinario sobre el plan de vacunación y alimentación adecuada para esta etapa.", "adulto": "Necesita paseos diarios y algo de estímulo mental, ya que es un perro activo e inteligente que se aburre fácil. El pelaje requiere cortes periódicos en la peluquería, y es buen momento para chequeos veterinarios anuales que incluyan control de peso y salud general.", "senior": "Puede reducir su nivel de actividad pero sigue necesitando paseos moderados y estimulación. Es recomendable aumentar la frecuencia de visitas al veterinario para monitorear la vista, el corazón y otros temas asociados a la edad, y ajustar la alimentación según indique el profesional."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('gato','balines',true,'El balinés surgió en Estados Unidos a mediados del siglo XX a partir de siamés de pelo largo. Se lo crió para conservar la elegancia y el carácter del siamés pero con un pelaje más largo y sedoso. No tiene relación con Bali, el nombre se eligió por la gracia de sus movimientos.','Suele ser un gato sociable y muy comunicativo, con tendencia a vocalizar bastante para interactuar con su familia. Se encariña con sus personas y busca estar cerca, participando de las actividades de la casa. Es activo y curioso, y en general le gusta la compañía, tanto humana como de otros animales.','Entre 3 y 5 kilos, contextura mediana y cuerpo alargado y estilizado.','Entre 12 y 16 años.',array['Problemas cardíacos hereditarios, algo para chequear con el veterinario de forma periódica','Estrabismo o alteraciones oculares leves, típicas de la línea siamesa','Sensibilidad respiratoria o asma felina, vale la pena conversarlo si aparecen síntomas','Amiloidosis hepática, una condición para tener en cuenta con controles regulares','Tendencia a la formación de nudos en el pelaje si no se lo cepilla con frecuencia']::text[],'{"cachorro": "Necesita mucha socialización temprana porque es un gato que va a demandar atención toda su vida. Conviene ofrecerle juegos interactivos desde chico y empezar pronto con el cepillado para que se acostumbre a la rutina. Es un buen momento para charlar con el veterinario sobre el plan de vacunación y controles de crecimiento.", "adulto": "Es un gato activo que disfruta de estímulos mentales y espacios para trepar u observar. El pelaje semilargo pide cepillado regular, aunque no tan intenso como el de un persa. Las visitas periódicas al veterinario ayudan a monitorear el corazón y otros temas asociados a la raza.", "senior": "Con la edad puede bajar su nivel de actividad, aunque suele mantener las ganas de estar cerca de su familia. Es importante prestar atención a cambios en el apetito, la movilidad o la voz, y consultarlos con el veterinario. Los controles regulares cobran más importancia para detectar a tiempo cualquier tema de salud propio de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','kerry-blue-terrier',true,'El Kerry Blue Terrier es originario del condado de Kerry, en Irlanda, donde se lo usaba como perro de granja para cazar alimañas, pastorear y vigilar. Es uno de los terrier de mayor tamaño entre los de origen irlandés.','Suele ser un perro inteligente, activo y muy apegado a su familia. Tiene el carácter típico de terrier: puede ser testarudo y territorial con otros perros si no se socializa bien desde cachorro. Con las personas que conoce suele mostrarse leal y cariñoso.','Entre 15 y 18 kg de peso y entre 44 y 49 cm de altura a la cruz.','Entre 12 y 15 años aproximadamente.',array['Displasia de cadera, algo para chequear con el veterinario en controles periódicos','Problemas oculares como cataratas, conviene consultarlo en los chequeos anuales','Hipotiroidismo, tema para conversar si aparecen cambios de energía o de peso','Ciertas afecciones de piel, vale la pena mencionarlo si hay picazón o irritación persistente','Enfermedades neurológicas hereditarias poco frecuentes, algo para preguntarle al veterinario si surge alguna duda']::text[],'{"cachorro": "Necesita socialización temprana con otros perros y personas para equilibrar su carácter terrier. El pelaje rizado requiere cepillado frecuente desde chico para que no se enrede. Es un buen momento para empezar los controles veterinarios de rutina y planificar la esterilización si la familia lo decide.", "adulto": "Requiere ejercicio diario, tanto físico como mental, porque es un perro con energía y necesidad de estímulo. El pelaje no se cae mucho pero crece continuamente, así que necesita cortes regulares en la peluquería. Los chequeos veterinarios anuales ayudan a seguir de cerca su salud general.", "senior": "Puede necesitar paseos más cortos y tranquilos, adaptados a su ritmo. El pelaje sigue necesitando mantenimiento regular. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a la vista, las articulaciones y el peso."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('equino','arabe',true,'El árabe es una de las razas de caballo más antiguas, originaria de la península arábiga, donde los pueblos beduinos la criaron durante siglos para resistencia y velocidad en el desierto. Se usaba para desplazamientos largos, guerra y como compañero cercano a las familias. Hoy es base de muchas otras razas y se usa en enduro, exhibición y equitación general.','Suele ser un caballo despierto, sensible y con mucha disposición para trabajar junto a las personas. Tiende a formar vínculos estrechos con quien lo cuida y a responder bien a un trato basado en confianza más que en imposición. Puede ser enérgico, así que agradece manejo constante y experimentado.','Entre 350 y 450 kilos, con una alzada aproximada de 1,40 a 1,55 metros al morro.','Entre 25 y 30 años, con buen manejo general.',array['Ciertas miopatías musculares hereditarias, para charlar con el veterinario sobre estudios genéticos disponibles','Síndrome de inmunodeficiencia combinada severa (SCID), relevante sobre todo para planes de cría','Sensibilidad cutánea o alergias en algunos ejemplares','Problemas oculares hereditarios en ciertas líneas','Tendencia a la delgadez o dificultad para ganar peso en algunos individuos']::text[],'{"cachorro": "El potrillo necesita espacio para moverse libremente y contacto temprano con otros caballos para socializar bien. La alimentación debe acompañar su crecimiento sin apurarlo, y conviene que el veterinario guíe el plan nutricional y de vacunación. El manejo suave desde pequeño facilita mucho el trabajo futuro.", "adulto": "Necesita ejercicio regular acorde a su nivel de entrenamiento, ya sea trabajo, paseo o actividad deportiva. El pelaje y los cascos piden revisión periódica, y una dieta equilibrada ayuda a mantener su energía sin excesos. Los controles veterinarios de rutina son clave para detectar cualquier tema a tiempo.", "senior": "Con la edad puede necesitar ajustes en la dieta y en la intensidad del ejercicio, siempre manteniendo cierta actividad si su salud lo permite. Conviene prestar atención a la dentadura, las articulaciones y el peso, consultando al veterinario ante cualquier cambio. El contacto social sigue siendo importante para su bienestar."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('cobaya','cobaya-skinny',true,'La cobaya Skinny surgió en Canadá en la década de 1970, a partir de una mutación espontánea en un centro de investigación de Montreal, sin pelo o casi sin pelo. No se criaba con un fin de trabajo, sino que se popularizó como mascota y también se usó en algunos estudios de dermatología.','Suele ser una cobaya curiosa y sociable, que busca bastante contacto con las personas, en parte porque necesita más calor corporal. Convive bien en pareja o grupo de su especie. Como cualquier cobaya, agradece un entorno tranquilo y manejo suave, sobre todo al principio.','Entre 350 y 700 gramos aproximadamente, con un cuerpo similar en tamaño al de una cobaya de pelo, unos 20 a 25 cm de largo.','Entre 5 y 7 años aproximadamente.',array['Sensibilidad de la piel a golpes, rozaduras y quemaduras solares, algo para revisar con el veterinario','Mayor tendencia a perder temperatura corporal, tema a conversar sobre el ambiente donde vive','Predisposición a problemas dentales típica de la especie, para controlar en visitas periódicas','Tendencia a afecciones respiratorias si el ambiente no es el adecuado, para charlar con el veterinario','Piel más expuesta a hongos o irritaciones, conviene que el veterinario la revise si aparecen cambios']::text[],'{"cachorro": "Necesita un espacio cálido, sin corrientes de aire, porque al no tener pelo pierde calor más rápido. La socialización temprana con manejo suave ayuda a que sea una cobaya confiada. La alimentación en esta etapa la conviene definir el veterinario, junto con los controles de crecimiento.", "adulto": "Vive bien con una dieta rica en fibra, heno disponible todo el día y espacio para moverse. La piel necesita chequeos visuales frecuentes por rozaduras o resequedad, y el ambiente debe mantenerse a una temperatura estable. Las visitas periódicas al veterinario ayudan a seguir de cerca la salud dental y de piel.", "senior": "Suele necesitar más atención a la temperatura ambiente y a la calidad del descanso. Conviene observar cambios en el apetito, la movilidad o la piel y comentarlos con el veterinario. Los controles se hacen un poco más frecuentes para acompañar mejor esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','setter-irlandes',true,'El Setter Irlandés se desarrolló en Irlanda durante el siglo XVIII como perro de caza, especializado en localizar aves mediante el olfato y quedarse quieto señalando la presa. Su pelaje rojizo característico y su elegancia lo convirtieron también en perro de compañía y de exposición.','Suele ser afectuoso, sociable y muy activo, con buena disposición hacia los niños y otros animales. Tiende a ser algo independiente y puede distraerse con facilidad si detecta olores o estímulos interesantes. Necesita contacto frecuente con su familia y no lleva bien la soledad prolongada.','Entre 27 y 32 kilos, con una altura de 58 a 67 centímetros aproximadamente.','Entre 12 y 14 años.',array['Displasia de cadera, algo para chequear con el veterinario en controles regulares','Torsión gástrica, tema para conversar especialmente por su contextura profunda de pecho','Hipotiroidismo, conviene mencionarlo si se notan cambios de energía o peso','Otitis, por sus orejas caídas que retienen humedad','Problemas oculares hereditarios, bueno consultarlo en revisiones periódicas']::text[],'{"cachorro": "Necesita socialización temprana y estímulos variados, ya que es una etapa clave para su desarrollo emocional. El ejercicio debe ser moderado para no forzar articulaciones en crecimiento, y conviene consultar con el veterinario un plan de alimentación acorde a su ritmo de crecimiento.", "adulto": "Requiere ejercicio diario intenso, ya que es una raza con mucha energía y resistencia. El pelaje necesita cepillado frecuente para evitar nudos, y las orejas deben revisarse periódicamente para prevenir humedad excesiva.", "senior": "El ejercicio puede mantenerse pero ajustando la intensidad según su movilidad y lo que indique el veterinario. Es buen momento para chequeos regulares de articulaciones, vista y tiroides. La alimentación también puede necesitar ajustes, siempre con orientación profesional."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','saluki',true,'El saluki es una de las razas de galgo más antiguas que se conocen, originaria de Oriente Medio, donde se usaba para cazar liebres y gacelas en el desierto junto a los beduinos. Durante siglos fue valorado por su velocidad y resistencia más que por su aspecto.','Suele ser un perro reservado y algo distante con los desconocidos, pero muy apegado a su familia. Tiene un fuerte instinto de caza, así que puede salir corriendo tras algo en movimiento sin previo aviso. Con su gente suele mostrarse tranquilo y sensible, no es un perro que busque atención constante.','Entre 18 y 30 kilos, con una altura de 58 a 71 centímetros según sea macho o hembra.','Entre 12 y 14 años.',array['Sensibilidad a ciertos anestésicos y medicamentos, algo típico de razas galgo con poca grasa corporal, para comentar con el veterinario antes de cualquier procedimiento','Problemas cardíacos, vale la pena chequear periódicamente con el veterinario','Displasia de cadera, aunque es menos común que en otras razas de su tamaño','Hipotiroidismo, conviene tenerlo en cuenta si aparecen cambios de energía o de peso','Sensibilidad digestiva, algunos saluki responden mejor a cambios graduales de alimentación']::text[],'{"cachorro": "Necesita socialización temprana para acostumbrarse a distintos estímulos, dado su carácter reservado. El ejercicio debe ser moderado mientras crece, evitando saltos o corridas muy intensas hasta que el desarrollo óseo esté más avanzado, algo para charlar con el veterinario según el caso. Es un buen momento para trabajar la llamada, aunque el instinto de caza puede complicar esto más adelante.", "adulto": "Necesita corridas regulares en espacios seguros y cerrados, ya que su velocidad lo puede llevar lejos si algo capta su atención. El pelaje es corto y de mantenimiento simple, con cepillado ocasional. La alimentación debe ajustarse a su nivel de actividad, que suele ser alto en ráfagas cortas.", "senior": "Los paseos pueden mantenerse pero con menor intensidad, respetando su ritmo. Es buen momento para chequeos veterinarios más frecuentes, sobre todo pensando en el corazón y las articulaciones. La comodidad importa: colchones blandos ayudan a un cuerpo con poca grasa corporal a descansar mejor."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','galgo-espanol',true,'El Galgo Español es una raza muy antigua originaria de la Península Ibérica, criada tradicionalmente para la caza de liebres gracias a su velocidad y vista aguda. Durante siglos fue el perro de caza por excelencia en el campo español.','Suele ser tranquilo y hasta reservado dentro de casa, muchas veces más parecido a un gato en su forma de estar. Con su familia tiende a ser afectuoso y sensible, aunque con extraños puede mostrarse tímido si no fue bien socializado. Tiene fuerte instinto de persecución ante animales pequeños en movimiento.','Entre 20 y 30 kilos, con una altura aproximada de 60 a 70 cm a la cruz.','Entre 12 y 15 años.',array['Sensibilidad a ciertos anestésicos y medicamentos, algo para comentar antes de cualquier procedimiento','Problemas dentales, por lo que conviene consultar sobre el cuidado bucal','Bajo porcentaje de grasa corporal, lo que puede hacerlo más sensible al frío, tema para charlar con el veterinario','Predisposición a lesiones musculares o de piel por su contextura delgada','Cardiopatías, algo que puede evaluarse en controles de rutina']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros perros y distintos ambientes para ganar confianza. El ejercicio debe ser moderado mientras crecen los huesos, evitando saltos o carreras muy intensas. Es buen momento para consultar con el veterinario un plan de alimentación acorde a su crecimiento.", "adulto": "Agradece salidas donde pueda correr libremente en espacios seguros, combinadas con paseos tranquilos diarios. Su pelaje corto requiere poco mantenimiento, aunque en climas fríos puede necesitar abrigo. Conviene mantener controles veterinarios periódicos y estar atento a su peso y estado dental.", "senior": "Los paseos pueden acortarse pero siguen siendo importantes para mantener movilidad y ánimo. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a articulaciones y corazón. El descanso en superficies blandas ayuda a cuidar su cuerpo delgado."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','american-staffordshire-terrier',true,'Es una raza desarrollada en Estados Unidos durante el siglo XIX, a partir de cruces entre terriers y molosoides traídos de Inglaterra. Se la usó originalmente para peleas y como perro de granja, un pasado que hoy no define en absoluto a los ejemplares de compañía. Con el tiempo se convirtió en un perro de familia muy popular en varios países.','Suele ser un perro afectuoso y muy apegado a su familia, con ganas de estar cerca de las personas todo el tiempo. Tiene energía y necesita estímulo físico y mental, porque el aburrimiento le sienta mal. Con otros perros puede mostrarse dominante o poco tolerante, así que la socialización temprana es clave.','Entre 25 y 30 kilos, con una altura de 43 a 48 cm aproximadamente.','Entre 12 y 16 años.',array['Displasia de cadera, algo para chequear con el veterinario en controles periódicos','Problemas de piel y alergias, que conviene consultar si aparecen picazón o irritaciones frecuentes','Afecciones cardíacas congénitas, un tema para hablar con el veterinario desde cachorro','Problemas oculares hereditarios, que se pueden monitorear en las visitas de rutina','Hipotiroidismo, una condición para tener en cuenta si aparecen cambios de peso o energía']::text[],'{"cachorro": "Necesita socializar mucho y temprano, con personas, otros perros y distintos ambientes, para desarrollar un carácter equilibrado. El ejercicio debe ser moderado mientras crece, evitando saltos o esfuerzos fuertes que puedan afectar las articulaciones en desarrollo. Es buen momento para empezar controles veterinarios regulares y planificar la alimentación con orientación profesional.", "adulto": "Es una etapa de mucha energía, así que necesita ejercicio diario constante, tanto físico como mental. El pelaje corto es fácil de mantener, con cepillado ocasional. Conviene sostener chequeos veterinarios anuales para monitorear peso, articulaciones y salud general.", "senior": "Los paseos pueden acortarse pero conviene mantenerlos, adaptando el ritmo a lo que el perro pida. Es buen momento para prestar atención a signos de dolor articular o cambios de comportamiento, y comentarlos con el veterinario. Los controles de salud más frecuentes ayudan a detectar a tiempo cualquier tema que necesite atención."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('otro','otro',false,null,null,null,null,'{}','{"cachorro": null, "adulto": null, "senior": null}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','bloodhound',true,'El Bloodhound viene de Europa, con raíces que se remontan a monasterios medievales en Francia y Bélgica, y se perfeccionó en Inglaterra. Se lo crió específicamente por su capacidad de rastreo, considerada una de las más finas entre todas las razas caninas. Se usaba y todavía se usa para seguir rastros de personas a largas distancias.','Es un perro tranquilo y afectuoso en casa, aunque puede mostrarse algo testarudo cuando algo le interesa, sobre todo un olor. Suele ser bueno con los niños y sociable con otros perros si se lo socializa bien desde cachorro. Una vez que agarra un rastro, cuesta mucho distraerlo, así que en exteriores conviene tenerlo siempre con correa.','Entre 36 y 50 kilos, con una altura de 58 a 69 cm a la cruz.','Entre 7 y 10 años.',array['Torsión gástrica, algo para hablar con el veterinario sobre cómo organizar las comidas','Displasia de cadera y codo','Problemas oculares como el ectropión o entropión','Otitis, por la forma y el tamaño de sus orejas caídas','Problemas de piel en los pliegues de la cara']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes, ya que su instinto de rastreo es muy fuerte desde chico. El crecimiento debe ser gradual, evitando ejercicio excesivo o saltos que fuercen las articulaciones todavía en desarrollo. Conviene consultar al veterinario sobre el tipo de alimentación más adecuado para una raza grande.", "adulto": "Requiere paseos largos y actividades de rastreo o búsqueda que le den un estímulo mental, además del físico. Sus orejas y los pliegues faciales necesitan revisión y limpieza regular para evitar infecciones. La alimentación y las porciones conviene ajustarlas con el veterinario, dado el riesgo de torsión gástrica.", "senior": "Baja naturalmente el ritmo, por lo que los paseos pueden acortarse pero conviene mantenerlos constantes para las articulaciones. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a la movilidad y la vista. El pelaje y la piel de los pliegues siguen necesitando cuidado regular."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('conejo','gigante-de-flandes',true,'Es una raza originaria de la región de Flandes, entre Bélgica y Francia, desarrollada a partir del siglo XVI. Se la criaba tanto por su carne como por su piel, y con el tiempo se convirtió en una de las razas de conejo doméstico más grandes que existen.','Suele ser un conejo tranquilo y de trato dócil, que tolera bien el contacto humano cuando se lo socializa desde chico. Por su tamaño conviene que los niños aprendan a manipularlo con cuidado. Cada ejemplar tiene su propio carácter, y algunos son más independientes que otros.','Entre 6 y 10 kg de peso, pudiendo llegar más de 70 cm de largo en su versión más grande.','Entre 5 y 8 años aproximadamente.',array['Problemas en las patas por el peso corporal sobre superficies duras, para conversar con el veterinario sobre el tipo de piso adecuado','Afecciones cardíacas asociadas a razas grandes, vale la pena mencionarlo en los controles','Problemas dentales, como en la mayoría de los conejos, algo para revisar periódicamente','Predisposición a golpe de calor por su tamaño y masa corporal','Dificultades de movilidad en la vejez, tema para charlar con el veterinario a medida que crece']::text[],'{"cachorro": "Necesita un espacio amplio desde chico para desarrollarse bien, ya que va a crecer bastante más que un conejo común. La socialización temprana con personas y otros animales ayuda mucho a su convivencia futura. La alimentación en esta etapa conviene consultarla con el veterinario, porque el crecimiento rápido requiere un balance específico.", "adulto": "Necesita espacio suficiente para moverse y estirarse, evitando jaulas chicas por su tamaño. El pelaje se beneficia de un cepillado regular, y el peso conviene monitorearlo porque influye en su salud articular. El ejercicio diario fuera de la jaula es importante para su bienestar físico y mental.", "senior": "En esta etapa puede volverse menos activo y conviene facilitarle el acceso a la comida, el agua y el descanso sin que tenga que subir o bajar demasiado. Los controles veterinarios más frecuentes ayudan a detectar cambios propios de la edad. Mantener una rutina estable y cómoda le hace bien en esta fase de su vida."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('equino','percheron',true,'El Percherón es una raza de caballos de tiro originaria de la región de Perche, en el norte de Francia. Se lo criaba para trabajar la tierra y para tirar de carruajes y cargas pesadas. Con el tiempo se exportó a todo el mundo por su fuerza y su buen carácter para el trabajo.','Suele ser un caballo tranquilo y paciente, con buena disposición para trabajar junto a las personas. Muchos ejemplares son dóciles y fáciles de manejar para su tamaño. Como en toda raza, el carácter también depende de la crianza y la experiencia individual de cada animal.','Entre 800 y 1200 kg, con una alzada que suele ir de 1,60 a 1,80 metros al lomo.','Entre 25 y 30 años aproximadamente.',array['Problemas articulares asociados al gran tamaño y peso corporal, para conversar con el veterinario sobre el manejo del ejercicio','Afecciones en los cascos, dado el peso que deben soportar','Cuestiones respiratorias, algo a monitorear con el veterinario especialmente en ambientes con polvo o encierro','Predisposición a cólicos, como en muchos equinos de gran tamaño','Sensibilidad cutánea en la zona de las crines y cuartillas, para revisar periódicamente con el veterinario']::text[],'{"cachorro": "En la etapa de potrillo es clave un crecimiento gradual, sin forzar ejercicio intenso mientras se desarrollan huesos y articulaciones. La socialización temprana con personas y otros caballos ayuda a formar un temperamento equilibrado. La alimentación en esta fase conviene planificarla con el veterinario, dado el rápido crecimiento de la raza.", "adulto": "Necesita ejercicio regular acorde a su condición física y al trabajo que realice. El pelaje y los cascos requieren revisión periódica, y la alimentación debe ajustarse a su gran tamaño sin excederse en calorías. Los controles veterinarios regulares ayudan a prevenir problemas articulares y digestivos propios de su contextura.", "senior": "Con los años conviene adaptar el ejercicio a su movilidad y prestar atención a signos de molestias articulares. La dieta puede necesitar ajustes para mantener un peso adecuado sin sobrecargar las articulaciones. Las visitas al veterinario suelen espaciarse menos en esta etapa para acompañar de cerca los cambios propios de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('cobaya','cobaya-peruana',true,'La cobaya peruana es una de las razas más antiguas, originaria de Sudamérica, y es reconocida por su pelo largo y liso que crece de forma continua. Se desarrolló como animal de compañía y de exhibición, valorada especialmente por su llamativo pelaje.','Suele ser una cobaya sociable y curiosa, que disfruta del contacto con su familia cuando se la maneja con calma. Como toda cobaya, se sobresalta con ruidos fuertes y necesita tiempo para confiar. Tiende a expresar bienestar o inquietud a través de sonidos, así que vale la pena aprender a reconocerlos.','Entre 900 gramos y 1,2 kilogramos, con un cuerpo de unos 20 a 25 centímetros de largo.','Entre 5 y 8 años, según los cuidados generales que reciba.',array['Problemas de piel o pelaje relacionados con el largo del pelo, algo para revisar con el veterinario','Molestias oculares si el pelo de la cara no se mantiene despejado, para consultar con el veterinario','Malformaciones dentales típicas de la especie, un tema para chequear en controles veterinarios','Sensibilidad respiratoria ante cambios bruscos de temperatura, para comentarlo con el veterinario','Deficiencia de vitamina C, algo habitual en cobayas y que conviene conversar con el veterinario']::text[],'{"cachorro": "En esta etapa temprana necesita un espacio protegido, sin corrientes de aire, y contacto progresivo y suave con la familia para que se acostumbre a las manos. El pelo largo empieza a notarse pronto, así que conviene ir habituándola al cepillado desde chica. La alimentación con heno de buena calidad y verduras frescas es clave, y cualquier duda sobre cantidades la puede resolver el veterinario.", "adulto": "El pelaje largo requiere cepillado frecuente para evitar nudos y suciedad, y a veces se opta por mantenerlo más corto para facilitar el cuidado diario. Necesita espacio para moverse, heno disponible todo el tiempo y una rutina estable. Los controles veterinarios periódicos ayudan a detectar a tiempo cualquier tema de piel, dientes o peso.", "senior": "Con los años puede moverse menos y necesitar ayuda para mantener el pelaje en condiciones, sobre todo en zonas que le cuesta alcanzar. Es buen momento para prestar atención a cambios en el apetito o en la movilidad y comentarlos con el veterinario. El entorno cálido y tranquilo sigue siendo fundamental para su bienestar."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','pinscher-miniatura',true,'El Pinscher Miniatura viene de Alemania, donde se lo criaba para cazar roedores en granjas y casas de campo. A pesar de su nombre y parecido, no es una versión pequeña del Doberman: son razas distintas con desarrollos separados.','Es un perro activo, curioso y alerta, con mucha energía para su tamaño. Suele encariñarse fuerte con su familia aunque puede mostrarse desconfiado con extraños. Tiene personalidad fuerte y necesita límites claros desde cachorro.','Entre 2.5 y 4.5 kg, con una altura de 25 a 30 cm aproximadamente.','Entre 12 y 14 años.',array['Luxación de rótula, algo para chequear con el veterinario en controles de rutina','Problemas de piel o alergias, conviene consultarlo si aparecen picazón o irritaciones frecuentes','Enfermedades dentales, buena idea hablar con el veterinario sobre el cuidado de los dientes desde joven','Problemas oculares, vale la pena mencionarlo en los chequeos periódicos','Cuestiones cardíacas, algo para tener en cuenta en los controles anuales']::text[],'{"cachorro": "Necesita socialización temprana para no volverse desconfiado o nervioso con el tiempo. El pelaje es corto y fácil de mantener, pero conviene ir acostumbrándolo a la higiene general desde chico. Es buen momento para empezar rutinas de alimentación y ejercicio moderado, siempre con guía del veterinario.", "adulto": "Requiere paseos diarios y estímulo mental, es un perro que se aburre fácil si no tiene actividad. El pelaje pide cepillado ocasional nomás. La alimentación debe ajustarse a su nivel de actividad, y cualquier cambio de peso o conducta vale la pena comentarlo con el veterinario.", "senior": "Con la edad puede bajar su nivel de energía, aunque muchos siguen bastante activos. Es buen momento para chequeos más frecuentes, sobre todo de articulaciones, dientes y corazón. Mantener rutinas estables lo ayuda a sentirse seguro en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('ave','jilguero',false,null,null,null,null,'{}','{"cachorro": null, "adulto": null, "senior": null}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('ave','cotorra-argentina',true,'La cotorra argentina, también llamada cotorra de cabeza gris o Myiopsitta monachus, es originaria de las zonas centrales y de la Pampa de Argentina, Uruguay, Paraguay y sur de Brasil. En su ambiente natural vive en bandadas grandes y es conocida por construir nidos colectivos de ramas, algo poco común entre los loros. Se volvió muy popular como mascota por su carácter sociable y su capacidad de imitar sonidos.','Es un ave inteligente, curiosa y muy activa, que suele encariñarse fuertemente con su familia humana. Tiende a ser vocal, con vocalizaciones frecuentes y bastante fuertes, y necesita estímulo mental para no aburrirse. Algunos ejemplares pueden mostrarse territoriales o algo dominantes si no se socializan bien desde jóvenes.','Entre 90 y 120 gramos de peso, con una longitud de 28 a 30 centímetros incluyendo la cola.','Entre 15 y 20 años, pudiendo llegar a más con buenos cuidados.',array['Problemas respiratorios, algo a conversar con el veterinario dado que son aves sensibles a cambios de temperatura y corrientes de aire','Picoteo compulsivo o arrancado de plumas, conducta que conviene revisar con el veterinario si aparece','Obesidad si la dieta no está bien equilibrada, tema para charlar con el veterinario','Deficiencias nutricionales por dietas basadas solo en semillas, bueno consultarlo con el veterinario','Estrés o ansiedad por aislamiento social, algo que amerita seguimiento profesional si se nota']::text[],'{"cachorro": "En esta etapa es clave la socialización temprana, exponerla de forma gradual a distintas personas, sonidos y manipulación suave. La alimentación debe ser variada desde el principio, evitando que se acostumbre solo a semillas, y esto conviene charlarlo con el veterinario. También es un buen momento para enseñarle rutinas y límites con paciencia y constancia.", "adulto": "Necesita tiempo diario fuera de la jaula para volar, explorar y interactuar con la familia, además de juguetes que la mantengan mentalmente activa. La dieta debe ser equilibrada, con frutas, verduras y un balanceado de calidad, siempre bajo la orientación del veterinario. Los chequeos veterinarios periódicos ayudan a detectar cualquier cambio a tiempo.", "senior": "Con los años puede reducir su nivel de actividad, así que hay que prestar atención a señales de dolor o incomodidad y comentarlas con el veterinario. El plumaje y las uñas pueden requerir más atención en esta etapa. Mantener el vínculo social y la estimulación mental sigue siendo importante, adaptando el ritmo a sus posibilidades."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','puli',true,'El Puli es una raza húngara antigua, criada durante siglos como perro pastor para conducir y controlar rebaños de ovejas. Se caracteriza por su pelaje característico en cordones, que lo protegía del clima y de los depredadores en el campo.','Es un perro alerta, ágil y muy unido a su familia, con tendencia a mostrarse desconfiado con extraños. Suele ser activo e inteligente, y le gusta tener una tarea o estímulo mental. Puede ladrar bastante si no se trabaja esa tendencia desde cachorro.','Entre 10 y 15 kg, con una altura de 36 a 45 cm aproximadamente.','Entre 10 y 13 años.',array['Displasia de cadera, algo para chequear con el veterinario en los controles de rutina','Problemas de piel relacionados con la humedad bajo el pelaje en cordones, conviene comentarlo con el veterinario','Afecciones oculares, es bueno mencionarlo en las visitas periódicas','Otitis, dado el tipo de oído caído y el manejo del pelaje alrededor']::text[],'{"cachorro": "Es clave socializarlo temprano con personas, otros animales y distintos entornos, para equilibrar su tendencia natural a la desconfianza. El pelaje empieza a formar los cordones característicos con el tiempo, así que conviene consultar con el veterinario o un groomer especializado sobre cómo acompañar ese proceso. Necesita estímulo físico y mental desde chico, sin exagerar el ejercicio mientras se desarrollan sus articulaciones.", "adulto": "Es un perro que necesita actividad diaria, tanto física como mental, para estar equilibrado. El cuidado del pelaje en cordones requiere atención regular para evitar que se enrede mal o acumule humedad. Los controles veterinarios periódicos ayudan a seguir de cerca su salud articular y de piel.", "senior": "Con la edad puede bajar su nivel de actividad, así que conviene adaptar los paseos a su ritmo sin dejar de estimularlo. El pelaje sigue necesitando cuidado constante, y en esta etapa es buen momento para chequear con el veterinario la salud de articulaciones, oídos y visión con más frecuencia. Los ajustes en la alimentación también vale la pena conversarlos con el veterinario."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('ave','cacatua-ninfa-perlada',true,'La cacatúa ninfa perlada es una variación de color de la ninfa común (Nymphicus hollandicus), especie originaria de las zonas áridas y semiáridas del interior de Australia. No es una raza distinta sino una mutación genética que afecta el patrón de las plumas, desarrollada y fijada por criadores en cautiverio. En estado silvestre las ninfas viven en bandadas y se criaba en cautiverio como ave de compañía por su carácter sociable.','Suele ser un ave sociable, curiosa y afectuosa con su familia humana, aunque cada individuo tiene su propio carácter. Muchas disfrutan del contacto y aprenden a silbar o imitar sonidos con facilidad. Necesitan interacción diaria porque tienden a apegarse mucho y pueden angustiarse si se sienten solas por períodos largos.','Entre 80 y 100 gramos de peso, con una longitud de aproximadamente 30 a 33 centímetros incluyendo la cola.','Entre 15 y 20 años, aunque con buenos cuidados algunas llegan a vivir más.',array['Problemas respiratorios, algo que conviene chequear con el veterinario si aparecen cambios en la respiración o el plumaje alrededor del pico','Deficiencias nutricionales asociadas a dietas basadas solo en semillas, tema para conversar con el veterinario sobre balance alimentario','Picaje o arrancado de plumas, conducta que vale la pena evaluar con el veterinario para descartar causas médicas o ambientales','Tumores relacionados con la glándula tiroides o gonadales, algo a monitorear con controles veterinarios periódicos','Obesidad si el ave tiene poco espacio para volar, punto para discutir con el veterinario en cuanto a dieta y actividad']::text[],'{"cachorro": "En las primeras semanas necesita calor constante y una dieta especial mientras se desteta, proceso que suele guiar un criador o veterinario especializado en aves. Es clave empezar la socialización temprano, manipulándola con calma para que se acostumbre a las manos y a distintos sonidos. Cualquier duda sobre el destete o el crecimiento conviene resolverla con el veterinario.", "adulto": "Necesita una jaula amplia donde pueda extender las alas y espacio diario para volar o moverse fuera de ella. La dieta debe combinar semillas con verduras, frutas y pellets, evitando que se base solo en semillas. El contacto social diario es importante, y si pasa mucho tiempo sola conviene evaluar con el veterinario o un especialista en comportamiento cómo enriquecer su rutina.", "senior": "Con los años puede reducir su nivel de actividad y volverse más sensible a los cambios de temperatura, por lo que conviene mantener un ambiente estable. Los controles veterinarios periódicos ayudan a detectar a tiempo cambios en el peso, el plumaje o la conducta. La estimulación mental y el vínculo social siguen siendo importantes, aunque el ritmo de juego cambie."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','alaskan-malamute',true,'Es una raza originaria de Alaska, desarrollada por el pueblo Mahlemut para tirar de trineos con cargas pesadas y ayudar en la caza. Fue criada para resistir climas extremos y trabajar en equipo durante largas distancias.','Suele ser un perro leal y afectuoso con su familia, aunque conserva un carácter independiente y algo testarudo. Tiene mucha energía y necesita sentirse parte de las actividades familiares, no le gusta quedarse solo por mucho tiempo. Con otros perros pequeños o animales puede mostrar instinto de persecución.','Entre 34 y 39 kilos, con una altura de 58 a 64 centímetros aproximadamente.','Entre 10 y 14 años.',array['Displasia de cadera, algo para chequear con el veterinario en controles periódicos','Problemas oculares hereditarios, conviene consultarlo en las revisiones de rutina','Hipotiroidismo, es un tema para conversar si aparecen cambios de energía o peso','Condiciones de piel relacionadas con el pelaje denso, bueno mencionarlo si hay picazón o irritación persistente','Cuestiones cardíacas congénitas, vale la pena preguntarlo en los chequeos generales']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros perros y distintos ambientes, ya que es una etapa clave para su carácter adulto. El ejercicio debe ser moderado para no forzar sus articulaciones en crecimiento, y conviene consultar con el veterinario sobre el plan de alimentación y vacunación.", "adulto": "Requiere ejercicio diario intenso, ya que es un perro con mucha resistencia física y necesidad de actividad. Su pelaje denso pide cepillado frecuente, sobre todo en las épocas de muda. Es buen momento para mantener controles veterinarios regulares y una dieta acorde a su nivel de actividad.", "senior": "Puede necesitar ajustes en la intensidad del ejercicio, siempre atendiendo a sus tiempos y comodidad. El pelaje y las articulaciones merecen atención especial, y los chequeos veterinarios más seguidos ayudan a detectar cambios propios de la edad a tiempo."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','pastor-suizo-blanco',true,'El Pastor Suizo Blanco desciende de los primeros pastores alemanes de pelaje blanco, considerados durante décadas una variación descartada de esa raza. En Suiza y Estados Unidos, criadores lo fueron consolidando como raza aparte a partir de los años 60 y 70, valorando su temperamento equilibrado además de su aspecto. Hoy se lo cría como perro de familia y también de trabajo, en tareas como rescate o asistencia.','Suele ser un perro leal y apegado a su familia, con buena disposición para aprender. Tiende a mostrarse reservado con extraños al principio, aunque rara vez es agresivo si fue bien socializado. Necesita sentirse parte de la vida diaria de la casa, no es un perro que rinda bien aislado o encerrado mucho tiempo.','Entre 30 y 40 kilos, con una altura que va de 55 a 66 cm según sea macho o hembra.','Entre 10 y 12 años en promedio.',array['Displasia de cadera y codo, algo para conversar con el veterinario sobre controles según la edad','Torsión gástrica, especialmente relevante en perros de pecho profundo','Problemas oculares hereditarios, conviene charlarlo en los chequeos de rutina','Sensibilidades digestivas, vale consultarlo si hay cambios frecuentes de alimentación','Alergias cutáneas, un tema para revisar si aparecen picazón o irritaciones recurrentes']::text[],'{"cachorro": "Es clave exponerlo a distintas personas, animales y entornos durante los primeros meses, siempre de forma gradual y positiva. El ejercicio debe ser moderado para no forzar las articulaciones en crecimiento, y conviene consultar con el veterinario un plan de alimentación adecuado a su desarrollo. El cepillado regular ayuda a acostumbrarlo al manejo del pelaje desde chico.", "adulto": "Necesita actividad física diaria, ya sea caminatas largas, juego o algún trabajo mental, porque es un perro activo e inteligente. El pelaje denso requiere cepillado frecuente, más aún en época de muda. Los controles veterinarios periódicos ayudan a seguir de cerca cualquier predisposición propia de la raza.", "senior": "Con la edad conviene ajustar la intensidad del ejercicio a lo que el cuerpo le permita, sin dejar de estimularlo física y mentalmente. Es buen momento para chequeos veterinarios más seguidos, atentos a la movilidad y la vista. La alimentación también suele necesitar ajustes, algo que conviene charlar con el veterinario según cómo esté cada perro."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','keeshond',true,'El keeshond viene de los Países Bajos, donde se lo usaba como perro guardián de barcazas y casas flotantes en canales y ríos. Su nombre está ligado a un líder político holandés del siglo XVIII, que lo tenía como mascota. Es una raza tipo spitz, emparentada con otros perros nórdicos de pelaje abundante.','Suele ser un perro alerta, apegado a su familia y con ganas de estar involucrado en todo lo que pasa en casa. Tiende a ser vocal, así que avisa cuando algo le llama la atención. Se lleva bien con niños y con la rutina familiar, aunque puede necesitar tiempo para confiar en desconocidos.','Entre 15 y 20 kilos, con una altura de 43 a 48 cm aproximadamente.','Entre 12 y 15 años.',array['Displasia de cadera, algo para chequear con el veterinario en controles de rutina','Problemas de tiroides, conviene hablarlo si notás cambios de peso o energía','Ciertas condiciones oculares hereditarias, bueno consultarlo en los chequeos periódicos','Sensibilidad de piel o alergias, si aparecen picazón o irritación es tema de consulta','Insuficiencia cardíaca en casos puntuales, algo para monitorear con estudios veterinarios']::text[],'{"cachorro": "Necesita socialización temprana, con exposición gradual a personas, otros animales y sonidos distintos. El pelaje empieza a desarrollarse y conviene ir acostumbrándolo al cepillado desde chico. La alimentación y el ritmo de crecimiento son buenos temas para charlar con el veterinario.", "adulto": "Requiere ejercicio diario, caminatas y algo de estimulación mental, ya que es un perro activo e inteligente. El pelaje denso pide cepillado frecuente, sobre todo en épocas de muda. Los chequeos veterinarios periódicos ayudan a seguir de cerca su salud general.", "senior": "Puede necesitar rutinas de ejercicio más suaves, adaptadas a su energía y movilidad. Es buen momento para prestar atención a cambios en el apetito, el peso o el comportamiento y comentarlos con el veterinario. Los controles regulares cobran más importancia en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','boyero-de-berna',true,'El Boyero de Berna viene de los Alpes suizos, de la región de Berna, donde se usaba como perro de granja: cuidaba el ganado, tiraba de carros pequeños y hacía guardia en las fincas. Es una de las cuatro razas suizas de montaña y su pelaje tricolor es característico.','Suele ser un perro tranquilo, cariñoso y apegado a su familia, con buena disposición hacia los niños. Puede mostrarse reservado con desconocidos aunque no es agresivo por naturaleza. Le gusta estar cerca de su gente y no lleva bien la soledad prolongada.','Entre 38 y 50 kilos, con una altura de 58 a 70 centímetros según sea macho o hembra.','Entre 7 y 10 años aproximadamente.',array['Displasia de cadera y codo, algo para chequear con el veterinario a lo largo de su vida','Ciertos tipos de cáncer, más frecuentes en esta raza que en otras, vale la pena hablarlo con el veterinario','Torsión gástrica, tema para conversar sobre prevención y señales de alerta','Problemas oculares como el entropión, conviene que el veterinario los revise periódicamente','Cuestiones cardíacas que pueden aparecer, bueno mencionarlo en los controles de rutina']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes. El ejercicio debe ser moderado, evitando saltos o esfuerzos fuertes mientras el esqueleto todavía se está formando. Es buen momento para consultar con el veterinario sobre alimentación y controles de crecimiento.", "adulto": "Agradece caminatas diarias y actividades al aire libre, sin ser una raza que necesite ejercicio extremo. El pelaje denso requiere cepillado frecuente, sobre todo en épocas de muda. Los controles veterinarios periódicos ayudan a seguir de cerca su salud articular y general.", "senior": "Baja el ritmo y conviene adaptar las caminatas a su energía, cuidando las articulaciones. La dieta puede necesitar ajustes, algo para charlar con el veterinario. Los chequeos más seguidos permiten detectar a tiempo cualquier cambio en su salud."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','setter-ingles',true,'El Setter Inglés se originó en Gran Bretaña, donde se lo desarrolló durante siglos para localizar aves de caza en el campo, quedándose quieto o agazapado al detectarlas para señalarle su posición al cazador. Es una raza de caza y muestra con mucha historia detrás.','Suele ser un perro amigable, sociable y con mucha energía, que disfruta del contacto con su familia y con otros perros. Tiende a ser sensible y responde bien a un trato paciente y afectuoso. Necesita compañía y no le sienta bien pasar largas horas solo.','Entre 25 y 30 kilos, con una altura aproximada de 56 a 66 cm a la cruz.','Entre 10 y 12 años aproximadamente.',array['Displasia de cadera, algo para chequear con el veterinario especialmente en perros grandes y activos','Sordera congénita, más frecuente en ejemplares con manchas blancas, conviene consultarlo','Hipotiroidismo, tema para conversar si se notan cambios de energía o peso','Alergias cutáneas, vale la pena preguntar si aparecen picazones o irritaciones frecuentes','Torsión gástrica, algo a tener en cuenta y comentar con el veterinario por su contextura']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos entornos, ya que es una etapa clave para su desarrollo emocional. El ejercicio debe ser moderado para no forzar articulaciones en crecimiento, y conviene consultar con el veterinario sobre alimentación y plan de vacunación.", "adulto": "Requiere ejercicio diario intenso, como caminatas largas o actividades al aire libre, porque es una raza con mucha energía. Su pelaje semilargo necesita cepillado regular para evitar nudos, y una dieta equilibrada acorde a su nivel de actividad ayuda a mantenerlo en forma.", "senior": "Con la edad conviene adaptar el ejercicio a un ritmo más tranquilo, respetando sus tiempos y posibles molestias articulares. Es buen momento para chequeos veterinarios más frecuentes y para prestar atención a cambios en el apetito, la movilidad o el comportamiento."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','dogo-de-burdeos',true,'El Dogo de Burdeos es una raza francesa muy antigua, originaria de la región de Burdeos, criada para el trabajo pesado: guarda de propiedades, arrastre de cargas y caza de animales grandes. Es una de las razas molosoides más antiguas de Francia.','Suele ser un perro tranquilo y afectuoso con su familia, muy apegado y protector. Puede ser reservado con extraños y con otros perros, por lo que la socialización temprana es importante. No es un perro que busque actividad constante, prefiere la calma dentro de casa.','Entre 45 y 65 kg, con una altura aproximada de 58 a 68 cm a la cruz.','Entre 5 y 8 años, una vida relativamente corta para su tamaño.',array['Displasia de cadera y codo, algo a controlar con el veterinario por su tamaño y peso','Problemas cardíacos, conviene chequeos periódicos','Torsión gástrica, tema para conversar sobre horarios y forma de alimentación','Problemas de piel en los pliegues faciales, requieren seguimiento veterinario','Sobrecalentamiento por dificultad respiratoria, algo a evaluar con el veterinario según la época del año']::text[],'{"cachorro": "Necesita un crecimiento controlado, sin ejercicio excesivo ni saltos que fuercen sus articulaciones todavía en desarrollo. La socialización temprana con personas, otros animales y distintos ambientes es clave para su temperamento adulto. La alimentación en esta etapa conviene consultarla con el veterinario, dado el ritmo de crecimiento de la raza.", "adulto": "Requiere ejercicio moderado, paseos regulares pero sin exigencias extremas de resistencia. Hay que estar atento a la limpieza de los pliegues de la cara y del cuerpo para evitar irritaciones. El control de peso es importante, ya que el sobrepeso agrava los problemas articulares y cardíacos.", "senior": "En esta etapa disminuye la actividad y aumenta el descanso, adaptando los paseos a su energía y movilidad. Es buen momento para chequeos veterinarios más frecuentes, sobre todo relacionados con el corazón y las articulaciones. La comodidad térmica y un lugar de descanso blando ayudan a su bienestar general."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('conejo','hotot-enano',true,'El Hotot Enano se desarrolló en Alemania a partir de cruces con el Hotot original y razas enanas, buscando una versión pequeña de ese conejo blanco con los característicos círculos oscuros alrededor de los ojos. Se lo criaba principalmente como mascota y para exposiciones, no para producción.','Suele ser un conejo activo y curioso, con carácter despierto y bastante presencia. Se encariña con su familia pero puede mostrarse independiente o territorial, sobre todo si no se lo maneja con calma desde chico. Con manejo suave y constante tiende a volverse confiado y sociable.','Entre 1 y 1.4 kg aproximadamente, con un cuerpo compacto y redondeado, de porte pequeño típico de las razas enanas.','Entre 7 y 10 años, con buenos cuidados generales.',array['Problemas dentales por crecimiento continuo de los dientes, algo para revisar con el veterinario','Predisposición a la obesidad si no tiene suficiente espacio para moverse, conviene charlarlo con el veterinario','Afecciones oculares dada la zona pigmentada alrededor de los ojos, vale la pena consultarlo','Sensibilidad digestiva ante cambios de dieta, tema para conversar con el veterinario','Cierta tendencia a el estrés en ambientes ruidosos o con manejo brusco, bueno mencionarlo en la consulta']::text[],'{"cachorro": "Necesita un espacio seguro y tranquilo para explorar, con manejo suave para que se acostumbre a las manos desde temprano. La alimentación en esta etapa es clave, así que conviene seguir las recomendaciones del veterinario sobre heno, pellets y verduras.", "adulto": "Requiere tiempo diario fuera de la jaula para moverse y explorar, además de heno disponible todo el tiempo para su digestión y desgaste dental. El cepillado regular ayuda con la muda de pelo, y los controles veterinarios periódicos son buenos para monitorear dientes y peso.", "senior": "Puede necesitar ajustes en el espacio para que le resulte más fácil moverse, y controles veterinarios más frecuentes para seguir de cerca la salud dental, articular y general. Mantener una rutina estable y tranquila ayuda a que esta etapa sea más cómoda para él."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','affenpinscher',true,'El Affenpinscher es una raza antigua originaria de Alemania, desarrollada para cazar ratones y otras alimañas pequeñas en casas y establos. Con el tiempo pasó de ser un cazador de campo a un perro de compañía muy apreciado en las ciudades.','Suele ser un perro curioso, terco y con mucha personalidad, cariñoso con su familia pero desconfiado con extraños. Le gusta sentirse parte de las decisiones de la casa y puede mostrarse territorial. Con buena socialización convive bien con otros animales, aunque conserva algo de su instinto cazador.','Entre 3 y 6 kilos, con una altura de 23 a 30 centímetros aproximadamente.','Entre 12 y 15 años.',array['Problemas en las articulaciones como luxación de rótula, algo para revisar con el veterinario','Enfermedades dentales, por lo que conviene hablar sobre el cuidado bucal','Problemas oculares que vale la pena controlar periódicamente','Sensibilidad respiratoria por su hocico corto, un tema para conversar con el veterinario','Hernias, algo que el veterinario puede chequear en los controles de rutina']::text[],'{"cachorro": "Es importante socializarlo temprano con personas, otros animales y distintos ambientes para equilibrar su carácter independiente. El pelaje empieza a necesitar cepillado regular desde chico para evitar enredos. Conviene consultar con el veterinario un plan de alimentación y vacunación adecuado para su tamaño.", "adulto": "Necesita paseos diarios moderados, no es una raza que requiera ejercicio intenso pero sí estímulo mental. El pelaje áspero pide cepillado frecuente y cortes periódicos para mantenerlo prolijo. Es buen momento para chequeos veterinarios regulares que sigan de cerca su salud articular y dental.", "senior": "Los paseos pueden acortarse pero conviene mantenerlos para cuidar su movilidad y peso. Es momento de estar más atentos a cambios en su comportamiento, visión o apetito, y consultarlos con el veterinario. Los controles periódicos ayudan a detectar a tiempo cualquier tema relacionado con la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','labradoodle',true,'El Labradoodle surgió en Australia en los años 80, de cruzar Labrador Retriever con Caniche. La idea original era lograr un perro guía con pelaje más hipoalergénico para familias con alergias. No es una raza reconocida formalmente por las grandes federaciones caninas, sino un cruce que se sigue reproduciendo de forma bastante consistente.','Suele ser un perro sociable, activo y apegado a su familia. Muchos ejemplares heredan la disposición amigable del Labrador y la viveza del Caniche, aunque el temperamento puede variar bastante según la generación y la mezcla de genes. Convive bien con niños y con otros animales cuando se socializa desde cachorro.','Entre 20 y 30 kg, y entre 45 y 65 cm de altura a la cruz, aunque varía según el tamaño de los padres.','Entre 12 y 14 años.',array['Displasia de cadera, algo para chequear con el veterinario según el linaje','Problemas oculares, conviene hacer controles periódicos','Alergias o sensibilidad de piel, vale la pena consultarlo si aparecen síntomas','Otitis, por el tipo de oreja caída conviene revisarlas seguido','Torsión gástrica, tema para hablar con el veterinario sobre hábitos de alimentación']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros perros y distintos ambientes. El pelaje puede empezar a rizarse y requiere cepillado frecuente para evitar nudos. Es un buen momento para consultar al veterinario sobre plan de vacunas y alimentación adecuada para su crecimiento.", "adulto": "Requiere ejercicio diario, tanto físico como mental, porque suele ser un perro con energía. El pelaje necesita cepillado regular, y muchas familias optan por cortes periódicos para mantenerlo manejable. Los controles veterinarios anuales ayudan a seguir de cerca su salud general.", "senior": "Baja naturalmente el nivel de actividad, así que conviene adaptar los paseos y la dieta a ese ritmo. Es buen momento para chequeos veterinarios más frecuentes, sobre todo de articulaciones y vista. El pelaje sigue necesitando cuidado constante para evitar enredos e irritaciones en la piel."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','bobtail',true,'El Bobtail, también llamado Old English Sheepdog, es un perro pastor originario de Inglaterra, criado para conducir y cuidar rebaños de ovejas y ganado. Su pelaje espeso lo protegía del clima húmedo de la campiña inglesa.','Suele ser un perro cariñoso y apegado a su familia, con un carácter tranquilo pero también juguetón. Es sociable y tiende a llevarse bien con niños, aunque su tamaño y energía requieren supervisión con los más pequeños. Puede mostrarse algo protector con su hogar.','Entre 27 y 45 kilos, con una altura de 56 a 61 cm a la cruz.','Entre 10 y 12 años.',array['Displasia de cadera, un tema para charlar con el veterinario en los controles de rutina','Problemas oculares, como cataratas, que conviene revisar periódicamente','Hipotiroidismo, que puede consultarse si hay cambios de peso o energía','Sordera congénita, algo a evaluar sobre todo en cachorros','Torsión gástrica, una condición que vale la pena conocer y consultar cómo prevenir']::text[],'{"cachorro": "Necesita socialización temprana con otros perros y personas, y cuidado con el ejercicio para no forzar sus articulaciones en crecimiento. El pelaje empieza a requerir cepillado frecuente desde chico para evitar nudos. Las consultas veterinarias regulares ayudan a seguir su desarrollo.", "adulto": "Requiere ejercicio diario moderado y cepillado varias veces por semana para mantener su pelaje en buen estado. Es un perro que disfruta estar cerca de su familia y necesita interacción social constante. Los chequeos veterinarios anuales son importantes para monitorear su salud general.", "senior": "Puede necesitar rutinas de ejercicio más suaves y colchones cómodos para aliviar las articulaciones. El pelaje sigue demandando atención, y es buen momento para consultar con el veterinario sobre chequeos más frecuentes. La alimentación también puede necesitar ajustes según indique el profesional."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','basenji',true,'El basenji es originario de África central, particularmente de la zona del Congo, donde comunidades locales lo usaban como perro de caza para rastrear y acorralar presas en la selva. Es una de las razas más antiguas que se conocen, con siglos de existencia prácticamente sin modificaciones. Llegó a Europa y Estados Unidos recién en el siglo XX.','Suele ser independiente y un poco reservado con los desconocidos, aunque cariñoso con su familia. Es curioso, activo e inteligente, con tendencia a tomar sus propias decisiones más que a buscar aprobación constante. Es conocido por no ladrar de la forma tradicional, aunque puede emitir otros sonidos.','Entre 9 y 11 kg, con una altura aproximada de 40 a 43 cm a la cruz.','Entre 12 y 14 años.',array['Problemas renales como la nefropatía familiar, para charlar con el veterinario sobre controles periódicos','Cuestiones tiroideas que conviene evaluar con estudios de rutina','Displasia de cadera, algo bueno de conversar antes de definir el nivel de ejercicio','Problemas oculares hereditarios, para tener en cuenta en revisiones regulares','Sensibilidad digestiva que algunos ejemplares presentan, útil de comentar al elegir alimentación']::text[],'{"cachorro": "Necesita socialización temprana porque su independencia natural puede acentuarse si no se trabaja desde chico. El ejercicio debe ser moderado y progresivo para no forzar el desarrollo de las articulaciones, y conviene hablar con el veterinario sobre el plan de vacunación y alimentación adecuada para esta etapa.", "adulto": "Es un perro con buena energía que disfruta de caminatas y espacios donde pueda correr con seguridad. El pelaje corto es fácil de mantener, con cepillados ocasionales. Los controles veterinarios anuales ayudan a monitorear la salud renal y tiroidea de la raza.", "senior": "Con la edad conviene ajustar la intensidad del ejercicio y observar cambios en el apetito o la movilidad. Los chequeos veterinarios más frecuentes son importantes para detectar a tiempo cualquier tema renal o articular. El descanso cómodo y una dieta acorde a su ritmo de vida hacen la diferencia en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('reptil','boa-constrictora',true,'La boa constrictora es una especie originaria de América Central y del Sur, desde México hasta Argentina. No es una raza en el sentido tradicional sino una especie con varias subespecies, y se la mantiene como mascota exótica desde hace décadas por su tamaño manejable comparado con otras boas y su temperamento relativamente tranquilo.','Suele ser un animal tranquilo y de movimientos pausados una vez adulto, aunque cada ejemplar tiene su propio carácter y algunos son más reactivos que otros. Con manejo regular y respetuoso muchas se acostumbran a la manipulación, pero no dejan de ser animales salvajes con instintos propios. No es una mascota para interactuar todos los días como un perro o un gato, y conviene respetar sus tiempos y señales.','Entre 2 y 3,5 metros de largo según la subespecie y el sexo, con hembras generalmente más grandes; el peso puede rondar los 10 a 25 kilos en ejemplares adultos.','Entre 20 y 30 años en cautiverio con cuidados adecuados.',array['Problemas respiratorios asociados a condiciones de temperatura y humedad inadecuadas, para charlar con el veterinario sobre el ambiente del terrario','Parásitos internos y externos, algo para controlar periódicamente con el veterinario especializado en reptiles','Retención de huevos o dificultades reproductivas en hembras, un tema para conversar si se planea reproducción','Problemas dérmicos o de muda incompleta, vinculados muchas veces a humedad insuficiente, para revisar con el veterinario','Obesidad por sobrealimentación en cautiverio, un punto a evaluar con el veterinario según el plan de alimentación']::text[],'{"cachorro": "Las crías necesitan un terrario de tamaño acorde a su tamaño real, no al que tendrán de adultas, con buen control de temperatura y humedad. La alimentación es con presas pequeñas y a intervalos que conviene definir con el veterinario especializado en reptiles. El manejo debe ser breve y gradual para que se acostumbre sin estresarse.", "adulto": "Necesita un terrario amplio con gradiente de temperatura, escondites y acceso a agua limpia. La frecuencia de alimentación se espaciación más que en la etapa juvenil, y el veterinario puede orientar sobre el tamaño y periodicidad de las presas. Es importante observar la piel y la muda para detectar cualquier irregularidad a tiempo.", "senior": "En animales mayores conviene prestar atención a cambios en el apetito, en la movilidad o en la calidad de la muda, y consultarlo con el veterinario. El ambiente del terrario sigue siendo clave, quizás con ajustes si el animal se mueve menos. Los controles periódicos ayudan a detectar a tiempo cualquier problema propio de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','fila-brasileno',true,'Es una raza brasileña desarrollada a partir de perros de presa europeos llevados durante la colonización. Se usaba para guardia de haciendas, para el rastreo de esclavos fugitivos en la época colonial y más tarde para el control de ganado y caza mayor.','Es un perro con fuerte instinto protector y muy apegado a su familia, aunque suele mostrarse desconfiado o distante con extraños. Necesita una socialización temprana y constante para manejar bien su carácter territorial. No es una raza pensada para hogares con visitas frecuentes o mucho contacto con desconocidos.','Entre 40 y 50 kg, con una altura que va de 60 a 75 cm aproximadamente.','Entre 9 y 11 años.',array['Displasia de cadera y codo, algo para conversar con el veterinario dado su tamaño grande','Torsión gástrica, un tema a tener en cuenta por su contextura','Problemas dermatológicos o de piel que conviene monitorear','Entropión u otras afecciones oculares que puede revisar el veterinario','Cardiopatías que a veces se presentan en razas grandes, buen tema para chequeos periódicos']::text[],'{"cachorro": "La socialización temprana es central en esta etapa, con exposición gradual y controlada a personas y otros animales. El ejercicio debe ser moderado para no forzar las articulaciones en crecimiento, y la alimentación tiene que acompañar ese desarrollo, algo que conviene planificar con el veterinario.", "adulto": "Necesita ejercicio diario constante y actividades que le den un propósito, además de límites claros y entrenamiento con refuerzo positivo. El pelaje corto se mantiene fácil con cepillado regular, y los controles veterinarios periódicos ayudan a seguir de cerca su salud articular y general.", "senior": "Los paseos se acortan pero no desaparecen, ajustando el ritmo a lo que el cuerpo le permita. Es buen momento para chequeos veterinarios más frecuentes, sobre todo de articulaciones y corazón, y para adaptar la dieta a sus nuevas necesidades."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','akita-americano',true,'El Akita Americano se desarrolló en Estados Unidos a partir de ejemplares de Akita Inu llevados desde Japón después de la Segunda Guerra Mundial, cruzados con otras razas para lograr un perro más grande y robusto. Originalmente se usó para caza mayor y guardia, y con el tiempo se consolidó como raza independiente del Akita Inu japonés.','Suele ser un perro tranquilo dentro de casa pero muy atento y protector con su familia. Tiende a mostrarse reservado o desconfiado con extraños y puede ser territorial con otros perros, por lo que la socialización temprana ayuda bastante. Es leal y cariñoso con los suyos, aunque no siempre busca el contacto constante como otras razas.','Entre 32 y 59 kg de peso, y entre 61 y 71 cm de altura a la cruz, según sea macho o hembra.','Entre 10 y 13 años aproximadamente.',array['Displasia de cadera y codo, algo para chequear con el veterinario en controles periódicos','Problemas de tiroides, conviene conversarlo si aparecen cambios de peso o energía','Torsión gástrica, vale preguntar sobre pautas de alimentación para reducir el riesgo','Afecciones oculares como entropión, bueno mencionarlo en las visitas de rutina','Cuestiones dermatológicas o alergias, útil comentarlas si hay picazón o cambios en la piel']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros perros y distintos ambientes para prevenir desconfianza excesiva de adulto. El ejercicio debe ser moderado para no forzar las articulaciones en crecimiento, y la alimentación conviene planificarla con el veterinario según su desarrollo.", "adulto": "Requiere ejercicio diario moderado, como paseos largos, sin necesidad de actividades muy intensas. Su pelaje denso pide cepillado regular, más frecuente en época de muda. Al ser un perro fuerte y a veces territorial, el entrenamiento con límites claros y constancia ayuda a la convivencia diaria.", "senior": "Puede reducir su nivel de actividad y conviene adaptar los paseos a su ritmo. Los controles veterinarios periódicos son importantes para monitorear articulaciones, tiroides y estado general. La dieta también puede necesitar ajustes acordes a la edad, siempre con orientación profesional."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','vizsla',true,'El Vizsla es un perro de caza originario de Hungría, criado durante siglos por la nobleza para rastrear y cobrar piezas en llanuras abiertas. Su función combinaba olfato fino, velocidad y una estrecha relación de trabajo con el cazador. Hoy se lo conoce tanto como perro deportivo como de compañía.','Suele ser un perro afectuoso y muy apegado a su familia, al punto de buscar contacto físico constante. Tiene energía alta y necesita actividad diaria, tanto física como mental, para estar equilibrado. Con los niños suele mostrarse paciente, aunque como con cualquier perro conviene supervisar los encuentros.','Entre 20 y 30 kilos, con una altura de 54 a 64 centímetros aproximadamente.','Entre 12 y 14 años.',array['Displasia de cadera, algo para chequear con el veterinario a lo largo de su vida','Epilepsia, un tema para conversar si aparecen episodios sospechosos','Problemas de tiroides, que conviene monitorear con estudios de rutina','Alergias cutáneas, para consultar si hay picazón o irritaciones frecuentes','Ansiedad por separación, un aspecto de manejo a charlar con un profesional']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros perros y distintos ambientes. El ejercicio debe ser moderado y progresivo para no forzar sus articulaciones en crecimiento. Es un buen momento para empezar con hábitos de alimentación controlada y visitas regulares al veterinario.", "adulto": "Requiere ejercicio diario intenso, como corridas largas o juegos activos, además de estímulo mental. Su pelaje corto es fácil de mantener con cepillados ocasionales. La alimentación debe ajustarse a su nivel de actividad, y las revisiones veterinarias anuales ayudan a seguir de cerca su salud general.", "senior": "Con la edad conviene adaptar la intensidad del ejercicio a lo que el cuerpo le permita, sin dejar de estimularlo física y mentalmente. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a articulaciones, vista y peso. La dieta también puede necesitar ajustes según indique el veterinario."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('pez','gourami-enano',true,'El gourami enano es originario de las zonas de aguas tranquilas del subcontinente indio, especialmente ríos y arrozales de India y Bangladesh. Se popularizó como pez ornamental por sus colores llamativos y su tamaño compacto, ideal para acuarios domésticos.','Suele ser un pez tranquilo y de movimientos pausados, aunque los machos pueden mostrarse territoriales entre sí, sobre todo en espacios reducidos. Convive bien con otras especies pacíficas de tamaño similar. Cada ejemplar tiene su propio ritmo, algunos son más tímidos y otros más curiosos con su entorno.','Entre 5 y 9 cm de largo, según el sexo y la línea genética.','Entre 4 y 6 años en condiciones adecuadas de acuario.',array['Susceptibilidad a la enfermedad del gourami, algo para consultar con el veterinario especializado en peces si notás cambios de comportamiento o coloración','Sensibilidad a la calidad del agua, conviene charlar sobre parámetros ideales con quien haga el seguimiento del acuario','Predisposición a infecciones fúngicas o bacterianas si el ambiente no está bien equilibrado','Estrés por convivencia con especies muy activas o agresivas, vale la pena revisar la combinación de peces con un especialista']::text[],'{"cachorro": "En la etapa juvenil es importante mantener el agua estable en temperatura y limpieza, ya que son más sensibles a los cambios bruscos. Conviene ofrecer un espacio con plantas o refugios donde puedan esconderse mientras se adaptan. La alimentación debe ser variada y en porciones pequeñas, varias veces al día.", "adulto": "Necesita un acuario con buena vegetación y zonas de sombra, además de agua tranquila sin corrientes fuertes. La dieta puede incluir alimento balanceado para peces tropicales junto con algo de comida viva o congelada ocasional. Si notás cambios en el apetito o en la piel, es buen momento para consultar al veterinario.", "senior": "Con la edad puede volverse más sedentario y sensible a las fluctuaciones del agua, por lo que el mantenimiento constante del acuario cobra más importancia. Es recomendable observar signos de letargo o pérdida de color, que ameritan una consulta veterinaria. Mantener una dieta liviana y de fácil digestión ayuda a sostener su bienestar general."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','papillon',true,'El Papillón es una raza francesa y belga muy antigua, descendiente de los pequeños spaniel falderos que aparecían en retratos de la nobleza europea desde el siglo XVI. Se criaba como perro de compañía en las cortes, apreciado por su elegancia y sus orejas características en forma de mariposa.','Suele ser un perro alerta, ágil e inteligente, con ganas de aprender y participar de lo que pasa en la casa. Se encariña mucho con su familia y puede mostrarse reservado con desconocidos hasta que los conoce. Su energía mental necesita estímulo, no solo ejercicio físico.','Entre 1,5 y 4,5 kg, con una altura de 20 a 28 cm aproximadamente.','Entre 14 y 16 años.',array['Luxación patelar, algo para revisar con el veterinario en controles de rutina','Problemas dentales, por el tamaño reducido de la boca','Hipoglucemia en cachorros muy pequeños, tema para consultar sobre alimentación','Colapso traqueal, conviene mencionarlo si aparece tos o ruidos al respirar','Sensibilidad ocular, bueno chequearla en visitas periódicas']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros perros y distintos ambientes, ya que es una etapa clave para su carácter futuro. Las comidas deben ser frecuentes y en porciones pequeñas, y conviene consultar con el veterinario sobre la alimentación adecuada para razas tan pequeñas. El juego y el aprendizaje de órdenes básicas ayudan a canalizar su energía.", "adulto": "Con paseos diarios y juegos que impliquen algo de desafío mental se mantiene equilibrado. Su pelaje sedoso no tiene subpelo denso, así que el cepillado regular alcanza para evitar nudos. Las revisiones veterinarias periódicas ayudan a seguir de cerca la salud dental y articular.", "senior": "Puede mantenerse activo por bastante tiempo, pero conviene ajustar la intensidad de los paseos según su ritmo. Los controles veterinarios más frecuentes ayudan a detectar cambios en la vista, las articulaciones o los dientes. Un descanso cómodo y abrigado es importante, ya que su tamaño pequeño lo hace más sensible al frío."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','schnauzer-gigante',true,'El Schnauzer Gigante viene de Baviera, Alemania, donde se lo usaba para arrear ganado y cuidar cervecerías y granjas. Se lo crió agrandando al Schnauzer Estándar para tener un perro de trabajo más robusto. Con el tiempo se sumó como perro policial y de protección.','Es un perro que suele ser leal y protector con su familia, y tiende a mantenerse reservado con los extraños. Es inteligente y necesita estímulo mental, porque si se aburre puede volverse destructivo o testarudo. Con buena socialización suele convivir bien con niños y otros animales de la casa.','Entre 25 y 47 kilogramos, con una altura de 60 a 70 centímetros a la cruz.','Entre 10 y 12 años.',array['Displasia de cadera y codo, algo para chequear con el veterinario en controles periódicos','Torsión gástrica, por lo que conviene conversar con el veterinario sobre pautas de alimentación','Problemas oculares hereditarios, conviene mencionarlo en los chequeos de rutina','Hipotiroidismo, algo que el veterinario puede evaluar con análisis de sangre','Ciertas afecciones de piel, para consultar si aparecen irritaciones o alergias recurrentes']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes, porque su tendencia a la reserva con extraños se maneja mejor si se trabaja desde chico. El ejercicio debe ser moderado para no forzar las articulaciones mientras crece. Es un buen momento para empezar con el veterinario un esquema de controles y consultar sobre alimentación.", "adulto": "Requiere ejercicio diario constante y tareas que lo mantengan mentalmente activo, como adiestramiento u obediencia. Su pelaje duro necesita cepillado regular y recortes periódicos para mantenerlo en condiciones. Las revisiones veterinarias anuales ayudan a seguir de cerca su salud articular y general.", "senior": "Los paseos pueden acortarse pero conviene mantenerlos, adaptando el ritmo a lo que el perro pida. Es un buen momento para que el veterinario controle con más frecuencia articulaciones, vista y función tiroidea. La dieta también suele necesitar ajustes, algo que conviene charlar con el veterinario según su estado."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','komondor',true,'El Komondor es un perro pastor originario de Hungría, criado durante siglos para proteger rebaños de ovejas de depredadores. Su pelaje en forma de cordones le permitía trabajar a la intemperie y mimetizarse con el ganado que cuidaba.','Es un perro independiente y protector, con fuerte instinto de guardián hacia su familia y su territorio. Tiende a ser reservado con los desconocidos y necesita socialización temprana para manejar mejor esa desconfianza natural. Con los suyos suele ser leal y tranquilo, aunque no es un perro especialmente efusivo.','Entre 40 y 60 kilos, con una altura de 60 a 80 centímetros aproximadamente.','Entre 10 y 12 años.',array['Displasia de cadera, algo para chequear con el veterinario en controles periódicos','Problemas de piel bajo el pelaje cordado, conviene comentarlo si aparecen molestias o cambios','Torsión gástrica, por ser una raza de tamaño grande, es un tema para hablar con el veterinario sobre rutinas de alimentación','Problemas oculares como entropión, vale la pena mencionarlo en las visitas de rutina']::text[],'{"cachorro": "Necesita socialización temprana con personas y otros animales para que su instinto protector no se vuelva excesivo. El pelaje empieza a formar cordones alrededor de los seis meses y conviene aprender a manejarlo desde el vet o un especialista en la raza. La alimentación y el ritmo de crecimiento es bueno conversarlos con el veterinario, dado que es una raza grande.", "adulto": "Requiere ejercicio diario moderado, más orientado a la vigilancia y el trabajo que a la actividad intensa. El cuidado del pelaje cordado es exigente y necesita atención regular para evitar enredos, suciedad o humedad acumulada. Es un perro que valora tener un rol o espacio para ejercer su instinto guardián.", "senior": "Baja naturalmente su nivel de actividad y puede necesitar ajustes en la rutina de ejercicio y en la dieta, algo bueno para charlar con el veterinario. El pelaje sigue necesitando cuidado constante, aunque puede requerir ayuda extra para mantenerlo. Conviene prestar atención a signos de movilidad reducida o molestias articulares y consultarlo a tiempo."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','rhodesian-ridgeback',true,'Es originario de Zimbabue (antigua Rodesia), donde se lo criaba para cazar en jauría, incluso enfrentar leones, y para custodiar la granja familiar. Desciende de perros de caza europeos cruzados con perros nativos africanos, de los cuales heredó la característica cresta de pelo a contrapelo en el lomo.','Suele ser un perro leal y protector con su familia, aunque reservado o distante con los desconocidos. Es independiente y tiene carácter fuerte, por lo que agradece límites claros desde cachorro. Con otros perros puede mostrarse dominante si no socializa temprano.','Entre 32 y 41 kg, con una altura de 61 a 69 cm a la cruz.','Entre 10 y 12 años.',array['Displasia de cadera y de codo, algo para chequear con el veterinario','Sinus dermoides, una condición asociada a la línea de la cresta que conviene que el veterinario revise','Torsión gástrica o dilatación de estómago, tema para conversar sobre prevención con el veterinario','Hipotiroidismo, conviene monitorearlo con controles veterinarios periódicos','Alergias cutáneas, que el veterinario puede ayudar a identificar y manejar']::text[],'{"cachorro": "Necesita socialización temprana con personas y otros animales, dada su tendencia a ser reservado con extraños. El ejercicio debe ser moderado y progresivo para cuidar el desarrollo de sus articulaciones, evitando saltos o corridas intensas mientras crece. Conviene consultar con el veterinario sobre el plan de alimentación y vacunación adecuado para esta etapa.", "adulto": "Es un perro atlético que necesita ejercicio diario constante, como caminatas largas o carreras controladas. Su pelaje corto es fácil de mantener con cepillados ocasionales. Al ser una raza con carácter firme, se beneficia de rutinas claras y estimulación mental además de la física.", "senior": "Puede necesitar ajustar la intensidad del ejercicio a paseos más cortos y tranquilos, cuidando sus articulaciones. Los controles veterinarios periódicos cobran más importancia para detectar a tiempo cambios propios de la edad. La alimentación también puede necesitar ajustes, algo para definir junto al veterinario."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','border-terrier',true,'El Border Terrier viene de la zona fronteriza entre Inglaterra y Escocia, donde se lo usaba para cazar zorros y otros animales que amenazaban al ganado. Necesitaba ser resistente, ágil y capaz de meterse en cuevas y madrigueras.','Es un perro activo, curioso y con buena disposición hacia las personas, incluidos los niños. Conserva instinto cazador, así que puede mostrar interés en perseguir animales pequeños. Suele llevarse bien con otros perros si se socializa desde cachorro.','Entre 5 y 7 kg, con una altura de 25 a 28 cm aproximadamente.','Entre 12 y 15 años.',array['Problemas de cadera, algo para chequear con el veterinario en controles regulares','Afecciones oculares, conviene consultarlo en revisiones periódicas','Problemas de piel o alergias, un tema para conversar si aparecen picazón o irritaciones','Convulsiones o temblores episódicos, algo que se ha reportado en la raza y vale comentar con el veterinario','Tendencia a subir de peso si no tiene suficiente actividad, bueno charlarlo en los controles']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros perros y distintos ambientes, dado su temperamento activo. El ejercicio debe ser moderado mientras crece para no forzar las articulaciones, y conviene consultar con el veterinario un plan de alimentación adecuado para esta etapa.", "adulto": "Requiere paseos diarios y espacio para gastar energía, ya que es una raza con buen nivel de actividad. El pelaje áspero necesita cepillado regular y puede beneficiarse de un despojo periódico según indique un profesional. Es bueno mantener revisiones veterinarias de rutina para monitorear peso y salud general.", "senior": "Puede necesitar ajustes en la intensidad del ejercicio, manteniendo caminatas más cortas pero frecuentes. La alimentación conviene revisarla con el veterinario para adaptarla a sus necesidades energéticas. Los controles periódicos ayudan a detectar a tiempo cualquier cambio relacionado con la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('ave','guacamayo-escarlata',true,'El guacamayo escarlata es originario de las selvas tropicales de América Central y del Sur, desde México hasta Brasil. En su hábitat natural vive en bandadas y se alimenta principalmente de frutas y semillas. No es una raza en el sentido técnico, sino una especie silvestre que hoy convive con personas en hogares y centros de conservación.','Es un ave inteligente, curiosa y muy social, que suele formar un vínculo fuerte con su familia humana. Puede ser ruidosa y expresiva, y necesita interacción diaria para estar tranquila. Sin estímulo suficiente puede volverse ansiosa o desarrollar conductas destructivas.','Entre 900 gramos y 1,5 kilogramos, con una longitud total de 80 a 95 centímetros incluyendo la cola.','Entre 40 y 60 años, aunque en cautiverio con buenos cuidados puede vivir varias décadas más.',array['Problemas de comportamiento como picoteo de plumas, algo para conversar con el veterinario si aparece','Deficiencias nutricionales si la dieta no está bien balanceada, tema para revisar con el veterinario','Infecciones respiratorias, especialmente en ambientes con mala ventilación','Enfermedades del pico y las plumas, para consultar ante cualquier cambio visible','Estrés o ansiedad por aislamiento social, algo a charlar con un especialista en aves']::text[],'{"cachorro": "En la etapa joven necesita mucha socialización y estímulo para desarrollar confianza con las personas. La alimentación debe ser variada y consultada con el veterinario para asegurar un crecimiento sano. Es clave ofrecerle juguetes y espacio para explorar y masticar.", "adulto": "Un guacamayo adulto necesita tiempo diario fuera de la jaula para volar o moverse, y estímulo mental constante con juegos y interacción social. La dieta debe mantenerse variada, con frutas, verduras y semillas, siempre bajo la guía de un veterinario especializado en aves. El contacto social regular ayuda a prevenir el aburrimiento y el estrés.", "senior": "En la vejez puede reducir su nivel de actividad, aunque sigue necesitando estímulo mental y compañía. Es recomendable observar cambios en el apetito, el plumaje o el comportamiento y consultarlos con el veterinario. Mantener una rutina estable le da seguridad en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','boerboel',true,'El Boerboel es un mastín originario de Sudáfrica, desarrollado por los colonos boers para proteger las granjas de depredadores e intrusos. Se buscaba un perro grande, robusto y capaz de trabajar de forma independiente en zonas rurales.','Suele ser un perro tranquilo y seguro de sí mismo dentro de su familia, con fuerte instinto de guarda. Necesita una socialización temprana y constante porque puede mostrarse desconfiado con extraños. Es cariñoso con los suyos, aunque su tamaño y carácter dominante requieren un manejo firme y experimentado.','Entre 65 y 90 kilos, con una altura de 60 a 70 centímetros a la cruz.','Entre 9 y 11 años.',array['Displasia de cadera y codo, algo para chequear con el veterinario a medida que crece','Problemas de piel o alergias, conviene consultarlo si aparecen molestias frecuentes','Torsión gástrica, tema para conversar sobre hábitos de alimentación con el veterinario','Problemas cardíacos, bueno mencionarlo en los controles de rutina','Entropión u otras afecciones oculares, para revisar en los chequeos periódicos']::text[],'{"cachorro": "Es clave la socialización temprana con personas, otros animales y distintos ambientes, dado su tamaño adulto y su instinto protector. El ejercicio debe ser moderado para no forzar las articulaciones en crecimiento, y la alimentación tiene que acompañar ese desarrollo con el asesoramiento del veterinario.", "adulto": "Necesita ejercicio diario y actividades que lo estimulen mental y físicamente, aunque no es una raza hiperactiva. El pelaje corto pide poco mantenimiento, pero conviene revisar la piel con regularidad. Los controles veterinarios periódicos ayudan a seguir de cerca su salud articular y general.", "senior": "Con la edad puede reducir su actividad y conviene adaptar los paseos a su ritmo, cuidando las articulaciones. La alimentación también puede necesitar ajustes, siempre con indicación del veterinario. Los chequeos más frecuentes permiten detectar a tiempo cualquier cambio en su salud."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('equino','criollo',false,null,null,null,null,'{}','{"cachorro": null, "adulto": null, "senior": null}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('gato','himalayo',true,'El himalayo surgió en Estados Unidos e Inglaterra a mediados del siglo XX, cruzando persas con siameses para lograr el cuerpo y pelaje del persa con los puntos de color del siamés. Se desarrolló como gato de compañía y de exposición, no tuvo un uso utilitario.','Suele ser tranquilo y cariñoso, apegado a su familia y poco amigo de cambios bruscos. Muchos disfrutan de la calma del hogar más que de la actividad intensa. Como en cualquier gato, el carácter varía según la crianza y la socialización temprana.','Entre 3 y 5,5 kg, cuerpo compacto y de talla mediana.','Entre 9 y 15 años aproximadamente.',array['Problemas respiratorios asociados a la estructura facial achatada, algo para comentar con el veterinario','Enfermedad renal poliquística, conviene conversar sobre estudios preventivos','Problemas dentales por la conformación de la mandíbula','Afecciones oculares como lagrimeo excesivo, vale la pena consultarlo','Predisposición a la formación de nudos y bolas de pelo por su manto denso']::text[],'{"cachorro": "Necesita cepillado frecuente desde chico para acostumbrarse y evitar nudos en el pelaje largo. Es buen momento para socializarlo con personas y otros animales de forma gradual. La alimentación y el calendario de vacunas conviene definirlos con el veterinario.", "adulto": "El cepillado diario o casi diario sigue siendo clave para mantener el pelaje sano y evitar bolas de pelo. Le sienta bien una rutina estable, con juego moderado y espacios tranquilos para descansar. Los controles veterinarios periódicos ayudan a seguir de cerca su salud respiratoria y renal.", "senior": "Puede necesitar ayuda para mantener el aseo si se le dificulta moverse o llegar a ciertas zonas del cuerpo. Es buen momento para prestar atención a cambios en el apetito, la movilidad o la vista, y comentarlos con el veterinario. Un ambiente cómodo y sin escalones abruptos facilita su día a día."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','greyhound',true,'El Greyhound es una raza muy antigua, originaria de la región mediterránea y desarrollada principalmente en Gran Bretaña para la caza por vista y, más tarde, para las carreras. Su cuerpo está diseñado para alcanzar gran velocidad en distancias cortas.','Suele ser tranquilo y hasta perezoso dentro de casa, a pesar de su capacidad atlética. Es afectuoso con su familia y generalmente reservado con desconocidos. Muchos disfrutan largas siestas y necesitan solo períodos breves de actividad intensa.','Entre 27 y 40 kg, con una altura de 68 a 76 cm a la cruz.','Entre 10 y 13 años aproximadamente.',array['Sensibilidad a ciertos anestésicos y medicamentos, por su bajo porcentaje de grasa corporal, algo para comentar con el veterinario antes de cualquier procedimiento','Problemas dentales, por lo que conviene consultar sobre el cuidado bucal','Torsión gástrica, especialmente en perros de pecho profundo, un tema para hablar con el veterinario sobre hábitos de alimentación','Sensibilidad cutánea o tendencia a lastimarse la piel fácilmente, dado su pelaje fino','Cardiopatías, algo que puede evaluarse en controles de rutina']::text[],'{"cachorro": "Necesita socialización temprana y aprendizaje de límites, ya que puede desarrollar instinto de persecución fuerte. El ejercicio debe ser moderado mientras crece, evitando saltos o esfuerzos excesivos que fuercen las articulaciones en desarrollo. Es buen momento para consultar con el veterinario sobre alimentación y plan de vacunación.", "adulto": "Agradece salidas con espacio para correr libremente en zonas seguras, aunque el resto del día suele ser bastante hogareño. Su pelaje corto requiere poco mantenimiento, pero conviene protegerlo del frío con abrigo en climas duros. Una alimentación equilibrada y controles veterinarios regulares ayudan a mantenerlo en buen estado.", "senior": "Puede reducir su actividad y necesitar superficies blandas para dormir, ya que sus articulaciones y músculos delgados son más sensibles con la edad. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a la salud dental y cardíaca. La dieta puede necesitar ajustes, algo que conviene charlar con el veterinario."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','presa-canario',true,'Es una raza originaria de las Islas Canarias, España, desarrollada como perro de trabajo en fincas para el manejo de ganado y la guarda de propiedades. También se lo conoce como Dogo Canario.','Suele ser un perro seguro de sí mismo, territorial y muy apegado a su familia. Con extraños tiende a mostrarse reservado o desconfiado, por lo que la socialización temprana marca una diferencia grande. No es una raza para el primer perro de la familia ni para dueños sin experiencia en manejo de perros grandes y dominantes.','Entre 38 y 57 kilos, con una altura de 55 a 65 centímetros aproximadamente.','Entre 9 y 11 años.',array['Displasia de cadera y codo, algo para chequear con el veterinario a lo largo de su vida','Problemas de piel o alergias, que conviene consultar si aparecen picazón o irritaciones recurrentes','Torsión gástrica, tema para hablar con el veterinario sobre horarios y modo de alimentación','Problemas oculares como entropión, para revisar en controles periódicos','Cuestiones de peso y articulaciones, por su contextura grande y pesada']::text[],'{"cachorro": "La socialización temprana con personas, otros animales y distintos entornos es clave en esta etapa, dada su tendencia natural a la desconfianza. El ejercicio debe ser moderado para no forzar el crecimiento de sus articulaciones, y la alimentación tiene que acompañar ese desarrollo, siempre con la guía del veterinario. También es el momento ideal para trabajar la obediencia básica con constancia y calma.", "adulto": "Necesita ejercicio diario y tareas o estímulos que le den un propósito, ya que es un perro trabajador por naturaleza. El pelaje corto se mantiene fácil con cepillados regulares. Los controles veterinarios periódicos ayudan a seguir de cerca su peso y su salud articular.", "senior": "Los paseos pueden acortarse pero conviene mantenerlos, adaptando la intensidad a su movilidad. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a articulaciones, vista y peso corporal. La comodidad en el descanso, con superficies blandas, ayuda a cuidar sus articulaciones."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('gato','munchkin',true,'El Munchkin surgió en Estados Unidos a principios de los años noventa, a partir de una mutación genética natural que produce patas cortas. No se criaba para ningún trabajo en particular, sino que se desarrolló como gato de compañía por su aspecto llamativo.','Suele ser un gato curioso, activo y sociable, que se adapta bien a la vida en interior. Muchos disfrutan del juego y mantienen una actitud juguetona incluso de adultos. Como en cualquier gato, el carácter varía según cada individuo y su crianza.','Entre 2.5 y 4 kilos, con una altura notablemente baja debido a sus patas cortas características.','Entre 12 y 15 años aproximadamente.',array['Problemas de columna vertebral, algo para conversar con el veterinario dado la conformación corporal de la raza','Osteoartritis o desgaste articular, un tema para monitorear con el veterinario a lo largo de su vida','Lordosis (curvatura excesiva de la columna), conviene charlarlo con el veterinario si se nota algo inusual en la postura','Cardiomiopatía hipertrófica, vale la pena mencionarlo en los controles veterinarios de rutina']::text[],'{"cachorro": "Necesita socialización temprana y juego moderado que respete su estructura corporal, evitando saltos muy altos o esfuerzos bruscos. La alimentación debe ser acorde a su etapa de crecimiento, y conviene consultar con el veterinario sobre el desarrollo óseo y articular.", "adulto": "Se beneficia de estímulo mental y físico diario, con juguetes y espacios que no exijan saltos extremos. El cepillado regular ayuda a mantener el pelaje en buen estado, y los controles veterinarios periódicos son importantes para seguir de cerca su salud articular y cardíaca.", "senior": "En esta etapa conviene facilitar el acceso a lugares altos con rampas o escalones bajos, ya que la movilidad puede disminuir. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a signos de dolor o rigidez que convenga evaluar profesionalmente."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('conejo','holandes-enano',true,'El Holandés Enano se desarrolló en los Países Bajos a principios del siglo XX, a partir de cruces de conejos pequeños salvajes con razas domésticas. Se buscaba fijar un tamaño reducido y hoy es una de las razas de conejo más populares como mascota de compañía.','Suele ser activo, curioso y con mucha energía para su tamaño. Algunos ejemplares son algo temerosos o asustadizos si no se los maneja con calma desde niños, aunque con paciencia se vuelven cariñosos y confiados. Cada conejo tiene su propio carácter, así que conviene ir conociéndolo de a poco.','Entre 0,5 y 1,1 kg de peso, con una altura pequeña y compacta.','Entre 7 y 10 años aproximadamente.',array['Problemas dentales, algo para revisar periódicamente con el veterinario','Predisposición a la obesidad si no tiene suficiente actividad, tema para charlar con el veterinario','Cuestiones oculares como buftalmia o glaucoma, que conviene consultar si se observa algo raro','Sensibilidad digestiva, por lo que cambios de dieta conviene comentarlos con el veterinario','Riesgo de golpe de calor por su tamaño pequeño, bueno conversarlo con el veterinario sobre el ambiente ideal']::text[],'{"cachorro": "En esta etapa necesita un espacio seguro para explorar y socialización gradual con las personas de la casa. La alimentación debe ser supervisada por el veterinario, priorizando heno de buena calidad desde temprano. Es un buen momento para acostumbrarlo a que lo manipulen con suavidad.", "adulto": "Necesita espacio para moverse y jugar todos los días, además de heno disponible de forma constante. El pelaje se beneficia de cepillados regulares, sobre todo en épocas de muda. Las revisiones veterinarias periódicas ayudan a detectar a tiempo cualquier tema de salud.", "senior": "Puede necesitar ajustes en la dieta y en el espacio para moverse con comodidad, algo que conviene charlar con el veterinario. Es buen momento para prestar más atención a cambios en el apetito, la movilidad o el comportamiento. Los controles veterinarios más frecuentes ayudan a acompañarlo mejor en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','xoloitzcuintle',true,'Es una raza originaria de México, con una presencia muy antigua entre los pueblos prehispánicos, que la consideraban un animal con significado especial dentro de sus creencias. Se la criaba como compañía y también cumplía un rol dentro de la vida doméstica de esas culturas. Existe en variedad con pelo y sin pelo, y en tres tamaños distintos.','Suele ser un perro leal y muy apegado a su familia, aunque puede mostrarse reservado con los desconocidos. Es atento y observador, lo que lo hace bastante bueno como perro de alerta en el hogar. Con socialización adecuada convive bien con niños y otros animales, aunque cada ejemplar tiene su propio carácter.','Entre 4 y 25 kg y entre 25 y 60 cm de altura, según la variedad (miniatura, intermedio o estándar).','Entre 12 y 15 años aproximadamente.',array['Sensibilidad de la piel, especialmente en la variedad sin pelo, algo para revisar con el veterinario','Cuidado con la exposición solar prolongada en ejemplares sin pelo','Tendencia a problemas dentales, un tema para conversar en los controles veterinarios','Cierta sensibilidad a temperaturas extremas, tanto frío como calor']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes para desarrollar confianza. Si es de la variedad sin pelo, conviene cuidar su piel de golpes y del sol desde chico. La alimentación y el ritmo de crecimiento son buenos temas para charlar con el veterinario.", "adulto": "Agradece paseos diarios y estímulo mental, ya que es un perro activo y curioso. La piel de los ejemplares sin pelo requiere atención regular, y conviene protegerlo del sol y del frío según la época. Los controles veterinarios periódicos ayudan a seguir de cerca su salud general.", "senior": "Puede necesitar rutinas de ejercicio más suaves y adaptadas a su energía. La piel y los dientes merecen atención constante, con revisiones veterinarias más frecuentes. Mantener un ambiente cómodo en cuanto a temperatura sigue siendo importante en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('pez','oscar',false,null,null,null,null,'{}','{"cachorro": null, "adulto": null, "senior": null}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('roedor','hamster-roborovski',true,'El hámster Roborovski proviene de las estepas desérticas de Mongolia, Kazajistán y el norte de China, donde vive en madrigueras excavadas en zonas áridas. Se lo empezó a criar como mascota por su tamaño pequeño y su carácter activo, más tardíamente que otras especies de hámster.','Es el más pequeño y veloz de los hámsters domésticos, con movimientos rápidos y constantes. Suele ser más esquivo al contacto humano que otras variedades, aunque con manejo paciente y frecuente puede llegar a tolerar bien la interacción. No es la mejor opción para niños muy pequeños porque es difícil de sostener en la mano.','Entre 4 y 5 centímetros de largo aproximadamente, y un peso de 20 a 25 gramos.','Entre 2 y 3 años, aunque algunos ejemplares llegan a los 3 y medio.',array['Problemas dentales por crecimiento continuo de los dientes, algo para revisar con el veterinario','Sensibilidad respiratoria ante ambientes húmedos o con corrientes de aire','Obesidad si el espacio para correr es insuficiente','Estrés por manipulación excesiva o inadecuada']::text[],'{"cachorro": "Necesita un espacio seguro con sustrato profundo para excavar y esconderse, ya que es una conducta natural de la especie. El destete y la separación de la madre deben respetar los tiempos recomendados por el veterinario. Conviene empezar a acostumbrarlo suavemente a la presencia humana sin forzar el contacto.", "adulto": "Requiere una jaula amplia con rueda de ejercicio grande, ya que es muy activo y corre largas distancias durante la noche. La dieta debe ser variada, con mezcla comercial para hámster y algunos vegetales frescos en pequeñas cantidades. Si se nota cambios en el pelaje, el peso o la actividad, es buen momento para consultar al veterinario.", "senior": "Puede reducir su nivel de actividad y dormir más horas durante el día. Es útil observar cualquier cambio en el apetito, la movilidad o el aspecto del pelaje y comentarlo con el veterinario. El ambiente debe mantenerse estable en temperatura, evitando corrientes de aire y cambios bruscos."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','kuvasz',true,'El Kuvasz es una raza húngara antigua, criada originalmente para proteger rebaños de ovejas y a sus pastores frente a depredadores. Con el tiempo también se lo usó como guardián de propiedades y compañía de familias nobles.','Es un perro independiente, protector y muy atento a su familia, aunque puede mostrarse reservado o desconfiado con extraños. Suele necesitar un dueño con experiencia que le marque límites claros desde cachorro, ya que tiende a tomar decisiones por su cuenta. Con su gente suele ser leal y cariñoso.','Entre 30 y 52 kg, con una altura de 66 a 76 cm según sea macho o hembra.','De 10 a 12 años aproximadamente.',array['Displasia de cadera y de codo, algo para conversar con el veterinario sobre controles articulares','Torsión gástrica, por ser una raza de tórax profundo','Problemas de tiroides','Sensibilidad a ciertos anestésicos, bueno tenerlo en cuenta antes de una cirugía','Osteocondritis en las etapas de crecimiento']::text[],'{"cachorro": "Necesita socialización temprana y consistente para que su instinto protector no se convierta en desconfianza excesiva. El ejercicio debe ser moderado y sin saltos ni carreras forzadas mientras crece, para no forzar las articulaciones. Es buen momento para consultar con el veterinario un plan de alimentación acorde a su crecimiento rápido.", "adulto": "Requiere ejercicio diario constante, tanto físico como mental, ya que es un perro activo y con instinto de trabajo. Su pelaje denso necesita cepillado regular, sobre todo en las épocas de muda. Conviene mantener revisiones veterinarias periódicas para monitorear articulaciones y tiroides.", "senior": "Los paseos pueden espaciarse pero conviene mantener alguna actividad suave para preservar masa muscular y movilidad. Es un buen momento para chequeos veterinarios más frecuentes, prestando atención a signos de dolor articular o cambios de energía. La dieta suele necesitar ajustes, algo para charlar con el veterinario."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','perro-de-agua-espanol',true,'Es una raza originaria de las zonas costeras y rurales de España, especialmente Andalucía, donde se usaba como perro de pastoreo y también para ayudar a los pescadores con las redes. Su pelaje característico, en forma de cordones, lo protegía del agua y del trabajo en el campo.','Suele ser un perro activo, inteligente y muy apegado a su familia. Tiende a ser protector y algo desconfiado con los desconocidos, aunque esto varía según la socialización que haya tenido. Necesita sentirse parte de las actividades diarias y no lleva bien quedarse solo por mucho tiempo.','Entre 14 y 22 kg, con una altura de 38 a 50 cm según el sexo y la línea.','Entre 12 y 14 años.',array['Displasia de cadera, algo para chequear con el veterinario en controles de rutina','Problemas oculares hereditarios, conviene consultarlo en los chequeos periódicos','Hipotiroidismo, tema para conversar si aparecen cambios de energía o peso','Otitis, por la forma de las orejas y la tendencia a mojarse, bueno revisarlo con el veterinario']::text[],'{"cachorro": "Es clave socializarlo temprano con personas, otros animales y distintos ambientes, dado su carácter algo reservado. El pelaje empieza a formar cordones con el tiempo y conviene consultar con el veterinario o un groomer especializado cómo manejarlo desde chico. También necesita mucha estimulación mental y física, sin exagerar el ejercicio mientras crece.", "adulto": "Es un perro que necesita ejercicio diario y tareas que lo mantengan ocupado, ya sea juego, natación o trabajo. El pelaje requiere un mantenimiento particular, con cortes periódicos en vez de cepillado tradicional. La alimentación y el peso conviene chequearlos con el veterinario según su nivel de actividad.", "senior": "Con la edad puede bajar su ritmo, así que es bueno adaptar el ejercicio a lo que el cuerpo le pida. Las revisiones veterinarias más frecuentes ayudan a detectar a tiempo cambios articulares, de visión o de tiroides. El pelaje sigue necesitando cuidado regular, aunque puede simplificarse el corte según indique el veterinario o el groomer."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','bullmastiff',true,'El bullmastiff se originó en Inglaterra en el siglo XIX, cruzando mastines con bulldogs, para trabajar como perro guardián de las grandes propiedades rurales. Se buscaba un animal capaz de detener a un intruso sin necesidad de matarlo, así que se priorizó la fuerza junto con cierto control.','Suele ser un perro tranquilo y observador dentro de la casa, muy apegado a su familia. Con extraños puede mostrarse reservado o desconfiado, y necesita socialización temprana para manejar esas situaciones con calma. No es un perro que busque pelea, pero su tamaño y determinación piden un manejo responsable desde cachorro.','Entre 41 y 59 kg de peso, y entre 61 y 69 cm de altura a la cruz.','Entre 7 y 9 años aproximadamente.',array['Displasia de cadera y de codo, algo para hablar con el veterinario sobre el crecimiento y el peso','Torsión gástrica, conviene conversar sobre el manejo de las comidas y el ejercicio después de comer','Problemas oculares como el entropión, vale la pena que el veterinario revise los ojos en los controles','Ciertos tipos de tumores, un tema para preguntar sobre chequeos periódicos según la edad','Problemas cardíacos, algo para mencionar en los controles de rutina']::text[],'{"cachorro": "El crecimiento es rápido y el esqueleto todavía se está formando, así que conviene evitar ejercicio excesivo o saltos forzados y consultar con el veterinario sobre el ritmo de alimentación más adecuado. La socialización temprana con personas y otros animales es clave dada su tendencia a ser reservado con desconocidos.", "adulto": "Necesita paseos regulares pero no ejercicio extenuante, ya que es un perro de contextura pesada más que un atleta de resistencia. El pelaje corto pide poco mantenimiento, aunque conviene revisar la piel con frecuencia por los pliegues. Mantener un peso adecuado es importante para sus articulaciones, y eso conviene charlarlo con el veterinario.", "senior": "Con la edad puede volverse menos activo y conviene adaptar los paseos a su ritmo, sin dejar de estimularlo. Los controles veterinarios periódicos ayudan a detectar a tiempo cambios articulares, cardíacos u otros propios de la edad. Un colchón cómodo y evitar subir y bajar escaleras en exceso suele hacerle bien."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','cocker-spaniel-americano',true,'El Cocker Spaniel Americano se desarrolló en Estados Unidos a partir de ejemplares de Cocker Spaniel inglés llevados al país en el siglo XIX. Se los seleccionó por tamaño más pequeño y se usaban para la caza de aves, aunque hoy es sobre todo un perro de compañía.','Suele ser alegre, afectuoso y con muchas ganas de agradar a su familia. Se encariña fácilmente y busca estar cerca de las personas, aunque algunos ejemplares pueden ser sensibles o algo tímidos si no se socializan bien desde niños. Convive bien con niños y con otros animales cuando se lo cría en un ambiente calmo.','Entre 5,5 y 8 kg, con una altura de 34 a 39 cm aproximadamente.','Entre 12 y 15 años.',array['Problemas oculares como cataratas o glaucoma, conviene chequeos periódicos con el veterinario','Infecciones de oído, por la forma caída y la cantidad de pelo en esa zona','Afecciones de piel y alergias, vale la pena consultarlo si hay picazón frecuente','Displasia de cadera, algo para conversar en los controles de rutina','Problemas cardíacos, el veterinario puede orientar sobre controles según la edad']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes para desarrollar un carácter equilibrado. El pelaje empieza a requerir cepillado regular desde chico para evitar nudos, y conviene que el veterinario guíe el plan de vacunación y alimentación.", "adulto": "Requiere ejercicio diario moderado, como paseos y algo de juego, para mantenerse en buen peso y estado de ánimo. El pelaje necesita cepillado frecuente y revisión regular de las orejas por su forma caída. Una alimentación balanceada acorde a su nivel de actividad ayuda a evitar el sobrepeso.", "senior": "Puede necesitar paseos más cortos y tranquilos, respetando su ritmo. Es un buen momento para chequeos veterinarios más seguidos, prestando atención a la vista, el oído y las articulaciones. El pelaje sigue necesitando cuidado regular para mantenerlo cómodo y sin enredos."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','bichon-habanero',false,null,null,null,null,'{}','{"cachorro": null, "adulto": null, "senior": null}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('cobaya','cobaya-americana',true,'La cobaya Americana es una de las razas más antiguas, descendiente directa de las cobayas domesticadas por pueblos andinos en Sudamérica. Se popularizó en Estados Unidos y Europa como mascota y como animal de exposición por su pelaje corto y su forma robusta. Es la variedad de referencia sobre la que se desarrollaron muchas otras razas de cobaya.','Suele ser sociable y curiosa, y tiende a adaptarse bien a la vida en familia. Con manejo frecuente desde joven suele mostrarse tranquila al alzarla y explorar su entorno. Como toda cobaya, agradece la compañía de otra de su especie y puede volverse más reservada si vive sola.','Entre 900 g y 1,2 kg, con un cuerpo compacto de unos 20 a 25 cm de largo.','Entre 5 y 7 años, aunque algunas llegan a los 8 con buenos cuidados.',array['Problemas dentales relacionados con el desgaste de los dientes, algo para revisar con el veterinario','Sensibilidad a la falta de vitamina C en la dieta, un tema para conversar sobre la alimentación','Afecciones respiratorias, especialmente si hay cambios bruscos de temperatura','Problemas de piel u hongos, más frecuentes en ambientes húmedos','Cálculos urinarios, algo que conviene chequear si hay cambios en el comportamiento al orinar']::text[],'{"cachorro": "En esta etapa crece rápido y necesita una dieta rica en heno de buena calidad y alimento balanceado específico para cobayas jóvenes. Es un buen momento para acostumbrarla al manejo suave y a la convivencia con otras cobayas. Cualquier duda sobre el crecimiento o la alimentación conviene consultarla con el veterinario.", "adulto": "Necesita heno disponible todo el día, verduras frescas variadas y espacio para moverse y explorar. El pelaje corto requiere poco cepillado, pero conviene revisar uñas y dientes con regularidad. Mantener una rutina estable de compañía y actividad ayuda a su bienestar general.", "senior": "Puede volverse más sedentaria y conviene observar cambios en el peso, el apetito o la movilidad. La dieta y el espacio se pueden ajustar según sus necesidades, siempre con la orientación del veterinario. Los controles periódicos ayudan a detectar a tiempo cualquier cambio propio de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','whippet',true,'El whippet es originario de Inglaterra, donde se lo desarrolló en el siglo XIX a partir de galgos y otras razas veloces. Se usaba para la caza de liebres y para carreras, aprovechando su velocidad en distancias cortas.','Suele ser un perro tranquilo y afectuoso dentro de casa, casi sedentario cuando no hace ejercicio. Con su familia tiende a ser cariñoso y algo apegado, aunque puede mostrarse reservado con extraños. Tiene fuerte instinto de persecución, así que conviene tener cuidado con animales pequeños o sueltos en espacios abiertos.','Entre 12 y 20 kg de peso, y entre 44 y 51 cm de altura a la cruz aproximadamente.','Entre 12 y 15 años en promedio.',array['Sensibilidad a ciertos anestésicos y medicamentos, algo típico de razas de cuerpo delgado, para conversar con el veterinario antes de cualquier procedimiento','Problemas de piel o heridas por su pelaje corto y poca grasa corporal','Afecciones oculares, conviene consultarlo en los controles de rutina','Problemas cardíacos que pueden monitorearse en chequeos periódicos','Baja tolerancia al frío por su escasa grasa corporal, algo para tener en cuenta más que para tratar médicamente']::text[],'{"cachorro": "Necesita socialización temprana y estímulos variados para acostumbrarse a distintos entornos y sonidos. El ejercicio debe ser moderado mientras crece, evitando saltos o carreras muy intensas hasta que el veterinario confirme que su desarrollo óseo lo permite. La alimentación en esta etapa conviene planificarla con el veterinario según su ritmo de crecimiento.", "adulto": "Disfruta de sesiones cortas de carrera libre combinadas con paseos tranquilos, ya que es un corredor de velocidad más que de resistencia. Su pelaje corto requiere poco mantenimiento, aunque agradece abrigo en días fríos. Las revisiones veterinarias periódicas ayudan a seguir de cerca su salud general.", "senior": "Con la edad puede necesitar paseos más breves y superficies blandas para dormir, ya que tiene poca masa muscular protectora en las articulaciones. Es buen momento para chequeos veterinarios más frecuentes, sobre todo relacionados con el corazón y la vista. El abrigo en invierno se vuelve aún más importante en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','grifon-de-bruselas',true,'Es una raza originaria de Bélgica, donde se la criaba en Bruselas para cazar ratones en establos y cocheras. Con el tiempo se refinó como perro de compañía, cruzándose con razas como el Pug y el King Charles Spaniel. Hoy se la conoce sobre todo como perro de familia.','Suele ser un perro muy apegado a su gente, curioso y con mucha personalidad para su tamaño. Puede mostrarse reservado con extraños, aunque esto varía según cada individuo y su socialización. Tiende a disfrutar estar cerca de las personas y no siempre lleva bien quedarse solo por mucho tiempo.','Entre 3.5 y 6 kilos, con una altura aproximada de 18 a 20 centímetros a la cruz.','Entre 12 y 15 años.',array['Problemas respiratorios asociados a su cara achatada, algo para conversar con el veterinario sobre todo en épocas de calor','Afecciones oculares, dado que sus ojos son grandes y prominentes','Dificultades en el parto, algo habitual en razas de cabeza grande y tamaño pequeño','Problemas de columna o de discos intervertebrales','Sensibilidad a temperaturas extremas']::text[],'{"cachorro": "Es un buen momento para socializarlo con distintas personas, sonidos y situaciones, ya que esto influye mucho en su carácter adulto. La alimentación y el ritmo de crecimiento conviene charlarlos con el veterinario, dado su tamaño pequeño. El pelaje necesita cepillado regular, más si es de variedad dura.", "adulto": "Necesita paseos diarios moderados, sin exigencias extremas de ejercicio. El pelaje pide cepillado frecuente y, en la variedad de pelo duro, un mantenimiento especial que muchas familias resuelven con ayuda profesional. Conviene prestar atención a su respiración en días de calor y evitar el sobreesfuerzo.", "senior": "Los chequeos veterinarios periódicos toman más importancia, especialmente para monitorear ojos, respiración y articulaciones. Los paseos pueden acortarse pero siguen siendo importantes para su bienestar. Es buen momento para ajustar la dieta según su nivel de actividad, siempre con orientación veterinaria."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','chino-crestado',true,'Es una raza antigua asociada a México, aunque su rastro se encuentra en varias culturas precolombinas de América. Se la valoraba como compañía y también se le atribuían usos medicinales tradicionales, como fuente de calor corporal. Existe en variedad sin pelo y en variedad con pelo, llamada ''powderpuff''.','Suele ser una raza afectuosa y muy apegada a su familia, a veces reservada con desconocidos. Es activa e inteligente, disfruta del contacto humano y no lleva bien la soledad prolongada. Con buena socialización temprana suele convivir bien con otros animales.','Entre 2 y 5 kg, con una altura de 23 a 33 cm aproximadamente.','Entre 12 y 14 años.',array['Problemas dentales, algo frecuente de conversar con el veterinario por la estructura de la boca','Sensibilidad de piel en la variedad sin pelo, incluyendo reacciones al sol o irritaciones','Luxación de rótula, conviene chequearla en controles de rutina','Problemas oculares, vale la pena consultarlo en los chequeos periódicos','Sensibilidad a temperaturas extremas, especialmente frío, en la variedad sin pelo']::text[],'{"cachorro": "Es un buen momento para socializarlo con personas, otros animales y distintos ambientes. La piel de los cachorros sin pelo necesita cuidado especial frente al sol y el frío, y conviene consultar con el veterinario sobre productos adecuados. La alimentación en esta etapa debe acompañar su crecimiento, siempre con orientación profesional.", "adulto": "Necesita paseos diarios y estímulo mental, aunque no requiere ejercicio extremo. La piel de la variedad sin pelo pide cuidado regular con protección solar e hidratación, mientras que la variedad con pelo necesita cepillado frecuente. Los controles veterinarios periódicos ayudan a seguir de cerca su salud dental y de piel.", "senior": "Suele mantenerse activo pero conviene ajustar la intensidad de los paseos a su ritmo. La piel y las articulaciones piden más atención en esta etapa, así que los chequeos veterinarios regulares son importantes. Un ambiente cálido y cómodo lo ayuda a sentirse bien, sobre todo en la variedad sin pelo."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('gato','burmes',true,'El Burmés desciende de gatos de Birmania (actual Myanmar), llevados a Estados Unidos en los años 30 donde se consolidó la raza cruzándolos con siameses. Se los criaba como gatos de compañía, apreciados por su cercanía con las personas.','Suele ser un gato sociable y muy apegado a su familia, que busca estar cerca y participar de lo que pasa en la casa. Tiende a ser curioso y activo, con tendencia a seguir a su gente de habitación en habitación. Convive bien con otros animales y con niños si se lo trata con respeto.','Entre 3.5 y 5.5 kg, con un cuerpo compacto y musculoso más pesado de lo que parece.','Entre 12 y 16 años.',array['Problemas de cálculos urinarios, algo para conversar con el veterinario','Predisposición a hipopotasemia (niveles bajos de potasio), tema para consultar','Cuestiones craneofaciales asociadas a ciertas líneas, para revisar con el veterinario','Diabetes, condición a monitorear con el veterinario','Problemas oculares, para chequear en controles periódicos']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes, ya que es una etapa clave para su carácter sociable. La alimentación debe ser acorde a su crecimiento, y conviene consultar al veterinario sobre el plan de vacunación y desparasitación. El juego activo ayuda a canalizar su energía natural.", "adulto": "Un gato Burmés adulto necesita estímulo mental y físico, con juguetes y espacios para trepar o explorar. El pelaje corto requiere poco mantenimiento, un cepillado ocasional alcanza. La alimentación debe controlarse para evitar sobrepeso, y los controles veterinarios periódicos ayudan a detectar a tiempo cualquier tema de salud.", "senior": "En la etapa senior conviene prestar atención a cambios en el apetito, la movilidad o el comportamiento, y comentarlos con el veterinario. Los chequeos más frecuentes ayudan a seguir de cerca su salud general. Mantener un ambiente cómodo y accesible, con menos esfuerzo para saltar o trepar, mejora su calidad de vida."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','bouvier-de-flandes',true,'Es una raza belga, originaria de la región de Flandes, criada originalmente para arrear ganado, tirar carros y como perro de granja todo terreno. También se usó como perro policial y militar por su versatilidad y fuerza.','Suele ser un perro leal y protector con su familia, con tendencia a mostrarse reservado o desconfiado con extraños. Es inteligente y trabajador, lo que lo hace responder bien a la actividad física y mental, aunque puede ser testarudo si no encuentra estímulos.','Entre 27 y 40 kg, con una altura de 59 a 68 cm aproximadamente.','Entre 10 y 12 años en promedio.',array['Displasia de cadera, algo para charlar con el veterinario en controles regulares','Torsión gástrica, conviene consultar sobre pautas de alimentación y ejercicio','Problemas oculares, como entropión, que se pueden chequear en visitas de rutina','Atrofia progresiva de retina, tema para conversar si hay antecedentes en la línea','Cuestiones de piel o pelaje por su doble capa densa, bueno mencionarlo en consultas de rutina']::text[],'{"cachorro": "Necesita socialización temprana con personas y otros animales, dada su tendencia a la reserva con extraños. El ejercicio debe ser moderado en esta etapa para no forzar el desarrollo de sus articulaciones, y conviene consultar con el veterinario un plan de alimentación acorde a su crecimiento.", "adulto": "Requiere ejercicio diario constante, tanto físico como mental, porque es un perro con energía y necesidad de propósito. Su pelaje denso y áspero pide cepillado frecuente para evitar nudos, y los controles veterinarios periódicos ayudan a monitorear su salud articular y digestiva.", "senior": "Puede necesitar ajustes en la rutina de ejercicio, con paseos más cortos pero regulares para mantener movilidad. Es buen momento para chequeos veterinarios más seguidos, prestando atención a signos de dolor articular o cambios de comportamiento."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','cavalier-king-charles-spaniel',true,'Esta raza viene de Inglaterra, donde se la criaba como perro de compañía para la nobleza, retratado en muchos cuadros de los siglos XVII y XVIII. Su nombre hace referencia al rey Carlos II, que era muy aficionado a estos perros. Con el tiempo se consolidó como un spaniel pequeño pensado para vivir cerca de las personas, no para trabajar en el campo.','Suele ser un perro afectuoso y sociable, que busca estar cerca de su familia y se adapta bien a la vida en interior. Tiende a llevarse bien con niños y con otros animales, aunque como todo perro necesita una buena socialización desde cachorro. Es común que sea dócil y receptivo al entrenamiento con refuerzo positivo.','Entre 5,5 y 8 kg de peso, con una altura aproximada de 30 a 33 cm a la cruz.','Entre 9 y 14 años aproximadamente.',array['Problemas cardíacos, algo para chequear con controles veterinarios periódicos a lo largo de su vida','Displasia de cadera, conviene conversarlo con el veterinario sobre todo si se nota cojera o dificultad para moverse','Afecciones oculares, vale la pena consultar si hay lagrimeo excesivo o cambios visibles en los ojos','Problemas de oído dada la forma de sus orejas caídas, tema para revisar en las visitas de rutina','Siringomielia, una condición neurológica asociada a la raza que conviene charlar con el veterinario si aparecen signos como rascado excesivo en cuello u hombros']::text[],'{"cachorro": "Es un buen momento para exponerlo a distintas personas, sonidos y situaciones, siempre de forma gradual y positiva. El pelaje todavía es corto pero conviene ir acostumbrándolo al cepillado desde chico. La alimentación y el calendario de vacunas conviene planificarlos junto al veterinario.", "adulto": "Necesita paseos diarios moderados, no es una raza que requiera ejercicio intenso pero sí constante. El pelaje semilargo pide cepillado frecuente para evitar nudos, sobre todo en las orejas. Es buen momento para mantener controles veterinarios regulares, dada la asociación de la raza con temas cardíacos.", "senior": "Puede necesitar paseos más cortos y tranquilos, respetando su ritmo. Los controles veterinarios se vuelven más importantes para monitorear el corazón, las articulaciones y la vista. La dieta también suele necesitar ajustes en esta etapa, algo para definir junto al veterinario."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('equino','pura-sangre-ingles',true,'El Pura Sangre Inglés se desarrolló en Inglaterra en los siglos XVII y XVIII, cruzando yeguas locales con sementales árabes, turcos y berberiscos. Se crió específicamente para la velocidad en carreras, y hoy es la base de gran parte del turf mundial.','Suele ser un caballo enérgico, sensible y muy atento a su entorno. Responde bien a un manejo constante y calmo, y puede mostrarse nervioso o reactivo si percibe tensión en las personas o cambios bruscos en su rutina. Con trabajo consistente y buen trato forma vínculos fuertes con quienes lo cuidan.','Entre 450 y 550 kg, con una alzada aproximada de 1,60 a 1,70 metros a la cruz.','Entre 25 y 28 años, aproximadamente.',array['Problemas en tendones y ligamentos de los miembros, algo para conversar con el veterinario especialmente si hace actividad física intensa','Úlceras gástricas, más frecuentes en caballos con historial de entrenamiento o competencia','Fracturas óseas asociadas a la estructura fina de sus patas, un tema para evaluar según el nivel de ejercicio','Problemas respiratorios en vías altas y bajas, algo a monitorear con revisiones periódicas','Sensibilidad digestiva ante cambios bruscos de alimentación, conviene consultarlo con el veterinario']::text[],'{"cachorro": "En la etapa de potrillo necesita espacio para moverse en libertad y contacto temprano con otros caballos para socializar bien. La alimentación en esta fase es clave para un desarrollo óseo adecuado, así que conviene planificarla con el veterinario.", "adulto": "Requiere ejercicio regular acorde a su nivel de actividad, ya sea trabajo, paseo o descanso activo en potrero. El pelaje y los cascos necesitan revisión periódica, y la dieta debe ajustarse según el gasto energético real del animal.", "senior": "Con los años conviene adaptar el ejercicio a un ritmo más suave y prestar atención a signos de rigidez o pérdida de peso. Los controles veterinarios más frecuentes ayudan a detectar a tiempo cambios propios de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('conejo','jersey-wooly',true,'El Jersey Wooly se desarrolló en Estados Unidos, en Nueva Jersey, durante los años 80, cruzando conejos de angora francesa con conejos enanos holandeses. Se buscaba un conejo pequeño con pelaje lanudo pero de cuidado más manejable que el angora. Se difundió principalmente como mascota y como conejo de exposición.','Suele ser tranquilo y dócil, con buena disposición para el manejo y el contacto humano. Es de tamaño pequeño, lo que lo hace apto para espacios reducidos, aunque igual necesita salir de la jaula y moverse todos los días. Cada conejo tiene su propio carácter, algunos son más curiosos y otros más reservados.','Entre 1 y 1.5 kg aproximadamente, con un cuerpo compacto y redondeado.','Entre 7 y 10 años, según el cuidado y la genética.',array['Enredos y nudos en el pelaje lanudo, algo para revisar seguido y conversar con el veterinario si aparecen zonas irritadas','Problemas dentales, como en muchos conejos, conviene charlarlo en los controles de rutina','Estasis gastrointestinal, algo a monitorear junto al veterinario ante cambios en el apetito o las heces','Golpe de calor por su pelaje denso, vale la pena preguntar cómo manejar la temperatura ambiente','Sarna u otros problemas de piel, para consultar si se nota picazón o pérdida de pelo excesiva']::text[],'{"cachorro": "En esta etapa necesita una dieta adecuada para su crecimiento, con heno de buena calidad como base y consultas al veterinario sobre la introducción de otros alimentos. Es un buen momento para acostumbrarlo suavemente al manejo y al cepillado, ya que su pelaje lanudo va a requerir atención constante. La socialización temprana con personas y con cuidado tranquilo ayuda a que sea un conejo confiado.", "adulto": "El cepillado frecuente es clave para evitar nudos y enredos en su pelaje característico. Necesita espacio para moverse fuera de la jaula todos los días y una dieta con heno, verduras frescas y una porción moderada de alimento balanceado. Los controles veterinarios periódicos ayudan a seguir de cerca su salud dental y digestiva.", "senior": "Con la edad puede volverse menos activo, así que conviene observar cambios en el peso, el apetito o la movilidad. El pelaje puede necesitar más cuidado todavía, y el ambiente debe mantenerse cómodo en cuanto a temperatura. Las visitas al veterinario con más frecuencia ayudan a detectar a tiempo cualquier cambio propio de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','borzoi',true,'El Borzoi viene de Rusia, donde se lo criaba desde hace siglos como perro de caza mayor, especialmente para perseguir lobos gracias a su velocidad y su vista aguda. Era también un símbolo de estatus entre la nobleza rusa.','Suele ser tranquilo y reservado dentro de la casa, con un temperamento independiente y algo distante con extraños. Tiene un fuerte instinto de persecución, así que conviene tener cuidado con animales pequeños sueltos. Con su familia suele mostrarse afectuoso aunque no siempre efusivo.','Entre 27 y 48 kg, con una altura de 68 a 78 cm aproximadamente.','Entre 9 y 11 años en promedio.',array['Torsión gástrica o dilatación de estómago, algo para conversar con el veterinario dado su pecho profundo','Sensibilidad a ciertos anestésicos por su bajo porcentaje de grasa corporal, tema para charlar antes de cualquier procedimiento','Problemas cardíacos, conviene mencionarlo en los controles de rutina','Cuestiones oculares, vale la pena chequearlas periódicamente','Displasia de cadera, aunque menos frecuente que en otras razas grandes']::text[],'{"cachorro": "Necesita socialización temprana y un crecimiento controlado, evitando ejercicio muy intenso mientras se desarrollan los huesos y articulaciones. La alimentación en esta etapa conviene consultarla con el veterinario para acompañar bien su crecimiento rápido.", "adulto": "Agradece caminatas largas y espacios seguros donde pueda correr, siempre con correa o en áreas cerradas por su tendencia a perseguir. El pelaje requiere cepillado regular para evitar nudos, y las comidas conviene dividirlas para reducir riesgos digestivos.", "senior": "Puede necesitar rutinas de ejercicio más suaves y colchones u superficies blandas para sus articulaciones. Los controles veterinarios periódicos ayudan a detectar a tiempo cualquier cambio propio de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','dogo-argentino',true,'Se desarrolló en Argentina a principios del siglo XX, a partir del cruce del viejo Dogo Córdoba con otras razas, para la caza mayor en el monte y como perro de trabajo y guarda en el campo. Fue reconocida oficialmente como raza en su país de origen y luego a nivel internacional.','Suele ser un perro leal y muy apegado a su familia, con instinto protector marcado. Con las personas que conoce tiende a mostrarse afectuoso, aunque puede ser reservado o desconfiado con extraños si no se lo socializa desde cachorro. Necesita límites claros y una conducción firme pero respetuosa.','Entre 40 y 45 kilos, con una altura de 60 a 68 centímetros aproximadamente.','Entre 10 y 12 años en promedio.',array['Displasia de cadera, un tema para conversar con el veterinario sobre control articular','Sordera congénita, algo que puede evaluarse con estudios específicos en cachorros','Problemas de piel o alergias, conviene charlarlo si aparecen irritaciones frecuentes','Cuestiones oculares, como entropión, para revisar en controles de rutina','Sensibilidad a ciertas anestesias, un punto para mencionar antes de cualquier procedimiento']::text[],'{"cachorro": "La socialización temprana es clave para esta raza, tanto con personas como con otros animales. Necesita ejercicio moderado pero controlado, evitando saltos o esfuerzos excesivos mientras crece, y una alimentación acorde a su desarrollo que conviene consultar con el veterinario. Las primeras rutinas de obediencia ayudan mucho a canalizar su energía.", "adulto": "Requiere actividad física diaria constante, ya que es un perro atlético y activo. El pelaje corto necesita poco mantenimiento, con cepillados ocasionales. Es buen momento para mantener chequeos veterinarios regulares y sostener el entrenamiento y la socialización aprendidos de cachorro.", "senior": "Los paseos pueden espaciarse o acortarse según lo que el cuerpo del perro vaya marcando. Es importante prestar atención a cambios en la movilidad o el comportamiento y comentarlos con el veterinario. Los controles periódicos ayudan a acompañar mejor esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('gato','manx',true,'El Manx es originario de la Isla de Man, en el mar de Irlanda, donde surgió de forma natural por una mutación genética aislada en la población felina local. Durante mucho tiempo se lo valoró como cazador de ratones en puertos y granjas de la isla.','Suele ser un gato sociable y apegado a su familia, que sigue a las personas por la casa y participa de la vida hogareña. Tiende a ser juguetón e inteligente, con buena disposición para convivir con niños y otras mascotas, aunque cada individuo tiene su propio carácter.','Entre 3,5 y 5,5 kg, con cuerpo compacto y redondeado.','Entre 8 y 14 años aproximadamente.',array['Alteraciones de columna vertebral relacionadas con la ausencia de cola, tema para conversar con el veterinario especialmente en cachorros','Problemas de médula espinal o del canal espinal, conviene evaluarlos desde temprano','Cuestiones digestivas como constipación, algo para monitorear con el veterinario','Displasia de cadera, vale la pena chequearla en controles de rutina','Sensibilidad en la zona pélvica o de las patas traseras, buen tema para consultar']::text[],'{"cachorro": "Es importante que el veterinario evalúe la columna y la movilidad de las patas traseras desde las primeras semanas de vida. La socialización temprana con personas y otros animales ayuda a formar un carácter equilibrado. La alimentación debe ajustarse a su crecimiento, siguiendo la guía del veterinario.", "adulto": "Necesita actividad física diaria y estímulos de juego, ya que es un gato activo y curioso. El pelaje requiere cepillado regular, más frecuente si es de pelo largo. Los controles veterinarios anuales ayudan a seguir de cerca la salud de su columna y cadera.", "senior": "Con la edad puede reducir su nivel de actividad, así que conviene adaptar el ambiente para que le resulte cómodo moverse. Es buen momento para chequeos veterinarios más frecuentes, atentos a la movilidad y la función digestiva. Mantener un peso adecuado ayuda a cuidar sus articulaciones."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','pastor-ovejero-belga-malinois',true,'Es una raza belga, originaria de la región de Malinas, desarrollada en el siglo XIX para el pastoreo de ovejas. Con el tiempo se destacó por su capacidad de trabajo y hoy se usa mucho en tareas policiales, militares y de rescate.','Es un perro enérgico, atento y muy orientado al trabajo, con un vínculo fuerte hacia su familia. Necesita estímulo mental y tareas para estar equilibrado, porque tiende a aburrirse si no tiene actividad. Con buena socialización suele convivir bien, aunque no siempre es el más indicado para un hogar tranquilo o sedentario.','Entre 20 y 30 kg, con una altura de 55 a 65 cm aproximadamente.','Entre 12 y 14 años.',array['Displasia de cadera y codo, algo para chequear con el veterinario en controles de rutina','Ciertas sensibilidades oculares, conviene consultarlo si hay señales','Problemas de tiroides, que el veterinario puede evaluar con análisis periódicos','Alergias cutáneas, buen tema para conversar si aparecen molestias en la piel','Epilepsia, una condición que amerita seguimiento veterinario si se sospecha']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes, siempre de forma gradual. El ejercicio debe ser moderado para no forzar las articulaciones en crecimiento, y conviene consultar al veterinario sobre el plan de vacunación y alimentación adecuada.", "adulto": "Requiere ejercicio diario intenso y tareas que lo mantengan mentalmente activo, como entrenamiento u obediencia. El pelaje se mantiene con cepillados regulares, y una alimentación equilibrada acorde a su nivel de actividad es clave. Los controles veterinarios periódicos ayudan a detectar a tiempo cualquier tema de salud.", "senior": "Con la edad puede necesitar rutinas de ejercicio más suaves, adaptadas a su movilidad. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a articulaciones, peso y estado general. La estimulación mental sigue siendo importante, aunque con menor exigencia física."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('roedor','hamster-chino',true,'El hámster chino viene del norte de China y Mongolia, donde se lo encontraba en zonas semidesérticas y de cultivo. No se lo criaba con un fin productivo como a otras especies, sino que llegó a la tenencia como mascota por su tamaño pequeño y su cuerpo alargado, distinto al de otros hámsters.','Suele ser un animal tranquilo pero bastante ágil y rápido, lo que hace que algunas familias lo encuentren más difícil de manejar en brazos que otras variedades. Con manejo frecuente y calmo desde joven tiende a acostumbrarse a la manipulación. Es de hábitos solitarios y no necesita ni conviene que conviva con otros hámsters adultos.','Entre 10 y 12 centímetros de largo y unos 30 a 45 gramos de peso.','Entre 2 y 3 años.',array['Es un tema para charlar con el veterinario la tendencia a desarrollar diabetes en algunos ejemplares.','Vale la pena consultar sobre el cuidado dental, ya que como todo roedor tiene dientes de crecimiento continuo.','Se puede preguntar por su piel y pelaje, sensibles a ambientes húmedos o mal ventilados.','Es bueno conversar sobre el riesgo de tumores, algo que puede aparecer con la edad en esta especie.','Conviene consultar sobre el manejo del estrés, ya que son animales que pueden verse afectados por cambios bruscos de entorno.']::text[],'{"cachorro": "En las primeras semanas necesita un espacio tranquilo, con temperatura estable y sin manipulación brusca. Es buen momento para acostumbrarlo de forma suave a la mano de la familia, con sesiones cortas y frecuentes. La alimentación debe ser variada y equilibrada, y ante cualquier duda sobre cantidades o tipo de alimento conviene preguntar al veterinario.", "adulto": "En esta etapa necesita una jaula con espacio suficiente para correr y una rueda de ejercicio acorde a su tamaño. El enriquecimiento con túneles, escondites y sustrato para escarbar le hace bien a su bienestar general. Los controles periódicos con el veterinario ayudan a detectar a tiempo cualquier cambio en su peso, piel o comportamiento.", "senior": "Con el paso del tiempo puede volverse más sedentario y es normal que duerma más horas. Hay que estar atento a cambios en el apetito, el pelaje o la movilidad, y comentarlos con el veterinario. Mantener un ambiente cálido, tranquilo y sin corrientes de aire le hace bien en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('reptil','tortuga-de-orejas-rojas',true,'Es originaria de las zonas cálidas del centro y sureste de Estados Unidos, especialmente de la cuenca del río Mississippi. Se popularizó como mascota en todo el mundo desde mediados del siglo XX por su tamaño manejable de cría y sus colores llamativos. Hoy se considera una especie invasora en muchas regiones donde fue liberada.','Es una tortuga activa y curiosa, que suele reconocer a quien la alimenta y acercarse cuando ve movimiento cerca del agua. No busca contacto físico como un mamífero, pero puede mostrarse tranquila si su ambiente está bien armado. Algunos ejemplares son más esquivos y prefieren esconderse ante manipulación frecuente.','Entre 15 y 30 cm de largo de caparazón, con hembras generalmente más grandes que los machos.','Entre 20 y 30 años en cautiverio, aunque con buenos cuidados algunos ejemplares viven más.',array['Problemas de caparazón relacionados con deficiencias de calcio o exposición inadecuada a luz UVB, para conversar con el veterinario','Infecciones respiratorias asociadas a temperaturas de agua o ambiente inadecuadas','Parásitos internos, sobre todo en ejemplares de origen silvestre o mal cuarentenados','Problemas de piel o caparazón por calidad de agua deficiente','Obesidad o crecimiento irregular por dietas desbalanceadas, tema para revisar con el veterinario']::text[],'{"cachorro": "En esta etapa necesita agua limpia, temperatura estable y una lámpara UVB adecuada para el desarrollo del caparazón. La alimentación debe variar entre proteína y vegetales, y conviene consultar con el veterinario la proporción correcta según su tamaño. El manejo debe ser breve y tranquilo para que se acostumbre sin estrés.", "adulto": "Necesita un espacio amplio con zona de agua y de tierra seca, además de UVB diaria. La dieta se ajusta con menos proteína animal y más vegetales que en la etapa joven. Los controles veterinarios periódicos ayudan a detectar cambios en el caparazón o el comportamiento a tiempo.", "senior": "Suele mantener buena actividad si el agua y la temperatura están bien reguladas, aunque puede volverse más sedentaria. Conviene observar el apetito y la movilidad, y consultar con el veterinario ante cualquier cambio notorio. El ambiente debe seguir limpio y estable para evitar infecciones asociadas a la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','coton-de-tulear',true,'El Coton de Tuléar viene de Madagascar, de la zona costera de Tuléar, donde se cree que llegó con marineros europeos y se cruzó con perros locales. Se convirtió en compañero de las familias y de la aristocracia malgache, apreciado más por su carácter que por trabajo alguno.','Suele ser un perro sociable, apegado a su familia y bastante adaptable a la vida en casa. Tiende a llevarse bien con niños y otros animales cuando se socializa desde cachorro. Es común que busque estar cerca de las personas y que disfrute de la compañía más que de la soledad.','Entre 3.5 y 6 kg, con una altura de 22 a 28 cm aproximadamente.','Entre 14 y 16 años.',array['Luxación de rótula, algo para chequear con el veterinario en controles de rutina','Problemas oculares, conviene hacer revisiones periódicas','Sensibilidad de piel, bueno conversarlo si aparecen irritaciones frecuentes','Alergias alimentarias, tema para charlar si hay síntomas digestivos o de piel']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes para desarrollar su carácter equilibrado. El pelaje empieza a requerir cepillado desde chico para evitar nudos. La alimentación y las vacunas conviene planificarlas con el veterinario desde el principio.", "adulto": "Requiere ejercicio moderado, con paseos diarios y algo de juego, sin necesitar grandes esfuerzos físicos. El pelaje largo pide cepillado frecuente, varias veces por semana, para mantenerlo sano. Los controles veterinarios anuales ayudan a seguir de cerca su salud general.", "senior": "Puede necesitar paseos más cortos y tranquilos, respetando su ritmo. Es buen momento para chequeos veterinarios más seguidos, sobre todo de articulaciones y vista. El pelaje y la higiene general siguen necesitando atención constante."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('reptil','tortuga-mordedora',true,'La tortuga mordedora, también llamada caimán, es nativa de humedales, ríos y pantanos del centro y sureste de Norteamérica. No se crió como mascota tradicional: es un animal salvaje que se popularizó en la tenencia doméstica por su aspecto llamativo y su tamaño.','Es un animal solitario y de comportamiento defensivo, no un reptil sociable ni de manejo frecuente. Tiende a permanecer quieto y evitar el contacto, pero puede reaccionar con mordidas fuertes si se siente amenazado o manipulado. No es una mascota para interactuar de forma directa, sobre todo con niños en la casa.','Puede alcanzar entre 15 y 35 kg de peso y un largo de caparazón de 40 a 70 cm, según el sexo y las condiciones de cría.','Entre 30 y 40 años en cautiverio, aunque hay registros de ejemplares que viven más.',array['Problemas de caparazón relacionados con calidad de agua o exposición a UV, para revisar con el veterinario','Deficiencias nutricionales si la dieta no está bien balanceada, tema para consultar con un especialista en reptiles','Infecciones respiratorias asociadas a temperaturas inadecuadas del agua o el ambiente','Problemas metabólicos óseos por falta de calcio o luz ultravioleta adecuada','Heridas o traumatismos por manejo inadecuado, algo para conversar sobre manejo seguro con el veterinario']::text[],'{"cachorro": "En esta etapa crece rápido y necesita un acuario o estanque amplio, con agua limpia y zona seca para tomar sol o luz UV. La alimentación debe ser variada y supervisada por un veterinario especializado en reptiles desde el principio, para asegurar un desarrollo óseo correcto.", "adulto": "Necesita un espacio grande, con buena filtración de agua y control de temperatura, ya que su tamaño aumenta considerablemente. El contacto físico debe ser mínimo y cuidadoso, priorizando la seguridad de las personas y del animal. Las revisiones periódicas con el veterinario ayudan a controlar su estado general y su alimentación.", "senior": "En la vejez puede reducir su actividad y apetito, por lo que conviene observar cambios de comportamiento o en el caparazón. Mantener la calidad del agua y la temperatura estable sigue siendo clave. Cualquier señal de letargo o pérdida de peso debe consultarse con el veterinario sin demora."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('pez','barbo-tigre',true,'El barbo tigre, o barbo sumatrano, es originario de los ríos y arroyos del sudeste asiático, especialmente Indonesia y la península de Malaca. No es una raza en el sentido tradicional sino una especie muy popular en acuarismo por su color y sus rayas llamativas. Se lo cría desde hace décadas para acuarios comunitarios de agua dulce.','Es un pez activo y curioso, que se mueve todo el tiempo explorando el acuario. En grupo suele estar más tranquilo, porque tiende a mordisquear las aletas de otros peces si está solo o en pocas cantidades. Convive mejor con compañeros de tamaño similar y de movimientos rápidos.','Entre 5 y 7 centímetros de largo en la edad adulta.','Entre 5 y 7 años con buenos cuidados.',array['Consultar con el veterinario sobre signos de estrés o agresividad cuando se mantiene en grupos muy chicos','Es un buen tema para hablar con el veterinario la aparición de manchas blancas o cambios en la piel, asociados a infecciones comunes en peces de acuario','Vale la pena preguntar sobre la calidad del agua y su relación con enfermedades branquiales','Consultar sobre parásitos externos, que pueden aparecer si el agua no se mantiene en buenas condiciones']::text[],'{"cachorro": "En la etapa juvenil necesita un acuario bien plantado con espacio para nadar y esconderse. Es importante mantenerlo en grupos de al menos cinco o seis individuos para que su comportamiento sea más equilibrado. La alimentación debe ser variada, con escamas y algo de alimento vivo o congelado, y ante cualquier duda sobre crecimiento o color conviene consultar al veterinario o especialista en peces.", "adulto": "En la etapa adulta sigue necesitando vivir en grupo y un acuario con buena filtración y temperatura estable. La alimentación variada ayuda a mantener su color y vitalidad. Los controles periódicos del agua son la forma más simple de prevenir problemas de salud, y si se nota algo raro en su comportamiento o aspecto, es buen momento para consultar al veterinario.", "senior": "Con los años puede volverse algo menos activo y hay que prestar atención a signos de letargo o pérdida de apetito. Mantener el agua limpia y estable sigue siendo la base del cuidado en esta etapa. Cualquier cambio notorio en su color, movimiento o forma de comer conviene comentarlo con el veterinario."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','pointer',true,'El Pointer es una raza inglesa desarrollada en el siglo XVII para la caza, especialmente para localizar y señalar aves con el cuerpo inmóvil. Se lo usaba mucho antes de que existieran las escopetas modernas, acompañando a los cazadores a campo abierto.','Es un perro activo, atento y con mucha energía para gastar, que suele mostrarse cariñoso y sociable con su familia. Tiende a llevarse bien con otros perros y a ser amigable con extraños, aunque necesita estímulo mental y físico para estar tranquilo en casa. Con niños generalmente es paciente, aunque su tamaño y ánimo pueden resultar mucho para los más pequeños.','Entre 20 y 30 kg, con una altura aproximada de 58 a 69 cm a la cruz.','Entre 12 y 14 años.',array['Displasia de cadera, algo para chequear con el veterinario en controles periódicos','Torsión gástrica, especialmente relevante por su contextura atlética y profunda del pecho','Problemas de tiroides, que conviene descartar si aparecen cambios de energía o peso','Sensibilidad ocular, vale comentarlo si se notan molestias o secreción','Sordera congénita en algunos ejemplares, un tema para conversar con el veterinario desde cachorro']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos entornos, ya que es una etapa clave para su carácter adulto. El ejercicio debe ser moderado para no forzar las articulaciones en crecimiento, y conviene consultar al veterinario sobre el plan de vacunación y alimentación adecuada.", "adulto": "Requiere ejercicio diario intenso, como caminatas largas o correr, porque es una raza con mucha resistencia y necesidad de actividad. Su pelaje corto es fácil de mantener con cepillados regulares, y es importante controlar el peso y la dieta según su nivel de actividad, consultando al veterinario ante cualquier duda.", "senior": "Con la edad puede necesitar rutinas de ejercicio más suaves, adaptadas a su movilidad y energía. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a la vista, las articulaciones y el estado general de salud."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('reptil','camaleon-velado',true,'El camaleón velado viene de las zonas montañosas y áridas de Yemen y Arabia Saudita, donde vivía en árboles y arbustos cerca de fuentes de agua. Se popularizó como mascota porque tolera mejor el cautiverio que otras especies de camaleón y es relativamente fácil de reproducir en criadero.','Es un animal solitario que no busca contacto ni cariño como lo haría un mamífero. Tiende a estresarse con el manipuleo frecuente y prefiere que lo observen antes que lo toquen. Cada ejemplar tiene su propio nivel de tolerancia al manejo, algunos aceptan mejor la interacción que otros.','Los machos llegan a unos 45 cm de largo y las hembras a unos 25 a 35 cm, con un peso que ronda entre 100 y 200 gramos según el sexo.','Entre 5 y 8 años los machos, y algo menos las hembras, que suelen vivir entre 4 y 6 años debido al desgaste de la puesta de huevos.',array['Problemas relacionados con déficit o exceso de calcio y vitamina D, algo para revisar con el veterinario según la exposición a luz UVB','Infecciones respiratorias asociadas a humedad o temperatura inadecuada en el terrario','Enfermedad ósea metabólica, un tema para conversar en los controles periódicos','Impactación digestiva por sustrato inadecuado, conviene charlarlo con el veterinario al armar el terrario','Deshidratación, frecuente en la especie y que vale la pena monitorear con el profesional']::text[],'{"cachorro": "Los camaleones jóvenes necesitan un terrario con buena ventilación, humedad controlada y acceso a luz UVB para el desarrollo óseo. La alimentación se basa en insectos vivos de tamaño acorde, y conviene consultar con el veterinario especializado en reptiles sobre la frecuencia y el aporte de calcio. El crecimiento es rápido, así que el espacio y las condiciones deben ajustarse seguido.", "adulto": "En esta etapa se estabiliza la rutina de alimentación e iluminación, pero hay que seguir respetando sus ciclos de luz y temperatura. Es buen momento para chequeos periódicos con el veterinario, sobre todo si es hembra y pone huevos, fecundados o no. El terrario debe tener suficiente altura y ramas para que pueda moverse y termorregular a gusto.", "senior": "Los camaleones mayores pueden mostrar menos apetito o movilidad más lenta, y ahí conviene afinar la observación diaria. Las visitas al veterinario ganan importancia para detectar a tiempo cualquier cambio metabólico u óseo. Mantener la humedad y temperatura estables sigue siendo clave, incluso más que antes."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('pez','danio-cebra',true,'El danio cebra es originario de los ríos y arroyos de agua dulce del sur de Asia, principalmente India, Bangladesh y Nepal. Se lo cría como pez de acuario desde hace décadas por su resistencia, su facilidad de cuidado y sus llamativas rayas horizontales. También es muy usado en investigación científica por su genética bien estudiada.','Es un pez activo, curioso y bastante sociable con sus congéneres. Se mueve todo el tiempo por el acuario y suele convivir bien con otras especies pacíficas de tamaño similar. Le gusta nadar en grupo, así que se siente más cómodo y seguro cuando hay varios juntos.','Entre 4 y 7 centímetros de largo, con un cuerpo delgado y alargado.','Entre 2 y 5 años, según las condiciones del acuario y los cuidados generales.',array['Problemas relacionados con mala calidad del agua, algo bueno para charlar con el veterinario o especialista en acuarios sobre el mantenimiento adecuado','Infecciones fúngicas o bacterianas en la piel o aletas, que conviene consultar si se notan cambios de color o textura','Estrés por espacio insuficiente o pocos compañeros, ya que es una especie que necesita vivir en grupo','Problemas digestivos asociados a sobrealimentación, algo para conversar sobre la cantidad y frecuencia de comida','Sensibilidad a cambios brumscos de temperatura, un punto para revisar con quien asesore sobre el acuario']::text[],'{"cachorro": "En la etapa joven es importante mantenerlo en grupos de al menos cinco o seis ejemplares, porque es una especie que necesita compañía de su misma especie. El agua debe estar limpia y con temperatura estable, y conviene consultar con un especialista en acuarios sobre los parámetros ideales. La alimentación en esta etapa debe ser variada y en pequeñas cantidades varias veces al día.", "adulto": "Ya adulto sigue necesitando vivir en grupo y un espacio con buena circulación para nadar, ya que es muy activo. La alimentación balanceada y el mantenimiento regular del acuario, con cambios parciales de agua, ayudan a mantenerlo saludable. Si se nota algún cambio en su comportamiento, apetito o aspecto físico, es buen momento para consultar con el veterinario o especialista.", "senior": "En la etapa mayor puede volverse un poco menos activo, y es normal que se mueva con menos energía que antes. Conviene observar de cerca su alimentación y la calidad del agua, ya que en esta etapa puede ser más sensible a los cambios. Cualquier señal de malestar prolongado vale la pena comentarla con un especialista en peces."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','perro-de-montana-de-los-pirineos',true,'Es una raza originaria de la cordillera de los Pirineos, entre Francia y España, donde se la usaba desde hace siglos para guardar y proteger rebaños de ovejas frente a depredadores. Trabajaba de forma independiente, tomando decisiones propias en el monte, lejos del pastor.','Suele ser un perro tranquilo y observador dentro de la casa, pero muy atento a lo que pasa alrededor. Tiende a ser protector con su familia y algo reservado con los desconocidos, aunque no suele ser agresivo si fue bien socializado. Es independiente por naturaleza, así que puede mostrarse algo terco a la hora de obedecer órdenes.','Entre 39 y 54 kg, con una altura aproximada de 65 a 81 cm según el sexo.','Entre 10 y 12 años.',array['Displasia de cadera y de codo, algo para chequear con el veterinario dado su tamaño grande','Torsión gástrica, conviene hablar con el veterinario sobre cómo organizar sus comidas','Problemas oculares como entropión, vale la pena una revisión periódica','Osteosarcoma, un tema a monitorear en razas grandes con el veterinario','Sensibilidad a ciertos anestésicos, bueno mencionarlo antes de cualquier procedimiento']::text[],'{"cachorro": "Necesita socialización temprana y variada, para que su instinto protector no se convierta en desconfianza excesiva. El ejercicio debe ser moderado en esta etapa, evitando saltos o esfuerzos fuertes mientras los huesos se desarrollan. Es buen momento para consultar con el veterinario sobre alimentación y ritmo de crecimiento, dado que es una raza grande.", "adulto": "Requiere paseos diarios pero no es un perro de ejercicio intenso, disfruta más de recorridos tranquilos que de actividad frenética. Su pelaje denso pide cepillado regular, sobre todo en épocas de muda. Convive bien en espacios con lugar para moverse y valora tener una rutina estable.", "senior": "Los paseos pueden acortarse pero conviene mantenerlos, adaptados a su movilidad. Es un buen momento para chequeos veterinarios más frecuentes, prestando atención a articulaciones y peso. El descanso en superficies cómodas ayuda a cuidar sus articulaciones con los años."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('roedor','ardilla-de-tierra',false,null,null,null,null,'{}','{"cachorro": null, "adulto": null, "senior": null}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('cobaya','cobaya-abisinia',true,'La cobaya abisinia es una de las razas más antiguas de cobayas domésticas, originaria de la región de los Andes en Sudamérica, aunque el nombre ''abisinia'' se lo dieron los criadores europeos sin relación real con Etiopía. Se desarrolló y popularizó como mascota y animal de exposición por su pelaje particular en rosetas.','Suele ser una cobaya activa y curiosa, con tendencia a explorar su entorno. Convive bien en pareja o grupo con otras cobayas y suele mostrarse sociable con las personas si se la maneja con calma desde chica. Como todo individuo, puede variar entre más tímida o más despierta.','Entre 700 gramos y 1,2 kilos, con un cuerpo compacto de unos 20 a 25 centímetros de largo.','Entre 5 y 8 años, dependiendo de los cuidados generales y la genética individual.',array['Problemas dentales relacionados con el crecimiento continuo de los dientes, conviene consultarlo con el veterinario','Afecciones de piel o irritaciones en las zonas donde se forman las rosetas del pelaje','Déficit de vitamina C, algo característico de la especie y que vale revisar con el veterinario','Problemas respiratorios, sobre todo si el ambiente tiene mucha humedad o corrientes de aire','Cálculos urinarios, un tema para charlar con el veterinario si se nota algún cambio al orinar']::text[],'{"cachorro": "Necesita una dieta rica en heno y verduras frescas, con suplemento de vitamina C, y un espacio amplio para moverse desde temprano. Es buen momento para acostumbrarla al manejo humano con calma y sin apuros. El pelaje en rosetas requiere cepillado suave para evitar enredos desde chica.", "adulto": "Necesita heno disponible todo el tiempo, verduras frescas a diario y espacio para ejercitarse fuera de la jaula. El cepillado regular ayuda a mantener el pelaje sin nudos y a revisar la piel. Cualquier cambio en el apetito o en el comportamiento conviene consultarlo con el veterinario.", "senior": "Puede necesitar ajustes en la dieta y controles más frecuentes de peso y dentadura. Conviene mantenerle el espacio accesible si se mueve con menos agilidad. El veterinario es quien mejor puede orientar sobre chequeos periódicos en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','airedale-terrier',true,'El Airedale Terrier surgió en el valle del río Aire, en Yorkshire, Inglaterra, durante el siglo XIX. Se lo criaba para cazar nutrias y ratas de agua, y también se usó como perro de caza mayor y perro de trabajo todoterreno. Es el más grande de los terrier británicos.','Suele ser un perro inteligente, seguro de sí mismo y con bastante independencia de criterio. Tiende a ser leal con su familia, aunque puede mostrarse reservado con extraños. Conserva instinto de caza y le gusta tener tareas o estímulos, así que el aburrimiento no le sienta bien.','Entre 23 y 29 kg, con una altura de 56 a 61 cm a la cruz.','Entre 10 y 13 años aproximadamente.',array['Displasia de cadera, algo para conversar con el veterinario en controles de rutina','Problemas de piel o alergias cutáneas, conviene consultarlo si aparecen picazón o irritaciones frecuentes','Hipotiroidismo, un tema para chequear con análisis periódicos según indique el veterinario','Ciertos tumores, por lo que los chequeos regulares ayudan a detectar cualquier cambio a tiempo','Problemas oculares, vale la pena mencionarlo en las visitas veterinarias']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos entornos, ya que esto ayuda a moldear su carácter independiente. El pelaje rizado y duro requiere cepillado regular desde chico para acostumbrarlo. La alimentación y el ritmo de crecimiento conviene charlarlos con el veterinario, dado que es una raza de talla mediana a grande.", "adulto": "Es un perro activo que necesita ejercicio diario, tanto caminatas como momentos de juego o trabajo mental. El pelaje pide cepillado frecuente y un mantenimiento particular, muchas familias optan por el stripping o la tusa periódica. Los controles veterinarios de rutina ayudan a seguir de cerca su salud articular y de piel.", "senior": "Con la edad conviene ajustar la intensidad del ejercicio, sin dejar de lado paseos suaves y regulares. Es buen momento para chequeos veterinarios más frecuentes, prestando atención a articulaciones, vista y peso corporal. El pelaje sigue necesitando cuidado, y cualquier cambio de comportamiento o movilidad vale la pena comentarlo con el veterinario."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('equino','paso-fino-colombiano',true,'El Paso Fino Colombiano se desarrolló en Colombia a partir de caballos traídos por los españoles, cruzando líneas andaluzas, bereberes y jennet. Se lo crió para el trabajo de campo y el transporte en terrenos difíciles, buscando un andar suave y cómodo para el jinete. Hoy se lo valora sobre todo por su paso característico, un andar natural a cuatro tiempos.','Suele ser un caballo dócil, atento y con ganas de agradar, lo que facilita el trabajo diario. Tiene energía y vivacidad, pero generalmente sin caer en el nerviosismo excesivo. Se adapta bien al vínculo cercano con las personas si recibe manejo constante y respetuoso.','Entre 350 y 400 kg de peso, con una alzada aproximada de 1,32 a 1,45 metros al morro.','Entre 25 y 30 años, con buen manejo y cuidados adecuados.',array['Problemas de cascos o herrajes por el tipo de andar particular, para revisar con el veterinario o el herrador','Cólicos digestivos, como ocurre en muchos equinos, conviene conversar sobre manejo de alimentación','Afecciones articulares u óseas en miembros por el trabajo específico del paso','Problemas dentales relacionados con el desgaste irregular, bueno chequearlos periódicamente','Sensibilidad ocular o cutánea en climas muy soleados, para consultar medidas de protección']::text[],'{"cachorro": "En el potrillo es clave la socialización temprana con personas y otros caballos, además de un manejo suave que no lo estrese. La alimentación tiene que acompañar el crecimiento óseo y muscular, así que conviene planificarla con el veterinario. El desarrollo del andar característico empieza a notarse de a poco y no hay que forzarlo.", "adulto": "Necesita ejercicio regular acorde a su uso, ya sea de trabajo, paseo o exhibición. El cuidado de cascos y el control dental periódico ayudan a mantenerlo cómodo y sano. La alimentación debe ajustarse a su actividad física para evitar tanto el sobrepeso como la falta de energía.", "senior": "Con la edad puede necesitar ajustes en la dieta y controles más frecuentes de dientes y articulaciones. Sigue disfrutando del movimiento, pero en intensidad más moderada según lo que indique el veterinario. La observación diaria ayuda a notar a tiempo cualquier cambio en su movilidad o apetito."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','golden-doodle',true,'Es un cruce entre Golden Retriever y Poodle (Caniche), desarrollado originalmente en Estados Unidos y Australia buscando combinar el temperamento del Golden con un pelaje que desprenda menos pelo. No es una raza reconocida formalmente por las asociaciones caninas más tradicionales, sino un híbrido cada vez más popular como mascota familiar.','Suele ser un perro sociable, cariñoso y con ganas de agradar, buen candidato para la vida en familia. Muchos ejemplares muestran inteligencia y facilidad para el aprendizaje, herencia de sus dos razas de origen. Como es un cruce, el carácter puede variar bastante de un individuo a otro.','Entre 9 y 36 kg y 35 a 60 cm de altura a la cruz, según el tamaño del Poodle usado en el cruce (miniatura, mediano o estándar).','Entre 10 y 15 años aproximadamente.',array['Displasia de cadera, algo para charlar con el veterinario sobre todo en ejemplares de mayor tamaño','Problemas oculares hereditarios, vale la pena consultarlo en los controles regulares','Alergias o sensibilidades en la piel, un tema para conversar si aparecen molestias frecuentes','Torsión gástrica en ejemplares grandes, bueno mencionarlo al veterinario para saber qué señales vigilar','Enfermedades hereditarias del Poodle, como ciertas condiciones tiroideas, que conviene preguntar en los chequeos']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes para desarrollar un carácter equilibrado. El pelaje empieza a definirse en esta etapa y conviene ir acostumbrándolo al cepillado desde chico. Es un buen momento para charlar con el veterinario sobre el plan de controles y cuidados generales.", "adulto": "Requiere ejercicio diario y estímulo mental, ya que suele ser un perro activo y curioso. El pelaje, sea más rizado o más liso según el individuo, necesita cepillado frecuente para evitar nudos. Los controles veterinarios periódicos ayudan a mantener un seguimiento de su salud general.", "senior": "Puede necesitar rutinas de ejercicio más suaves y adaptadas a su energía y movilidad. Es buen momento para prestar atención a cambios en el peso, la vista o el comportamiento, y comentarlos con el veterinario. Los chequeos regulares ganan importancia para detectar a tiempo cualquier tema de salud propio de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('huron','huron',true,'El hurón doméstico desciende del turón europeo y se lo domesticó hace siglos, primero para cazar conejos y controlar roedores, y hoy principalmente como animal de compañía. Existen distintas variedades de color y patrón, pero no razas formalmente diferenciadas como en perros o gatos.','Suele ser curioso, juguetón y muy activo, con largos períodos de sueño entre medio. Le gusta explorar y esconder objetos, así que convive bien con familias dispuestas a hurón-proofear la casa. Puede convivir con otras mascotas si la presentación es gradual, aunque cada individuo tiene su propio carácter.','Entre 0,7 y 2 kg, con 20 a 25 cm de largo de cuerpo sin contar la cola.','Entre 6 y 10 años aproximadamente.',array['Tumores adrenales, un tema para conversar con el veterinario sobre chequeos periódicos','Insulinoma, conviene charlarlo con el veterinario si aparecen cambios de energía o apetito','Enfermedades dentales, vale revisarlo en los controles veterinarios de rutina','Linfoma, algo para tener presente en los chequeos generales con el veterinario','Problemas cardíacos, un punto a conversar con el veterinario a partir de la edad adulta']::text[],'{"cachorro": "Necesita mucho estímulo y juego para canalizar su energía, además de un espacio seguro y a prueba de escapes. Es buen momento para socializarlo con manipulación suave y distintas personas. La alimentación debe ser específica para hurones, algo para definir con el veterinario desde el inicio.", "adulto": "Requiere tiempo diario fuera de la jaula para explorar y jugar bajo supervisión. El pelaje pasa por mudas estacionales que conviene acompañar con cepillado. Los controles veterinarios anuales ayudan a seguir de cerca su salud general.", "senior": "Suele bajar su nivel de actividad y puede necesitar ajustes en la dieta, algo para conversar con el veterinario. Conviene estar atento a cambios de peso, apetito o comportamiento. Los chequeos veterinarios más frecuentes son recomendables en esta etapa."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','terranova',true,'El Terranova viene de la isla de Terranova, en Canadá, donde se lo usaba como perro de pescadores. Ayudaba a arrastrar redes, transportar cargas y rescatar personas en el agua fría. Su pelaje y sus patas semipalmeadas lo hicen un excelente nadador.','Suele ser tranquilo, paciente y muy apegado a su familia, incluyendo a los niños. Tiene fama de gentil y protector sin ser agresivo. Como cualquier perro grande, necesita socialización temprana y espacio para sentirse cómodo.','Entre 45 y 70 kilos, con una altura de 66 a 74 centímetros aproximadamente.','Entre 9 y 10 años en promedio.',array['Displasia de cadera y de codo, algo para chequear con el veterinario en controles periódicos','Problemas cardíacos, como la estenosis subaórtica, que conviene monitorear','Torsión gástrica, tema para conversar sobre hábitos de alimentación','Afecciones oculares, como entropión o ectropión','Sensibilidad al calor por su pelaje denso, para tener en cuenta en días de temperaturas altas']::text[],'{"cachorro": "Necesita un crecimiento controlado, sin ejercicio excesivo ni saltos fuertes, para proteger sus articulaciones en desarrollo. La socialización temprana con personas y otros animales es clave dado su tamaño futuro. El veterinario puede guiar sobre alimentación adecuada para razas grandes.", "adulto": "Agradece paseos moderados y, si es posible, acceso a nadar, ya que es una actividad que disfruta y le hace bien físicamente. El cepillado frecuente ayuda a mantener su pelaje denso libre de nudos. Los controles veterinarios de rutina son importantes para monitorear articulaciones y corazón.", "senior": "Puede necesitar superficies antideslizantes y camas ortopédicas para aliviar las articulaciones. El ejercicio se ajusta a su ritmo, con paseos más cortos y tranquilos. Es buen momento para chequeos veterinarios más frecuentes y atención a cambios en su movilidad o apetito."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','bull-terrier-miniatura',true,'El Bull Terrier Miniatura se desarrolló en Inglaterra en el siglo XIX como una versión más pequeña del Bull Terrier, buscando el mismo temperamento en un tamaño más manejable. Se usó como perro de compañía y también para el control de alimañas.','Suele ser un perro enérgico, curioso y muy apegado a su familia. Puede mostrarse terco y necesita límites claros desde cachorro, además de estímulo mental porque se aburre con facilidad. Con buena socialización convive bien en el hogar, aunque no siempre es el mejor compañero para otros perros pequeños o gatos.','Entre 10 y 15 kg, con una altura aproximada de 25 a 35 cm a la cruz.','Entre 11 y 14 años.',array['Problemas de piel y alergias, algo para charlar con el veterinario si aparecen picazón o irritaciones frecuentes','Afecciones renales, conviene conversarlo con el veterinario para saber si conviene algún control periódico','Problemas cardíacos congénitos, vale la pena mencionarlo en los chequeos de rutina','Sordera congénita, especialmente en ejemplares de pelaje blanco, algo para evaluar con el veterinario desde cachorro','Luxación de rótula, un tema para preguntar si se nota alguna cojera o cambio en la forma de caminar']::text[],'{"cachorro": "Es clave socializarlo temprano con personas, otros animales y distintos ambientes, dado su carácter fuerte. Necesita rutinas de obediencia consistentes y pautas claras de convivencia. La alimentación y el calendario de vacunación conviene definirlos con el veterinario.", "adulto": "Requiere ejercicio diario, tanto físico como mental, porque es un perro activo que se aburre rápido. El pelaje es corto y de mantenimiento simple, con cepillados ocasionales. Es buen momento para chequeos veterinarios regulares que sigan de cerca su salud general.", "senior": "Puede necesitar rutinas de ejercicio más suaves y adaptadas a su movilidad. Es importante prestar atención a cambios en el apetito, el peso o la energía, y comentarlos con el veterinario. Los controles periódicos ayudan a detectar a tiempo cualquier tema relacionado con la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','mastin-tibetano',true,'Es una raza originaria de las zonas montañosas de Tíbet, Nepal y regiones vecinas del Himalaya, donde se la usaba para guardar rebaños y proteger campamentos de depredadores. Durante siglos vivió aislada en esas alturas, lo que moldeó un perro robusto y muy independiente.','Suele ser un perro protector y territorial, muy apegado a su familia pero reservado con extraños. Es independiente y puede mostrarse testarudo, por lo que necesita una crianza con límites claros desde cachorro. Con su núcleo familiar suele ser tranquilo y afectuoso.','Entre 45 y 75 kg, con una altura de 61 a 77 cm aproximadamente.','Entre 10 y 14 años aproximadamente.',array['Displasia de cadera y de codo, algo para conversar con el veterinario en controles periódicos','Torsión gástrica, por su tamaño grande y pecho profundo','Problemas de tiroides','Entropión u otras alteraciones oculares','Hipertensión pulmonar, descripta en algunos ejemplares de la raza']::text[],'{"cachorro": "Necesita socialización temprana y constante, ya que su tendencia natural a proteger territorio puede acentuarse si no se trabaja desde chico. El crecimiento debe ser gradual, evitando ejercicio excesivo mientras se forman sus huesos y articulaciones, algo para charlar con el veterinario según su desarrollo. Su pelaje denso empieza a necesitar cepillado regular desde esta etapa.", "adulto": "Requiere paseos diarios pero no ejercicio intenso, ya que es más un perro de resistencia y guardia que de alta energía. El cepillado frecuente es importante para mantener su doble capa de pelo, especialmente en épocas de muda. Al ser una raza territorial, conviene mantener rutinas de socialización y límites claros a lo largo de su vida.", "senior": "Puede volverse más sedentario, por lo que hay que ajustar la alimentación para evitar sobrepeso, algo para revisar con el veterinario. Las articulaciones merecen atención especial dado su tamaño, con superficies cómodas para descansar. Los controles veterinarios periódicos ayudan a detectar a tiempo cambios propios de la edad."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('gato','bombay',true,'El Bombay se desarrolló en Estados Unidos en la década de 1950, cruzando gatos Burmese con gatos negros de pelo corto, buscando un aspecto similar a una pequeña pantera. Nunca fue criado para un trabajo específico, sino como gato de compañía y exhibición.','Suele ser un gato sociable y apegado a su familia, que busca estar cerca de las personas y participar de lo que pasa en la casa. Muchos son juguetones hasta adultos y se adaptan bien a la vida en interior. Puede vocalizar bastante para pedir atención.','Entre 3 y 5 kilos de peso, con cuerpo compacto y musculoso.','Entre 12 y 16 años aproximadamente.',array['Problemas respiratorios relacionados con la estructura corta del hocico, algo para revisar con el veterinario','Enfermedades cardíacas como la cardiomiopatía hipertrófica, conviene conversarlo en los controles','Tendencia al exceso de peso si no se controla la alimentación y el ejercicio','Sensibilidad ocular o lagrimeo por la conformación facial, vale la pena mencionarlo en la consulta']::text[],'{"cachorro": "Necesita socialización temprana con personas y otros animales, y juego frecuente para gastar energía. La alimentación debe ser acorde a su edad y tamaño, y conviene consultar al veterinario sobre las vacunas y controles de rutina.", "adulto": "Requiere estimulación diaria con juegos, ya que es un gato activo y curioso. El pelaje corto necesita poco cepillado, pero conviene vigilar el peso y mantener chequeos veterinarios regulares.", "senior": "Puede reducir su nivel de actividad y necesitar ajustes en la dieta. Es buen momento para consultar con el veterinario sobre controles cardíacos y respiratorios más frecuentes, dado su historial como raza."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('pez','pleco-limpiavidrios',true,'El pleco o limpiavidrios es un pez originario de las cuencas de ríos de América del Sur, especialmente de la Amazonía. Se lo incorporó a los acuarios domésticos por su hábito de comer algas de las paredes del tanque, más que por criarse con un propósito ornamental específico. Agrupa en realidad a varias especies de la familia Loricariidae, siendo el más común en acuarismo el conocido como pleco común.','Es un pez tranquilo y de hábitos nocturnos, que suele pasar el día escondido entre rocas o troncos. Convive bien con otras especies pacíficas, aunque puede mostrarse territorial con otros plecos si el espacio es chico. No es un pez sociable en el sentido de buscar interacción, pero su presencia suele ser discreta y de bajo conflicto.','Puede alcanzar entre 30 y 60 centímetros de largo según la especie, con un cuerpo robusto y aplanado.','Entre 10 y 15 años en buenas condiciones de cuidado.',array['Problemas relacionados con la calidad del agua, algo para revisar y conversar con el veterinario o especialista en peces','Dificultades digestivas si la dieta no incluye suficiente fibra vegetal, tema para consultar','Infecciones fúngicas o bacterianas en la piel ante estrés o agua inadecuada, para evaluar con un profesional','Problemas de crecimiento en acuarios demasiado niños para su talla adulta, algo a monitorear con asesoramiento especializado']::text[],'{"cachorro": "De joven necesita un acuario con buena filtración y escondites, ya que es una etapa donde crece rápido. La alimentación debe incluir vegetales y elementos de fibra, además de restos orgánicos. Conviene consultar con un especialista en peces sobre el tamaño mínimo de tanque necesario a futuro.", "adulto": "Requiere un espacio amplio acorde a su tamaño final, con buena oxigenación y superficies para raspar. La dieta se mantiene variada, con base vegetal y algún aporte proteico ocasional. Es buen momento para chequear periódicamente la calidad del agua y el estado general con quien maneje el acuario.", "senior": "En esta etapa puede reducir su actividad y pasar más tiempo quieto. Conviene observar cambios en el apetito o en la piel y consultar con un veterinario o especialista si aparece algo fuera de lo habitual. Mantener estable la calidad del agua sigue siendo central para su bienestar."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','west-highland-white-terrier',true,'El West Highland White Terrier, conocido como Westie, es originario de Escocia, donde se lo criaba para cazar alimañas y roedores en granjas y madrigueras. Su pelaje blanco se seleccionó para distinguirlo fácilmente de las presas durante la caza. Es un terrier con mucha historia como perro de trabajo rural.','Es un perro alerta, curioso y con mucha personalidad, típico de los terriers. Suele ser cariñoso con su familia pero puede mostrarse testarudo o vocal si algo le llama la atención. Le gusta la actividad y explorar, y conserva instinto de cazador con animales pequeños.','Entre 6 y 10 kg, con una altura aproximada de 25 a 30 cm a la cruz.','Entre 12 y 16 años.',array['Problemas de piel y alergias, algo para consultar con el veterinario si aparecen picazón o irritaciones frecuentes','Displasia de cadera, conviene charlarlo con el veterinario especialmente si se nota cojera o dificultad para moverse','Luxación de rótula, tema para conversar si se observan saltos o cambios en la forma de caminar','Ciertas afecciones respiratorias o de vías aéreas, bueno mencionarlo si hay tos o dificultad para respirar','Predisposición a algunos tipos de cáncer de piel, algo para tener en cuenta en los controles veterinarios regulares']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros perros y distintos ambientes, ya que su naturaleza curiosa se beneficia de una buena exposición controlada. El pelaje empieza a formarse y conviene ir acostumbrándolo al cepillado desde chico. Es un buen momento para consultar con el veterinario sobre alimentación y el calendario de cuidados preventivos.", "adulto": "Requiere paseos diarios y estímulo mental, ya que es un perro activo que disfruta explorar y tener tareas. Su pelaje duro necesita cepillado regular y visitas periódicas a peluquería canina para mantenerlo prolijo. Es buen momento para chequeos veterinarios de rutina que ayuden a detectar cualquier tema a tiempo.", "senior": "Puede mantenerse activo pero conviene ajustar la intensidad del ejercicio a su ritmo. La piel y las articulaciones merecen atención especial en esta etapa, así que los controles veterinarios más frecuentes son recomendables. La alimentación también puede necesitar ajustes, algo que conviene charlar con el veterinario."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('cobaya','cobaya-teddy',true,'La cobaya Teddy es una variedad desarrollada a partir de cruces selectivos en criaderos, buscando un pelaje corto, denso y con textura rizada o áspera, similar al de un peluche. No se la criaba para trabajo ni producción, sino como mascota de compañía.','Suele ser una cobaya activa y curiosa, que se acostumbra bien a la manipulación si se la socializa desde chica. Como toda cobaya, es de naturaleza social y le hace bien la compañía de otra de su especie. El carácter varía bastante de un individuo a otro, así que conviene conocerla en persona antes de sacar conclusiones.','Entre 700 gramos y 1,2 kilos, con una longitud de cuerpo de unos 20 a 25 centímetros.','Entre 5 y 8 años, según cuidados y genética.',array['Problemas dentales relacionados con el crecimiento continuo de los dientes, algo para revisar con el veterinario de forma periódica','Afecciones de piel vinculadas a la textura particular de su pelaje, que conviene consultar si aparecen zonas irritadas o descamación','Sensibilidad respiratoria ante cambios de temperatura o corrientes de aire, un tema para charlar con el veterinario sobre el ambiente ideal','Necesidad de vitamina C en la dieta, algo que el veterinario puede ayudar a planificar correctamente','Predisposición a la obesidad si la alimentación no está bien balanceada, otro punto para conversar en los controles']::text[],'{"cachorro": "En esta etapa necesita una dieta rica en heno de buena calidad y verduras frescas, además de contacto frecuente para que se acostumbre a las manos de la familia. Es buen momento para que el veterinario haga un primer chequeo general y oriente sobre la alimentación.", "adulto": "Necesita espacio suficiente para moverse, heno disponible todo el tiempo y una rutina de limpieza del pelaje, ya que su textura particular puede acumular más suciedad. Los controles veterinarios periódicos ayudan a detectar a tiempo cualquier tema dental o de piel.", "senior": "Puede volverse más sedentaria y conviene observar si mastica con la misma facilidad de antes. Los chequeos veterinarios más frecuentes son útiles para acompañar los cambios propios de la edad y ajustar la dieta si hace falta."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','gran-pirineo',true,'Es una raza originaria de las montañas de los Pirineos, entre Francia y España, donde se la criaba para proteger rebaños de ovejas de lobos y osos. Trabajaba de noche, vigilando el ganado prácticamente sola, sin necesidad de que un pastor le diera órdenes constantes.','Suele ser tranquilo dentro de casa y muy protector con su familia, incluso con niños pequeños. Tiende a ser independiente y a tomar decisiones propias, lo cual puede hacer que la obediencia estricta no sea su fuerte. Con extraños puede mostrarse reservado al principio, y suele ladrar bastante, sobre todo de noche, como parte de su instinto guardián.','Entre 39 y 54 kg, con una altura de 65 a 81 cm según sea macho o hembra.','Entre 10 y 12 años aproximadamente.',array['Displasia de cadera y de codo, algo para chequear con el veterinario a medida que crece','Torsión gástrica, por su tamaño grande y pecho profundo','Problemas oculares como entropión, conviene una revisión periódica','Enfermedades cardíacas congénitas en algunos ejemplares','Osteosarcoma, un tema para hablar con el veterinario especialmente en la etapa senior']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes, ya que su instinto protector puede acentuarse si no se trabaja desde chico. El ejercicio debe ser moderado en esta etapa, evitando saltos o esfuerzos fuertes mientras los huesos todavía se están formando. Conviene consultar con el veterinario sobre el plan de alimentación, porque el crecimiento acelerado de las razas grandes requiere cuidados particulares.", "adulto": "Requiere caminatas diarias, aunque no es una raza que necesite ejercicio intenso constante, más bien actividad regular y espacio para moverse. Su pelaje denso necesita cepillado frecuente, especialmente en épocas de muda, para evitar nudos. Es un buen momento para mantener controles veterinarios regulares dado su tamaño y las predisposiciones asociadas a la raza.", "senior": "Los paseos pueden espaciarse o acortarse, priorizando la comodidad de sus articulaciones, que con los años pueden resentirse. Una cama ortopédica o superficies blandas ayudan a aliviar el descanso. Es importante mantener visitas veterinarias más frecuentes para monitorear su salud general y detectar cambios a tiempo."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('reptil','iguana-verde',true,'La iguana verde es originaria de América Central y del Sur, desde México hasta Brasil y Paraguay. En estado silvestre vive en zonas tropicales cercanas a ríos y se ha popularizado como mascota exótica desde hace varias décadas, aunque no es una raza en sentido estricto sino una especie con distintas variantes regionales y de color.','De joven suele ser nerviosa y puede reaccionar con mordidas o coletazos si se siente amenazada. Con manejo constante y paciencia muchas se vuelven más tolerantes al contacto humano, aunque conservan cierto carácter territorial, especialmente los machos adultos. No es un animal que busque afecto como un perro o gato, su vínculo con la familia se construye distinto y requiere respetar sus tiempos.','Puede alcanzar entre 1,2 y 1,8 metros de largo total (incluyendo la cola) y pesar entre 3 y 6 kilos, según sexo y alimentación.','Entre 10 y 20 años en cautiverio con cuidados adecuados.',array['Trastornos metabólicos óseos vinculados a la dieta y exposición a luz ultravioleta, para conversar con el veterinario sobre el manejo adecuado','Problemas renales asociados a dietas con exceso de proteína animal','Parásitos internos y externos, algo a controlar con revisiones periódicas','Infecciones respiratorias relacionadas con temperatura o humedad inadecuada del terrario','Prolapso o retención de huevos en hembras, un tema para consultar si hay señales de alarma']::text[],'{"cachorro": "Las iguanas jóvenes necesitan un terrario con temperatura y humedad bien reguladas, y exposición a luz ultravioleta tipo B para procesar el calcio correctamente. La alimentación en esta etapa es principalmente vegetal, con variedad de hojas verdes y vegetales, y conviene consultar al veterinario especializado en reptiles sobre suplementación. El manejo frecuente y calmo desde chicas ayuda a que tolere mejor el contacto en el futuro.", "adulto": "En la adultez necesita un espacio amplio para moverse y trepar, además de mantener la temperatura y la luz UVB estables todo el año. La dieta sigue siendo mayormente vegetal, evitando el exceso de proteína animal, y las revisiones veterinarias periódicas ayudan a detectar a tiempo cualquier desequilibrio. Es un buen momento para mantener rutinas de manejo que la mantengan habituada a la presencia humana.", "senior": "Las iguanas mayores pueden mostrar menor apetito o movilidad reducida, por lo que conviene facilitar el acceso a los distintos sectores del terrario. Los controles veterinarios más frecuentes ayudan a monitorear la función renal y ósea, algo relevante en esta etapa de la vida. Mantener condiciones ambientales estables sigue siendo tan importante como en etapas anteriores."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','mastin-espanol',true,'El Mastín Español es originario de España, donde se lo criaba desde hace siglos para proteger rebaños de ovejas de lobos y otros depredadores. Es una de las razas de perro de montaña y guarda de ganado más antiguas de la península ibérica.','Suele ser tranquilo, territorial y muy protector con su familia y su espacio. Es un perro independiente, que piensa por sí mismo, y no siempre busca agradar como otras razas. Con extraños tiende a ser reservado, y necesita socialización temprana para manejar bien esas situaciones.','Entre 50 y 90 kg, con una altura de 70 a 90 cm aproximadamente, según el sexo.','Entre 10 y 12 años aproximadamente.',array['Displasia de cadera y codo, algo para hablar con el veterinario sobre todo por su tamaño y crecimiento rápido','Torsión gástrica, tema para conversar en cuanto a manejo de comidas y ejercicio','Problemas oculares como entropión, conviene que el veterinario los revise periódicamente','Afecciones cardíacas, vale la pena mencionarlo en los controles de rutina','Sensibilidad articular en general debido a su gran tamaño']::text[],'{"cachorro": "El crecimiento es rápido y el peso final es muy alto, así que conviene hablar con el veterinario sobre el ritmo de ejercicio para cuidar las articulaciones en desarrollo. La socialización temprana con personas y otros animales es clave dado su carácter protector natural. El pelaje necesita cepillado regular desde chico para que se acostumbre a la rutina.", "adulto": "Necesita ejercicio moderado, no es un perro de alta energía pero sí requiere espacio, idealmente con un jardín o patio amplio. El pelaje pide cepillado semanal, más frecuente en época de muda. Es importante mantener los controles veterinarios regulares dado su tamaño y las tendencias asociadas a la raza.", "senior": "El peso corporal hay que vigilarlo de cerca porque el sobrepeso complica aún más las articulaciones en esta etapa. Los paseos pueden acortarse pero conviene mantenerlos, siempre adaptados a su movilidad. Las visitas al veterinario suelen ser más frecuentes para monitorear el estado general y detectar a tiempo cualquier cambio."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','pastor-australiano',true,'El Pastor Australiano se desarrolló en el oeste de Estados Unidos en el siglo XIX, a pesar del nombre, para trabajar el ganado ovino junto a pastores vascos que habían pasado antes por Australia. Se lo crió como perro de trabajo, ágil y resistente, capaz de pasar largas jornadas arreando y cuidando rebaños.','Es un perro activo, atento y muy apegado a su familia, que suele necesitar sentirse parte de las tareas y rutinas del hogar. Tiende a ser inteligente y receptivo al entrenamiento, aunque puede mostrarse reservado con desconocidos si no se lo socializa desde cachorro. Con espacio y estímulo suele convivir bien con niños y otros animales, aunque su instinto de pastoreo puede llevarlo a intentar arrear a las personas o mascotas de la casa.','Entre 18 y 32 kilos, con una altura de 46 a 58 centímetros según sea macho o hembra.','Entre 12 y 15 años.',array['Displasia de cadera, algo para chequear con el veterinario en controles periódicos','Problemas oculares hereditarios, conviene consultar sobre exámenes específicos','Sordera congénita, en especial en ejemplares con mucho blanco en el pelaje','Epilepsia, un tema para conversar si aparecen episodios extraños','Sensibilidad a ciertos medicamentos, vale mencionarlo siempre antes de cualquier tratamiento']::text[],'{"cachorro": "Necesita socialización temprana con personas, otros animales y distintos ambientes para no volverse desconfiado de adulto. El ejercicio debe ser moderado y acorde a su crecimiento, evitando saltos o esfuerzos fuertes mientras se desarrollan sus huesos y articulaciones. Es buen momento para empezar rutinas de obediencia básica, ya que aprende rápido y necesita canalizar su energía.", "adulto": "Requiere bastante ejercicio diario, tanto físico como mental, porque es un perro que se aburre fácil si no tiene tareas o estímulos. El cepillado regular ayuda a mantener su pelaje semilargo en buen estado, sobre todo en épocas de muda. Los controles veterinarios de rutina son importantes para monitorear las articulaciones y la vista a lo largo de los años.", "senior": "Con la edad conviene ajustar la intensidad del ejercicio, manteniendo caminatas y actividad suave que respete sus tiempos. La alimentación puede necesitar ajustes para acompañar cambios en el metabolismo, algo que el veterinario puede orientar según cada caso. Vale la pena prestar atención a signos de dolor articular o cambios de comportamiento y consultarlos a tiempo."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('roedor','hamster-enano-de-campbell',true,'El hámster de Campbell viene de las estepas y zonas áridas de Mongolia, norte de China y Siberia, donde vivía en madrigueras. Se popularizó como mascota a partir del siglo XX por su tamaño pequeño y su carácter activo. Muchas veces se confunde o cruza con el hámster ruso enano, con el que comparte parte del hábitat original.','Es un hámster activo y curioso, que suele moverse mucho durante la noche. Puede ser algo más nervioso o rápido que otras razas de hámster, por lo que necesita un manejo tranquilo y progresivo para acostumbrarse a las manos. No siempre tolera bien la convivencia con otros hámsters, incluso de su misma especie.','Entre 8 y 10 centímetros de largo y un peso de 20 a 50 gramos.','Entre 1 y 2 años, con algunos casos que llegan a los 3.',array['Tendencia a desarrollar diabetes, algo para preguntarle al veterinario sobre la alimentación','Problemas dentales por crecimiento continuo de los incisivos','Tumores, sobre todo en hámsters de mayor edad','Sensibilidad de piel y posibles alergias a ciertos sustratos','Predisposición a el estrés por manejo brusco o cambios de ambiente']::text[],'{"cachorro": "En las primeras semanas necesita un espacio tranquilo, con buen sustrato para escarbar y esconderse. Conviene manipularlo poco al principio, dejando que se acostumbre al olor y la voz de la familia. La alimentación debe ser variada y es buen momento para que el veterinario revise su desarrollo general.", "adulto": "Necesita una jaula con suficiente espacio para correr, una rueda adecuada a su tamaño y accesorios para roer. La dieta equilibrada y el ejercicio diario ayudan a mantenerlo activo y con buen peso. Conviene revisar sus dientes y su piel de forma periódica, y consultar al veterinario ante cualquier cambio de comportamiento o apetito.", "senior": "Con la edad puede volverse menos activo y dormir más horas durante el día. Es buen momento para observar bultos, cambios de peso o dificultad para moverse, y comentarlo con el veterinario. El ambiente debe mantenerse tranquilo y accesible, evitando saltos o alturas que antes no le costaban."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz),
  ('perro','mastin-napolitano',true,'El Mastín Napolitano viene de la región de Nápoles, en el sur de Italia, donde se lo usó durante siglos como perro guardián de propiedades y ganado. Desciende de antiguos molosos y su aspecto imponente y su instinto territorial fueron siempre parte de su función.','Es un perro tranquilo dentro de casa, poco activo y muy apegado a su familia. Suele mostrarse desconfiado con extraños, lo que lo hace un buen guardián, aunque necesita socialización temprana para no volverse reactivo. Con los suyos es cariñoso y protector, aunque no busca demasiado juego ni contacto físico exagerado.','Entre 50 y 70 kilos, con una altura de 60 a 75 centímetros a la cruz.','Entre 8 y 10 años.',array['Displasia de cadera y de codo, algo para chequear con el veterinario dado su tamaño y ritmo de crecimiento','Torsión gástrica, conviene hablar con el veterinario sobre pautas de alimentación para reducir el riesgo','Problemas de piel y pliegues cutáneos, que requieren revisión veterinaria periódica','Entropión o ectropión, alteraciones de los párpados que vale controlar con el veterinario','Problemas cardíacos, algo para monitorear en controles veterinarios regulares']::text[],'{"cachorro": "El crecimiento debe ser gradual, evitando ejercicio excesivo o saltos que fuercen articulaciones todavía en desarrollo. La socialización temprana con personas y otros animales es clave para su equilibrio adulto. La alimentación debe ajustarse a razas grandes, siempre bajo indicación del veterinario.", "adulto": "Necesita paseos moderados, sin exigencias de alta actividad física, y espacio suficiente para moverse con comodidad. Los pliegues de piel y las arrugas faciales requieren limpieza regular para evitar irritaciones. Los controles veterinarios periódicos ayudan a detectar a tiempo problemas articulares o cardíacos.", "senior": "El ejercicio debe adaptarse a su movilidad, priorizando caminatas cortas y superficies que no resbalen. La alimentación puede necesitar ajustes para mantener un peso saludable y cuidar las articulaciones, siempre con orientación veterinaria. Las visitas al veterinario deberían ser más frecuentes para monitorear el corazón y las articulaciones."}'::jsonb,'claude-sonnet-5','2026-09-05T23:56:33.833Z'::timestamptz)
on conflict (especie, raza_codigo) do nothing;

-- Las 11 por especie.
-- 🔴 `do update` acotado a `not conocida`: una ficha CON contenido le gana a una
-- vacía —que es justo el caso de `gato-comun` y `criollo`—, y **jamás pisa una
-- que alguien ya leyó y publicó**. El `and not activo` es redundante hoy (las
-- tres publicadas son conocidas) y está puesto igual: *una guarda que depende de
-- que otra cosa siga siendo cierta no es una guarda.*
insert into public.razas_contenido
  (especie, raza_codigo, conocida, origen, temperamento, talla_adulta,
   esperanza_vida, predisposiciones, cuidados_por_etapa, modelo, generado_el)
values
  ('gato','gato-comun',true,null,'El gato es un animal independiente pero también cariñoso a su manera. Cada gato marca su propio ritmo de acercamiento y no conviene forzarlo. Le gusta tener rutinas estables y espacios propios donde sentirse seguro, como alturas para observar o rincones tranquilos para descansar. Es limpio por naturaleza y necesita su bandeja siempre disponible y en buen estado. Puede convivir con niños y otros animales si el encuentro se hace con paciencia, pero necesita siempre la posibilidad de retirarse si algo lo incomoda. No responde bien a los gritos ni al manejo brusco.','El tamaño adulto varía bastante según el tipo de gato, desde ejemplares pequeños y livianos hasta otros notablemente más grandes y robustos. Es un rango amplio y depende mucho de cada gato en particular.','La esperanza de vida también es un rango amplio, que puede ir de unos diez años a bastante más de quince. Depende de la genética individual, del tipo de gato y sobre todo de los cuidados que recibe a lo largo de su vida.','{}','{"cachorro": "En las primeras semanas el gatito necesita calor, calma y muy poca manipulación si todavía está con la madre. Cuando empieza a comer solo, se lo debe alimentar varias veces al día con una comida formulada para esa etapa. Es un momento clave para las primeras experiencias: presentarlo de forma tranquila a sonidos, personas y a la bandeja sanitaria ayuda mucho a que de adulto sea un gato seguro. Conviene empezar pronto la visita al veterinario para seguir su desarrollo y planificar la vacunación.", "adulto": "En esta etapa lo principal es mantener rutinas estables: horarios de comida, acceso constante a agua fresca y una bandeja limpia. El gato adulto necesita estímulo físico y mental, con juegos, rascadores y algo de altura para trepar u observar. La alimentación debe ajustarse a su nivel de actividad para evitar el sobrepeso. Los controles veterinarios periódicos siguen siendo importantes aunque el gato se vea sano, porque suele disimular bien las molestias.", "senior": "El gato mayor puede volverse menos ágil y dormir más horas. Es buen momento para facilitarle el acceso a sus lugares favoritos, con rampas o superficies más bajas si le cuesta saltar. La alimentación y la hidratación merecen atención especial, y cualquier cambio en el apetito, el peso o los hábitos de la bandeja conviene comentarlo con el veterinario sin demora. Los controles regulares ayudan a detectar a tiempo lo que en esta etapa suele aparecer con más frecuencia."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('perro','criollo',true,null,'El perro es un animal social que busca el contacto con su familia y necesita sentirse parte del grupo. Es leal y se apega a sus personas de referencia. Cómo se comporta en el día a día depende mucho de la raza, la genética individual y la crianza, pero en general necesita rutina, ejercicio acorde a su energía y momentos de contacto con las personas. La falta de estímulo o de compañía puede generar ansiedad o conductas destructivas. Antes de tenerlo en casa conviene pensar en el tiempo diario que se le puede dedicar a paseos, juego y atención.','Varía enormemente según la raza o el tipo: desde poco más de un kilo hasta más de setenta. Este dato hay que mirarlo en la ficha de la mascota, no en la de la especie.','El rango es muy amplio y depende del tamaño, la raza y la salud general: suele ir de los ocho a los diecisiete años, con las razas más pequeñas viviendo generalmente más que las grandes.','{}','{"cachorro": "En las primeras semanas de vida el cachorro depende totalmente de la madre o de cuidados intensivos si está solo. Después del destete necesita varias comidas pequeñas al día con un alimento formulado para su etapa. Es el momento clave para la socialización: exponerlo de forma tranquila a personas, otros animales, sonidos y superficies distintas ayuda a que sea un adulto seguro. El plan de vacunación y desparasitación lo define el veterinario, y no conviene saltarlo. También es la etapa de empezar hábitos: dónde duerme, dónde hace sus necesidades, qué se puede morder y qué no. Cualquier decaimiento, falta de apetito o diarrea persistente hay que consultarlo enseguida, porque en esta etapa se descompensan rápido.", "adulto": "El perro adulto necesita una rutina estable de alimentación, ejercicio y descanso. La cantidad de actividad física varía según el tamaño y el tipo, pero todos necesitan salir a moverse y estimularse mentalmente. La alimentación se ajusta a su peso y nivel de actividad, evitando sobrealimentar. Los controles veterinarios anuales, las vacunas de refuerzo y la prevención de parásitos externos e internos son parte de mantenerlo sano. Cambios de conducta como agresividad repentina, decaimiento o pérdida de apetito conviene consultarlos con el veterinario.", "senior": "Con la edad el perro reduce su actividad y puede necesitar un alimento más liviano o adaptado a sus articulaciones y riñones. Conviene facilitarle el acceso a su cama, agua y comida, sobre todo si le cuesta moverse o subir escaleras. Los controles veterinarios se hacen más frecuentes para detectar a tiempo problemas de vista, oído, articulaciones o dientes. Cambios como más sed de lo habitual, desorientación, dificultad para pararse o pérdida de peso son señales para consultar sin demora."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('otro','otro',true,null,'Convivir con una mascota que no es perro ni gato pide informarse puntualmente sobre esa especie, porque las necesidades cambian mucho de un animal a otro. Algunas son sociables y buscan contacto, otras son más independientes o incluso se estresan con el manejo frecuente. Antes de traerla a casa conviene averiguar si es una especie que tolera bien la interacción con niños, cuánto tiempo de atención necesita por día y si puede convivir con otras mascotas de la casa. El veterinario que atienda a este animal en particular es la mejor fuente para entender su comportamiento específico.','Varía enormemente según la especie de que se trate, desde animales muy pequeños hasta ejemplares grandes. No hay un rango que sirva de referencia general: hay que guiarse por la especie y, si corresponde, por la raza o el tipo puntual del animal.','También varía muchísimo: hay especies que viven pocos años y otras que pueden acompañar a la familia por décadas. El rango es demasiado amplio para dar un número general, así que conviene preguntarle al veterinario cuál es la expectativa de vida realista para este animal en particular.','{}','{"cachorro": "En la etapa temprana de vida es cuando más cuidado hay que poner en el alojamiento, la temperatura, la alimentación y el manejo, porque cada especie tiene requerimientos distintos y a veces muy específicos. Es el momento clave para investigar bien qué necesita esta especie en particular antes de establecer una rutina, y para consultar con un veterinario con experiencia en ese tipo de animal. También es la etapa donde conviene ir acostumbrando al animal, con calma, al contacto humano si la especie lo tolera.", "adulto": "Una vez que el animal está establecido, lo más importante es mantener una rutina estable de alimentación, limpieza del espacio donde vive y observación diaria. Cualquier cambio en el comportamiento, el apetito, el aspecto físico o la actividad habitual es una señal para consultar al veterinario, ya que en muchas especies los signos de enfermedad son sutiles y se notan tarde. Mantener el hábitat adecuado a la especie es tan importante como la alimentación misma.", "senior": "En animales mayores conviene prestar más atención a cambios lentos: menos actividad, cambios en el peso, en el pelaje, el plumaje o la piel según corresponda, o en los hábitos de alimentación. Muchas especies no muestran signos evidentes de malestar hasta que el problema ya avanzó, así que los controles periódicos con el veterinario cobran más importancia en esta etapa. Ajustar el espacio donde vive para que le resulte más cómodo también suele ser necesario con el paso de los años."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('equino','criollo',true,null,'El caballo es un animal social que necesita contacto con otros de su especie y con las personas que lo manejan. Es sensible y percibe el estado de ánimo de quien lo maneja, por eso responde mejor a la calma y la constancia que a los gritos o los apurones. Es un animal de huida por naturaleza, así que los ruidos fuertes o los movimientos bruscos lo pueden sobresaltar. Convivir con un caballo requiere tiempo diario, espacio adecuado y respeto por sus tiempos. No es una mascota de interior ni de patio chico: necesita moverse, pastar y estar con otros equinos siempre que sea posible.','La talla adulta varía mucho según el tipo o la raza, desde ponys que rondan el metro de alzada hasta caballos grandes que superan el metro setenta a la cruz. Es un rango amplio y conviene preguntar por el tamaño esperado del ejemplar en particular.','La esperanza de vida también es amplia y depende del tipo, el manejo y la salud general del animal. En general se habla de veinticinco a treinta años, pero hay casos que viven menos y otros que llegan más lejos con buenos cuidados.','{}','{"cachorro": "En la etapa temprana el potrillo necesita estar con la madre y con otros caballos para aprender a comportarse dentro del grupo. El destete y el primer manejo con personas deben ser progresivos y sin apuro, porque lo que aprende en estos meses le queda para toda la vida. Necesita espacio para moverse libremente, no estar encerrado, y una alimentación acorde a su crecimiento que conviene planificar con el veterinario. Los controles sanitarios y las primeras vacunas también se coordinan con él.", "adulto": "El caballo adulto necesita movimiento diario, ya sea con trabajo, suelta a campo o ambas cosas. La alimentación se basa en forraje o pasto de buena calidad, con el agregado de balanceado si el trabajo o la condición del animal lo requieren, siempre evaluado por el veterinario. Los cascos necesitan revisión y mantenimiento periódico, con herraje o recorte según el caso. Las vacunas, la desparasitación y los controles dentales de rutina son parte del cuidado habitual. Cualquier cambio en el apetito, la forma de pararse o de moverse conviene consultarlo pronto, porque en esta especie los problemas pueden agravarse rápido.", "senior": "El caballo mayor puede necesitar ajustes en la alimentación, con forraje más blando o de fácil digestión si empieza a perder piezas dentales. Conviene mantenerle el movimiento pero sin forzarlo, respetando lo que el cuerpo le permite. Los controles veterinarios se vuelven más frecuentes para seguir de cerca el estado de las articulaciones, el peso y la salud general. Hay que estar atento a que no pierda condición física de golpe, y cualquier señal de dolor, rigidez o cambio de comportamiento hay que consultarla con el veterinario."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('huron','huron',true,null,'El hurón es curioso, activo y juguetón, con ratos largos de sueño profundo entre medio. Necesita tiempo fuera de la jaula todos los días para explorar y gastar energía, siempre bajo supervisión porque tiende a meterse en huecos, cajones y agujeros pequeños. Muerde para explorar, sobre todo de joven, y hay que enseñarle límites con paciencia. Convive bien con la familia cuando se lo maneja con calma y constancia, y suele encariñarse mucho con las personas que lo cuidan. Tiene olor corporal natural, más allá de la higiene que se le dé. Es un animal que requiere dedicación diaria, no es de los que se arreglan solos en un rincón de la casa.','El tamaño varía bastante según el ejemplar: en general va de unos 20 a 40 centímetros de cuerpo, sin contar la cola, y entre 0,7 y 2 kilos de peso. Es un rango amplio porque depende del tipo de hurón y de cada individuo.','Suele vivir entre 6 y 10 años, aunque también es un rango amplio que depende mucho del tipo de hurón, de su salud y de los cuidados que reciba a lo largo de la vida.','{}','{"cachorro": "En la etapa temprana el hurón necesita un espacio seguro, con jaula amplia, escondites y una zona de descanso blanda. Es el momento de acostumbrarlo a las manos de la familia con manejo suave y frecuente, para que asocie el contacto humano con algo positivo. Muerde mucho mientras explora el mundo, y ahí es clave enseñarle con constancia que morder fuerte no está bien, sin gritos ni golpes. Conviene empezar pronto con el uso de una bandeja higiénica, porque aprenden rápido si se es constante. La alimentación tiene que ser la adecuada para su etapa de crecimiento, y ante cualquier duda sobre cantidades o tipo de alimento lo mejor es consultar al veterinario. También es el momento de programar la primera visita veterinaria para chequeo general y vacunas.", "adulto": "El hurón adulto necesita salir de la jaula todos los días a explorar y jugar, con supervisión, porque su curiosidad lo lleva a meterse en lugares riesgosos. La casa tiene que estar a prueba de hurones: sin huecos abiertos, sin objetos pequeños que pueda tragar y sin productos de limpieza accesibles. La alimentación debe mantenerse estable y de calidad, y los cambios de dieta conviene hacerlos gradualmente. Hay que limpiar la jaula y la bandeja higiénica con regularidad para evitar olores fuertes. Es un animal sociable que agradece tiempo de juego e interacción diaria. Cualquier cambio en el apetito, el pelo, la energía o las heces conviene comentarlo con el veterinario sin demora.", "senior": "Con la edad el hurón puede volverse menos activo y dormir más horas, aunque sigue disfrutando de ratos de juego suaves. Es buen momento para revisar que la jaula tenga accesos fáciles, sin escalones ni alturas que le compliquen el movimiento. La alimentación puede necesitar ajustes propios de la edad, y eso conviene definirlo con el veterinario. Los controles veterinarios periódicos son importantes en esta etapa, porque los problemas de salud se manejan mejor si se detectan a tiempo. Cualquier cambio notorio en el peso, la movilidad o el comportamiento merece una consulta veterinaria pronta."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('pez','pez',true,null,'Un pez no busca contacto ni compañía como lo hace un perro o un gato. Su bienestar depende casi todo del agua y del acuario, no del vínculo directo con la familia. Aun así cada especie de pez tiene su carácter: algunos son tranquilos y se mueven poco, otros son activos y curiosos, y algunos son territoriales con otros peces. Es una mascota para observar y cuidar con atención constante al ambiente, más que para interactuar físicamente. Los niños pueden participar en la alimentación y en la observación, pero el mantenimiento del acuario es tarea de un adulto.','El rango es enorme, desde pocos centímetros hasta más de treinta, según la especie y el tipo de pez. El tamaño adulto y el volumen de acuario que necesita hay que consultarlo puntualmente para ese pez en particular.','También varía mucho según la especie, de dos o tres años a más de diez en algunos casos. Es un rango amplio y conviene informarse sobre la especie concreta que se tiene en casa.','{}','{"cachorro": "En la etapa temprana lo más importante es la calidad del agua: temperatura estable, buena filtración y niveles controlados de amoníaco y nitritos. Los peces jóvenes son más sensibles a los cambios bruscos. La alimentación debe ser en porciones pequeñas y frecuentes, con alimento adecuado a su tamaño. Conviene evitar la sobrepoblación del acuario y observar si hay peces más grandes que puedan intimidarlos o lastimarlos. Cualquier cambio en el color, la natación o el apetito conviene consultarlo con el veterinario especializado en peces.", "adulto": "En esta etapa se mantiene la rutina de cuidado del agua: cambios parciales periódicos, control de temperatura y filtración en buen estado. La alimentación debe ajustarse a la especie, sin excederse en cantidad, porque el exceso de comida ensucia el agua y afecta la salud del pez. Es importante observar el comportamiento habitual, para detectar cambios que indiquen malestar, como nadar de forma extraña, dejar de comer o quedarse en el fondo. El acuario necesita espacio suficiente para el tamaño y la cantidad de peces que conviven ahí.", "senior": "Los peces mayores pueden volverse más lentos y comer menos que antes. Conviene mantener el agua en condiciones óptimas, porque en esta etapa son más sensibles a cualquier desequilibrio. Es recomendable observarlos con frecuencia para notar cambios en la piel, las aletas o la forma de nadar. Ante cualquier señal de deterioro visible o pérdida de apetito sostenida, lo indicado es consultar al veterinario especializado en peces."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('roedor','roedor',true,null,'Los roedores como mascota suelen ser animales activos, curiosos y con instinto de roer marcado, algo que necesitan hacer todos los días para desgastar los dientes. Muchas especies son sociales y disfrutan la compañía de otros de su misma especie, aunque esto varía mucho según el tipo de roedor. Son animales pequeños y sensibles al manejo brusco, por lo que conviene que el contacto con niños esté siempre supervisado por un adulto. Suelen ser más activos al atardecer y de noche. Con manejo tranquilo y constante, muchos se acostumbran a las manos de la familia y a que los tomen en brazos.','Entre los roedores hay muchísima variación de tamaño según la especie y el tipo: desde animales de pocos centímetros hasta otros considerablemente más grandes. El rango es muy amplio y depende del tipo de roedor que tengas en casa.','También varía mucho según la especie: algunos roedores viven apenas uno o dos años, y otros pueden llegar a vivir varios años más. El rango es amplio y depende del tipo de roedor.','{}','{"cachorro": "En la etapa temprana lo más importante es un espacio seguro, sin corrientes de aire ni cambios brustos de temperatura, y con acceso constante a agua limpia y alimento adecuado a su edad. El manejo tiene que ser suave y progresivo, para que se acostumbre a las manos de la familia sin asustarse. Es un buen momento para observar cómo se relaciona con otros de su especie si conviven varios, y para that toda la familia entienda que son animales delicados que no se deben apretar ni sostener con fuerza. Cualquier cría que se vea débil, que no coma o que esté separada del grupo sin motivo aparente hay que llevarla al veterinario.", "adulto": "En esta etapa la base es un hábitat limpio, con espacio suficiente para moverse, y material adecuado para roer y desgastar los dientes, que en los roedores crecen de forma continua. La alimentación tiene que ser la indicada para la especie, evitando excesos de alimentos ricos en azúcar o grasa. La limpieza frecuente del espacio donde vive es clave para evitar olores y problemas de piel o respiratorios. Conviene ofrecerle estímulos, como elementos para explorar o esconderse, porque el aburrimiento afecta su bienestar. Si notás que dejó de comer, que respira con dificultad, que tiene los dientes muy largos o que el pelo se le cae en zonas raras, es momento de consultar al veterinario.", "senior": "Con la edad muchos roedores empiezan a moverse menos y pueden necesitar que el acceso a la comida y el agua esté más cerca o sea más fácil de alcanzar. La piel, los dientes y las uñas conviene revisarlos con más frecuencia, porque en esta etapa aparecen más problemas de este tipo. Los cambios de peso, ya sea que suba o baje, son una señal para prestar atención. El manejo debe ser todavía más cuidadoso, porque los huesos y el cuerpo en general son más frágiles. Ante cualquier cambio de comportamiento, de apetito o de movilidad, la visita al veterinario no debería demorarse."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('cobaya','cobaya',true,null,'La cobaya es un animal social que necesita compañía de su misma especie, no le alcanza con la atención humana. Es tranquila, se asusta con facilidad y con manejo suave y constante llega a reconocer a su familia y a pedir atención con sonidos. No es un animal para tener solo en una jaula aislada: sufre con la soledad. Con niños convive bien si el trato es calmado y supervisado, porque es frágil y se estresa con movimientos brustos o ruidos fuertes.','El tamaño adulto varía bastante según el tipo, en general entre 20 y 40 centímetros de largo y entre 700 gramos y 1.5 kilos. Conviene mirar el tamaño esperado según el tipo de cobaya en particular.','La esperanza de vida es amplia y depende del tipo y de los cuidados, en general entre 4 y 8 años, pudiendo llegar a más en algunos casos.','{}','{"cachorro": "En las primeras semanas de vida la cobaya ya come sólido y necesita heno disponible todo el tiempo, además de verdura fresca y alimento balanceado específico para la especie. El espacio tiene que ser amplio, con piso firme, y siempre debe vivir con al menos otra cobaya. El manejo tiene que ser suave, sosteniéndola con las dos manos y sin dejarla caer, porque a esta edad es especialmente delicada. Cualquier bajón de peso o falta de apetito hay que consultarlo con el veterinario.", "adulto": "En la etapa adulta la base de la alimentación sigue siendo el heno disponible todo el día, junto con verdura fresca variada y una porción de balanceado. La cobaya necesita vitamina C en la dieta porque no la produce por sí misma, y el veterinario puede orientar sobre la mejor forma de asegurarla. El espacio tiene que permitir moverse y esconderse, con buena limpieza para evitar humedad. Sigue necesitando compañía de su especie y rutina estable, los cambios bruscos de ambiente le generan estrés.", "senior": "En la etapa senior conviene prestar atención a los dientes, las uñas y el peso, porque los problemas se hacen más frecuentes con la edad. Puede necesitar que la comida esté más accesible si se mueve con menos soltura. Los controles veterinarios periódicos ayudan a detectar cambios a tiempo. El ambiente tranquilo y la compañía siguen siendo importantes, y cualquier cambio en el apetito, el pelo o la forma de moverse conviene consultarlo con el veterinario sin demorar."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('conejo','conejo',true,null,'El conejo es un animal social y sensible, que necesita compañía y rutinas estables. Se apega a su familia pero no siempre disfruta que lo alcen: por instinto de presa, sentir el cuerpo en el aire le genera miedo, y muchos prefieren el contacto a nivel del suelo. Es un animal de horarios, más activo al amanecer y al atardecer. Es curioso y necesita explorar y masticar, así que hay que preparar la casa para eso. Con paciencia y manejo suave se puede volver muy confiado, pero los movimientos bruscos o los gritos lo estresan de verdad, y el estrés en esta especie afecta directamente su salud física.','Varía mucho según la raza o el tipo: hay conejos de poco más de un kilo y otros que superan los seis kilos. No hay un tamaño único para la especie, y conviene no guiarse por el tamaño de cachorro para imaginar el tamaño adulto.','También es un rango amplio, que depende bastante de la raza, la alimentación y los cuidados: en general se habla de entre 6 y 12 años, aunque hay ejemplares que viven más.','{}','{"cachorro": "En las primeras semanas el conejo depende totalmente de la madre y no debe separarse de ella antes de tiempo. Una vez en casa, la etapa temprana es clave para la socialización: hay que acostumbrarlo a que lo toquen las manos, a los sonidos de la casa, y a un manejo tranquilo desde chico para que no le tenga miedo a la gente. La alimentación en esta etapa necesita heno de buena calidad de forma constante y una introducción gradual de otros alimentos, siempre con la guía del veterinario. El espacio debe estar libre de cables y de plantas al alcance, porque el instinto de morder aparece temprano y con fuerza.", "adulto": "El conejo adulto necesita un espacio amplio para moverse, no solo una jaula para dormir: correr, saltar y estirarse todos los días es parte de su bienestar. La dieta se basa en heno disponible todo el tiempo, verduras frescas variadas y una cantidad moderada de pellets, evitando el exceso de azúcares. Los dientes le crecen toda la vida, así que necesita masticar heno y materiales adecuados para desgastarlos. Conviene revisar el pelaje y las uñas con regularidad, y estar atento a la cantidad y forma de las heces, porque un conejo que deja de comer o no defeca es una urgencia que hay que llevar al veterinario sin demora.", "senior": "Con la edad, el conejo puede volverse menos activo y hay que vigilar que no suba de peso, porque eso le complica la higiene y la movilidad. La artrosis es algo a tener en cuenta, así que conviene facilitarle el acceso a la comida y al lugar de descanso sin que tenga que saltar demasiado. Los dientes y las uñas necesitan revisiones más seguidas. Cualquier cambio en el apetito, en la forma de moverse o en las heces merece una consulta veterinaria pronta, porque en esta especie los problemas de salud pueden agravarse muy rápido si no se atienden a tiempo."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('ave','ave',true,null,'Convivir con un ave pide entender que es una especie de prey animal, alerta y sensible a los cambios. Muchas son sociables y forman vínculo fuerte con la familia, buscan atención y se aburren si están mucho tiempo solas. Otras son más independientes y toleran menos el manejo directo. El ruido, la rutina y el contacto diario influyen mucho en cómo se comporta. Necesita estímulo mental, de lo contrario puede desarrollar conductas como gritar, arrancarse plumas o morder. No es una mascota de bajo mantenimiento solo porque sea pequeña.','Va de unos pocos centímetros hasta más de un metro contando la cola, según el tipo de ave. El rango es enorme y depende totalmente de la raza o especie puntual, así que conviene guiarse por el ejemplar real y no por esta cifra general.','Puede ir de unos 5 años hasta más de 50, con casos de aves grandes que superan esa edad. Es un rango muy amplio que depende del tipo de ave, así que hay que tomarlo como orientación y no como dato fijo.','{}','{"cachorro": "En la etapa temprana el ave necesita calor constante, calma y muy poco manejo brusco. Si llega joven a la casa, el proceso de adaptación es lento: conviene dejar que se acostumbre al entorno antes de buscar contacto físico. La alimentación en esta fase suele requerir una dieta específica y a veces alguien con experiencia que asista, así que es mejor consultarlo con el veterinario antes de improvisar. La jaula o el espacio deben estar lejos de corrientes de aire y de ruidos fuertes repentinos.", "adulto": "En la etapa adulta lo central es la rutina: horarios de luz, alimentación variada y tiempo fuera de la jaula si la especie lo permite. Necesita estímulo mental, juguetes que pueda destruir o manipular, y contacto social si es una especie que lo busca. La dieta cambia según el tipo de ave y conviene revisarla con el veterinario, evitando dar por sentado que las semillas solas alcanzan. Cualquier cambio en el canto, la postura, las plumas o el apetito es señal de alarma y hay que consultarlo pronto, porque las aves suelen esconder los signos de enfermedad hasta que están muy avanzados.", "senior": "Un ave mayor puede volverse más quieta, dormir más y necesitar menos manipulación directa. Conviene facilitarle el acceso a la comida y al agua si baja su movilidad, y revisar con más frecuencia las patas, el pico y las plumas. Los cambios de temperatura le cuestan más, así que hay que cuidar el ambiente. Ante cualquier señal de dolor, dificultad para pararse en la percha o cambios de comportamiento, lo indicado es que lo evalúe el veterinario sin demora."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz),
  ('reptil','reptil',true,null,'Convivir con un reptil es distinto a convivir con un perro o un gato. No busca cariño ni compañía como esos animales, y no hay que esperar que lo haga. Es un animal de manejo tranquilo y observación más que de interacción constante. Muchas especies toleran algo de manipulación si se las acostumbra despacio, pero otras prefieren que no las toquen casi nunca. El vínculo con la familia se construye respetando sus tiempos, no forzando contacto. Los niños pueden disfrutar mucho observándolo, pero el manejo directo siempre necesita supervisión de un adulto, porque un reptil estresado puede morder o defenderse, y porque después de tocarlo hay que lavarse las manos siempre.','Va de unos pocos centímetros hasta más de un metro, según la especie y el tipo. Es un rango enorme y hay que informarse puntualmente sobre el ejemplar de la casa, porque el tamaño adulto define el terrario, el manejo y hasta la alimentación.','También varía muchísimo: hay reptiles que viven unos pocos años y otros que acompañan a la familia por décadas. Depende del tipo y de la especie puntual, así que conviene averiguarlo antes de decidir tenerlo, pensando en un compromiso a largo plazo.','{}','{"cachorro": "En la etapa temprana el punto clave es la temperatura y la humedad del espacio donde vive. Un reptil joven necesita un terrario bien armado desde el principio, con una zona de calor y una de sombra, para poder regular su temperatura corporal moviéndose entre ambas. La alimentación en esta etapa suele ser más frecuente y hay que informarse bien sobre qué come esa especie en particular, porque hay herbívoros, carnívoros y omnívoros, y las diferencias son grandes. El manejo tiene que ser mínimo y calmo, para que se acostumbre a la presencia humana sin estresarse. Cualquier cambio de color en la piel, falta de apetito sostenida o letargo que no se explique por la muda hay que consultarlo con el veterinario.", "adulto": "Ya con su tamaño y hábitos establecidos, lo esencial sigue siendo mantener el terrario con la temperatura, la humedad y la iluminación adecuadas para esa especie, porque de eso depende su digestión, su piel y su sistema inmune. La dieta se estabiliza pero hay que respetar la frecuencia y el tipo de alimento que le corresponde, evitando la sobrealimentación. La limpieza del espacio es central para evitar enfermedades, ya que muchos reptiles son sensibles a la humedad estancada o la falta de higiene. El manejo puede ser más frecuente si el animal lo tolera bien, pero siempre leyendo sus señales de incomodidad. Cambios en la piel, en el apetito, en las heces o en el comportamiento habitual son motivo de consulta veterinaria.", "senior": "En la etapa avanzada muchos reptiles bajan su nivel de actividad y pueden necesitar ajustes en la temperatura o en la frecuencia de alimentación, siempre con guía veterinaria porque cada especie envejece distinto. Hay que estar más atento a la piel, a las articulaciones y a la facilidad para moverse dentro del terrario, adaptando el espacio si hace falta para que le resulte más accesible. Los controles veterinarios periódicos se vuelven más importantes en esta etapa, y cualquier señal de deterioro que no sea la normal del paso del tiempo conviene consultarla a tiempo."}'::jsonb,'claude-sonnet-5','2026-09-06T00:21:38.664Z'::timestamptz)
on conflict (especie, raza_codigo) do update set
  conocida = excluded.conocida, origen = excluded.origen,
  temperamento = excluded.temperamento, talla_adulta = excluded.talla_adulta,
  esperanza_vida = excluded.esperanza_vida,
  predisposiciones = excluded.predisposiciones,
  cuidados_por_etapa = excluded.cuidados_por_etapa,
  modelo = excluded.modelo, generado_el = excluded.generado_el
where not public.razas_contenido.conocida and not public.razas_contenido.activo;
commit;
